CREATE      PROCEDURE [dbo].[A_SP_Z_SYSTEM_TASKS_MAKE_A_SYSTEM_TASK]
@id varchar(50),
@name nvarchar(50),
@strNTLogin varchar(50)
as
declare @myCo varchar(50)
SELECT @myCO = ROOT_COMPANY FROM A_V_PEOPLE_APPROVED_DATA WHERE ID = @strNTLogin
if EXISTS(SELECT * FROM A_O_PROCEDURES WHERE CREATING_CO = @myCo AND SYSTEM_ID = @id) goto fin
print 'Inserting into the proc hist table'
declare @newID as varchar(50)
exec sp_GetUniqueID3 @newID OUTPUT
INSERT INTO A_PROCEDURES_HISTORY (ID,SYSTEM_ID,NAME,SECURITY_LEVEL,DRCM,MODBY,IS_SYSTEM)
VALUES (@newID,@id,@name,'5',getDate(),@strNTLogin,1)
declare @eacObj as varchar(50)
SELECT @eacObj = OBJECT_ID FROM A_PROCEDURES_HISTORY WHERE ID = @newID
print 'Object ID  = ' + isNull(@eacObj,'NULL')
print 'Setting status to approved and locked by to null'
UPDATE A_OBJECTS SET STATUS = 'APPROVED', LOCKED_BY = NULL WHERE ID = @eacObj
print 'Finishing the wf now'
exec A_SP_PROCEDURES_FINISH_WF @newid,@eacObj,@strNTLogin

fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_Z_SYSTEM_PROCEDURE_ADD_NEW_ONE_FOR_ALL_COMPANIES]    Script Date: 6/3/2019 2:03:07 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO





CREATE     PROCEDURE [dbo].[A_SP_Z_SYSTEM_PROCEDURE_ADD_NEW_ONE_FOR_ALL_COMPANIES]
@id varchar(50),
@NAME nvarchar(200)
AS
BEGIN TRANSACTION
print 'Inside A_SP_Z_SYSTEM_PROCEDURE_ADD_NEW_ONE_FOR_ALL_COMPANIES'
Declare @it nvarchar(50),@coName varchar(1000)
Declare @curs Cursor
declare @strNTLogin varchar(50)
set @curs = Cursor For SELECT ID,NAME FROM A_V_COMPANIES_APPROVED_DATA WHERE PARENT is NULL
open @curs
Fetch Next from @curs Into @it,@coName
while (@@fetch_status = 0)
Begin
	print 'Adding System Procedure for Company = ' + @coName
	set @strNTLogin = NULL
	SELECT TOP 1 @strNTLogin = ID FROM A_V_PEOPLE_APPROVED_DATA WHERE ROOT_COMPANY = @it
	if @strNTLogin is null
		begin
			print 'There was nobody with the company ' + @coName
			SELECT TOP 1 @strNTLogin = ID FROM A_V_PEOPLE_APPROVED_DATA WHERE ROOT_COMPANY = @it
		end
	if @strNTLogin is null
		begin
			print 'There was nobody in this company at all so I can not make this system Task'
			goto skip
		end 
	print 'Wanted to call A_SP_Z_SYSTEM_TASKS_MAKE_A_SYSTEM_TASK ''' + @id + ''',''' + @name + ''',''' + @strNTLogin + ''''
	exec A_SP_Z_SYSTEM_TASKS_MAKE_A_SYSTEM_TASK @id,@name,@strNTLogin
	skip:
	Fetch Next from @curs Into @it,@coName
End
close @curs
Deallocate @curs

if @@ERROR <> 0 GOTO PROBLEM
fin:
COMMIT TRANSACTION
RETURN 0
PROBLEM:
ROLLBACK TRANSACTION
RETURN 1
GO

/****** Object:  StoredProcedure [dbo].[A_SP_Z_SPLIT]    Script Date: 6/3/2019 2:03:07 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO




CREATE   proc [dbo].[A_SP_Z_SPLIT]
@i varchar(8000), --input string
@del varchar(8000) = ',' --delimiter
as
set nocount on
declare 
@p int,
@p2 int,
@tok varchar(8000)

CREATE TABLE #TempItems
	(
	IT varchar(1000)
	)

set @p=1

if (CHARINDEX(@del,@i,@p)=0)
begin
  exec('INSERT INTO #TempItems (IT) values (ltrim('''+@i+'''))')
end
else
begin
  while CHARINDEX(@del,@i,@p)>0
  begin
    set @p2 = CHARINDEX(@del,@i,@p)
    set @tok = SUBSTRING(@i,@p,@p2-@p)
    if Len(@tok)>0
      exec('INSERT INTO  #TEMPITEMS (IT) values (ltrim('''+@tok+'''))')
    set @p = @p2+Len(@del)
  end
  if @p<=Len(@i)
  begin
    set @tok = SUBSTRING(@i,@p,Len(@i)-(@p-1))
      exec('INSERT INTO  #TEMPITEMS (IT) values (ltrim('''+@tok+'''))')
  end
end
SELECT * FROM #TEMPITEMS
set nocount off
GO

/****** Object:  StoredProcedure [dbo].[A_SP_Z_PROJECTS_PURPOSES_AND_OBJECTS_SEARCH]    Script Date: 6/3/2019 2:03:08 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO




CREATE    PROCEDURE [dbo].[A_SP_Z_PROJECTS_PURPOSES_AND_OBJECTS_SEARCH]
@strList varchar(4000),
@strType varchar (50),
@strSearchType varchar (100),
@strAlias varchar (20),
@sql varchar (8000) output,
@strNTLogin varchar (50)
AS 
CREATE TABLE #TempItems (IT varchar(50))
INSERT INTO #TempItems Exec A_SP_Z_SPLIT @strList,','
Declare @it nvarchar(50)
Declare @curs Cursor
set @curs = Cursor For SELECT * FROM #TempItems
open @curs
Fetch Next from @curs Into @it
while (@@fetch_status = 0)
Begin
 print 'Adding a search for this tag = ' + @it
 set @sql = @sql + 'AND EXISTS (SELECT ID FROM '
 if @strSearchType = 'OBJECT' set @sql = @sql + ' A_OBJECT_ITEM_LINK '
 if @strSearchType = 'PURPOSES' set @sql = @sql + ' A_BUSINESS_PURPOSES_ITEM_LINK '
 if @strSearchType = 'PROJECT' set @sql = @sql + ' A_PROJECT_ITEM_LINK '
 set @sql = @sql + ' WHERE ITEM_TYPE = ''' + @strType + ''' AND ITEM_ID = ' + @strAlias + '.ID AND '
 if @strSearchType = 'OBJECT' set @sql = @sql + ' OBJECT_ID '
 if @strSearchType = 'PURPOSES' set @sql = @sql + ' BUSINESS_PURPOSE_ID '
 if @strSearchType = 'PROJECT' set @sql = @sql + ' PROJECT_ID '
 set @sql = @sql + ' = ''' + ltrim(@it) + ''')'
 Fetch Next from @curs Into @it
End
close @curs
Deallocate @curs
GO

