CREATE           PROCEDURE [dbo].[A_SP_THEORY_SELECT_FOR_THEORY_PARAGRAPHS]
@strWhere nvarchar(2000),
@strParagraphWhere nvarchar(2000),
@strSort nvarchar(1000),
@strNTLogin nvarchar(50)
AS
declare @myWhere as nvarchar(2000)
--find out my Company
declare @myCO as nvarchar(50)
exec A_SP_GET_PERSON_COMPANY @strNTLogin,@myCO OUTPUT

declare @mySecurityLevel as nvarchar(50)
exec A_SP_SECURITY_LEVEL_GET_FOR_PERSON @mySecurityLevel OUTPUT,@strNTlogin
print 'Searchers Sec Level is ' + @mySecurityLevel

--first let me see all theory I am editing
--set @myWhere = '' + ' ((LOCKED_BY = ''' + @strNTLogin + ''') '
--next if my co wrote it it is approved and I have sec level to see it
--set @myWhere = @myWhere + 'OR (CREATING_CO = ''' + @myCO + ''' AND STATUS LIKE ''APPROVED%'' AND SECURITY_LEVEL <= ' + @mySecurityLevel + ')' 
--If the security level is 5 then show this in the select screen
--set @myWhere = @myWhere + ' OR (SECURITY_LEVEL = 5) ' 
--set @myWhere = @myWhere + ')'

declare @sql nvarchar(4000)

if @strParagraphWhere is NULL
	begin
		print 'Paragraph Where is NULL'
		set @sql = 'SET QUOTED_IDENTIFIER OFF SELECT ID,NAME,CREATING_CO_NAME,ROOT AS SEND_ID,ROOT AS ROOT,STATUS
		FROM A_O_THEORY '
		if len(@strWhere) > 0
			set @sql = @sql + 'WHERE STATUS LIKE ''APPROVED%'' AND CREATING_CO = ''' + @myCo + ''' AND '+ @strWhere + ' '
		if len(@strSort) > 0
			set @sql = @sql + @strSort
		print @sql
	end
else
	begin
		print 'Paragraph Where is not null'
		set @sql = 'SET QUOTED_IDENTIFIER OFF SELECT ID,NAME,CREATING_CO_NAME,ROOT AS SEND_ID,ROOT AS ROOT,STATUS
		FROM A_O_THEORY_WITH_PARAGRAPHS '
		if len(@strWhere) > 0
			set @sql = @sql + 'WHERE STATUS LIKE ''APPROVED%'' AND CREATING_CO = ''' + @myCo + ''' AND '+ @myWhere + ' AND ' + @strWhere + ' '
		if len(@strParagraphWhere) > 0
			set @sql = @sql + ' AND  ' + @strParagraphWhere + ' '
		if len(@strSort) > 0
			set @sql = @sql + @strSort
	end

print @sql
exec (@sql)
GO

/****** Object:  StoredProcedure [dbo].[A_SP_THEORY_SECTION_REORDER_COMMENTS]    Script Date: 6/3/2019 2:03:28 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


Create  procedure [dbo].[A_SP_THEORY_SECTION_REORDER_COMMENTS]
@ID as varchar(50),
@LOC as varchar(50)
AS
declare @curs as CURSOR,
	@it as varchar(50)
Declare @counter int  
set @counter =0
print 'Reordering the comments for the theory ' + @ID + 'AND LOC = ' + @LOC
set @curs = Cursor For 
SELECT ID FROM A_THEORY_COMMENTS WHERE THEORY_HIST_ID = @ID AND LOC = @LOC
	ORDER BY PRINT_ORDER
open @curs
Fetch Next from @curs Into @it
while (@@fetch_status = 0)
	Begin
	set @counter = @counter +1 
	print 'reordering= ' + @it
        print 'counter = ' + convert(varchar(50),@counter)	
	UPDATE A_THEORY_COMMENTS SET PRINT_ORDER = @counter WHERE ID = @it
 	Fetch Next from @curs Into @it
	End
close @curs
Deallocate @curs
GO

/****** Object:  StoredProcedure [dbo].[A_SP_THEORY_SEARCH]    Script Date: 6/3/2019 2:03:28 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO











CREATE               PROCEDURE [dbo].[A_SP_THEORY_SEARCH]
	@strWhere nvarchar(2000),
	@strParagraphWhere nvarchar(2000),
	@strSort nvarchar(1000),
	@strNTLogin nvarchar(50)
AS
declare @myWhere as nvarchar(2000)
--find out my Company
declare @myCO as nvarchar(50)
exec A_SP_GET_PERSON_COMPANY @strNTLogin,@myCO OUTPUT

declare @mySecurityLevel as nvarchar(50)
exec A_SP_SECURITY_LEVEL_GET_FOR_PERSON @mySecurityLevel OUTPUT,@strNTlogin
print 'Searchers Sec Level is ' + @mySecurityLevel

--first let me see all theory I or my subordinates are created
set @myWhere = '' + '( (LOCKED_BY = ''' + @strNTLogin + ''') OR (CREATED_BY = ''' + @strNTLogin + ''') OR (CREATED_BY IN (SELECT SUBORDINATE FROM A_PEOPLE_SUB_LOOKUP_TABLE WHERE BOSS = ''' + @strNTLogin + '''))'
--next if my co wrote it and it is approved and I have sec level to see it
set @myWhere = @myWhere + 'OR (CREATING_CO = ''' + @myCO + ''' AND STATUS LIKE ''APPROVED%'' AND SECURITY_LEVEL <= ' + @mySecurityLevel + ')' 
--If the security level is 5 then never show this in the search only in the select screen
set @myWhere = @myWhere + ' AND (SECURITY_LEVEL <> 5) '
--put the roles in too
set @myWhere = @myWhere + ' OR  '
set @myWhere = @myWhere + ' exists ( SELECT ID FROM A_THEORY_ROLES_ALLOWED tra WHERE tra.THEORY_ID = A_V_THEORY_HISTORY_SEARCH.ID AND  '
set @myWhere = @myWhere + ' tra.ROLE_ID IN (SELECT ROLE_ID FROM A_PERSON_ROLES WHERE PERSON_ID = ''' + @strNTLogin + ''' )) '



set @myWhere = @myWhere + ')'

declare @sql nvarchar(4000)

if @strParagraphWhere is NULL
	begin
		set @sql = 'SET QUOTED_IDENTIFIER OFF SELECT *
		FROM A_V_THEORY_HISTORY_SEARCH '
		if len(@strWhere) > 0
			set @sql = @sql + 'WHERE '+ @myWhere + ' AND '  + @strWhere + ' '
		if len(@strSort) > 0
			set @sql = @sql + @strSort
	end
else
	begin
		set @sql = 'SET QUOTED_IDENTIFIER OFF SELECT DISTINCT SPECIAL_ROOT,SPECIAL_ID,ID,OBJECT_ID,SECURITY_LEVEL,
		CREATING_DEPT,OBJ_ID,LOCKED_BY,CREATED_BY,ROOT,CREATING_CO,
		NAME,CREATING_CO_NAME,DEPT_NAME,REV,STATUS,LOCKED_BY_NAME,DEPT_NAME,SECURITY_NAME,APPROVAL_DATE
		FROM A_O_THEORY_WITH_PARAGRAPHS A_V_THEORY_HISTORY_SEARCH '
		if len(@strWhere) > 0
			set @sql = @sql + 'WHERE '+ @myWhere + ' AND ' + @strWhere + ' '
		if len(@strParagraphWhere) > 0
			set @sql = @sql + ' AND  ' + @strParagraphWhere + ' '
		if len(@strSort) > 0
			set @sql = @sql + @strSort
	end

print @sql
exec (@sql)
GO

