/****** Object:  StoredProcedure [dbo].[A_SP_THEORY_FINISH_WF]    Script Date: 6/3/2019 2:03:37 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO








CREATE              PROCEDURE [dbo].[A_SP_THEORY_FINISH_WF]
	@myID nvarchar(50),
	@objID nvarchar(50),
	@strNTLogin nvarchar(50)
as
print 'Finishing the wf for a Theory with ObjectID = ' + isNull(@objID,'Fin Null')
declare @myRoot as nvarchar(50) --get the root which is the ID of A_THEORY
declare @ID as nvarchar(50) --get my ID  in the A_THEORY_HISTORY table
SELECT @myRoot = ROOT,@ID = OBJ_ID FROM A_OBJECTS WHERE ID = @objID
declare @tester as nvarchar(50) --Test to see if it is in the table
SELECT @tester = ID FROM A_THEORY WHERE ID = @myRoot 
if @tester is Null --it is not in there so add it
	begin
		print 'tester was null so i need to go ahead and make a record'
		INSERT INTO A_THEORY(ID,HISTORY_REF_ID,DRCM,MODBY) VALUES (@myRoot,@ID,getDate(),@strNTLogin)
	end
--so now make sure that the value in A_THEORY is Approved
declare @curID as nvarchar(50)
SELECT @curID = OBJ_ID FROM A_OBJECTS WHERE ROOT = @myROOT AND STATUS IN
('APPROVED','APPROVED_BUT_REVISING','APPROVED_BUT_DELETING')
exec A_SP_UPDATE_TABLE_FIELD @curID,@myRoot,'A_THEORY','HISTORY_REF_ID'

print 'The Workflow is finished.  Now we need to create the E-Access Product if there is not one'
--exec A_SP_THEORY_CREATE_E_ACCESS_PRODUCT @myRoot,@strNTLogin
GO

