/****** Object:  StoredProcedure [dbo].[A_SP_THEORY_COMMENT_UPDATE_ONE_COMMENT]    Script Date: 6/3/2019 2:03:39 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
