CREATE            PROCEDURE [dbo].[A_SP_TASKS_UPDATE_DATA] 
@ID as varchar(50),
@MODBY as varchar(50)
AS

--print ' Updating all the task information'
--print 'We need to set the original Requestor of this task'
declare @origReq as varchar(50)
SELECT top 1 @origReq = REQUESTOR  FROM A_TASK_ASSIGNEE WHERE TASK_ID = @ID ORDER BY REQUEST_DATE
--print 'The original Requestor for this task was' + @origReq
UPDATE A_TASKS SET ORIG_REQUESTOR_ID = @origReq WHERE ID = @ID

--print 'Get the current person who has accepted the task'
declare @accPer as varchar(50)
declare @accRole as varchar(50)
SELECT @accPer = PERSON_ASSIGNED,@accRole = ROLE_TASK_ACCEPTED_UNDER FROM A_TASK_ASSIGNEE WHERE TASK_ID = @ID AND ASSIGNEE_CURRENTLY_ACCEPTED = 1
if @accPer is null
	begin
--		print 'No Person is the current accepted assignee of this task'
--		print 'So get the latest requested Role for this task'
		SELECT @accRole = ROLE_ASSIGNED FROM A_TASK_ASSIGNEE WHERE TASK_ID = @ID AND ACTIVE = 1
		if @accRole is null
			begin
--			print 'There is no Role requested, so we need to get the persons id'
			SELECT @accPer = PERSON_ASSIGNED FROM A_TASK_ASSIGNEE WHERE TASK_ID = @ID AND ACTIVE = 1
			end
	end
--print 'Now we have the data...  person = ' + isNull(@accPer,'Null') + ' role = ' + isNull(@accRole,'Null')
--print 'Now to get the names'
declare @accRoleName as nvarchar(200)
declare @comboNAme as nvarchar(200)
if @accRole is not null
	begin
--		print 'Get the Role Name First'
		SELECT @accRoleName = NAME FROM A_V_ROLE_DATA_BY_APPROVED_ID WHERE ID = @accRole
		set @comboname = @accRoleName
	end
declare @accPerName as nvarchar(200)
if @accPer is not null
	begin
--		print 'Now add the person'
		SELECT @accPerName = P_NAME FROM A_V_PEOPLE_BY_NTLOGIN WHERE P_ID = @accPer
		set @comboName = isNull(@comboname + ' - ','') + @accPerName
	end
declare @curReqName as nvarchar(200)
SELECT @curReqName = LATEST_REQUESTEE_NAME FROM A_TASKS WHERE ID = @ID
if isNull(@curReqName,'') != isNull(@comboName,'')
	begin
	UPDATE A_TASKS SET LATEST_REQUESTEE_NAME = @comboName WHERE ID = @ID
	end

--print 'Checking the surveys'
declare @surTest as varchar(50)
SELECT @surTest  = ID FROM A_TASK_SURVEY_LINK WHERE TASK_ID = @ID
declare @curSurState as smallint
SELECT @curSurState = HAS_SURVEY FROM A_TASKS WHERE ID = @ID
if @surTest is not null
	begin
--	print 'This one has a survey'
	if  isnull(@curSurState,'') != 1 
		begin
		UPDATE A_TASKS SET HAS_SURVEY = 1 WHERE ID = @ID
		end
	end
else
	begin
--	print 'This one does not has a survey'
	if isnull(@curSurState,'') != 0
		begin
		UPDATE A_TASKS SET HAS_SURVEY = 0 WHERE ID = @ID
		end
	end
declare @discTest as varchar(50)
SELECT @discTest  = ID FROM A_TASK_DISCUSSION_LINK WHERE TASK_ID = @ID
declare @curDiscState as smallint
SELECT @curDiscState = HAS_DISCUSSION FROM A_TASKS WHERE ID = @ID
if @discTest is not null
	begin
--	print 'This one has a discussion'
	if isnull(@curDiscState,'') != 1 
		begin
		UPDATE A_TASKS SET HAS_DISCUSSION = 1 WHERE ID = @ID
		end
	end
else
	begin
--	print 'This one does not has a discussion'	
	if isnull(@curDiscState,'') != 0
		begin
		UPDATE A_TASKS SET HAS_DISCUSSION = 0 WHERE ID = @ID
		end
	end
declare @childTest as varchar(50)
SELECT @childTest  = ID FROM A_TASKS WHERE PARENT_ID = @ID
declare @curChildState as smallint
SELECT @curChildState = HAS_CHILD FROM A_TASKS WHERE ID = @ID
if @childTest is not null
	begin
--	print 'This one have child'
	if isnull(@curChildState,'') != 1 
		begin
		UPDATE A_TASKS SET HAS_CHILD = 1 WHERE ID = @ID
		end
	end
else
	begin
--	print 'This one does not have child'	
	if isnull(@childTest,'') != 0
		begin
		UPDATE A_TASKS SET HAS_CHILD = 0 WHERE ID = @ID
		end
	end

declare @procedureTest as varchar(50)
SELECT @procedureTest  = ID FROM A_TASK_REFERENCE_PROCEDURES WHERE TASK_ID = @ID
declare @curProcState as smallint
SELECT @curProcState = HAS_REF_PROC FROM A_TASKS WHERE ID = @ID
if @procedureTest is not null
	begin
--	print 'This one have child'
	if isnull(@curProcState,'') != 1 
		begin
		UPDATE A_TASKS SET HAS_REF_PROC = 1 WHERE ID = @ID
		end
	end
else
	begin --	print 'This one does not have child'	
	if isnull(@curProcState,'') != 0
		begin
		UPDATE A_TASKS SET HAS_REF_PROC = 0 WHERE ID = @ID
		end
	end

declare @objTest as varchar(50)
SELECT @objTest  = ID FROM A_TASK_OBJECT_LINK WHERE TASK_ID = @ID
declare @curObjState as smallint
SELECT @curObjState = HAS_REF_OBJ FROM A_TASKS WHERE ID = @ID
if @objTest is not null
	begin
--	print 'This one has an object'
	if isnull(@curObjState,'') != 1 
		begin
		UPDATE A_TASKS SET HAS_REF_PROC = 1 WHERE ID = @ID
		end
	end
else
	begin
--	print 'This one does not have Object'	
	if isnull(@curObjState,'') != 0
		begin
		UPDATE A_TASKS SET HAS_REF_PROC = 0 WHERE ID = @ID
		end
	end

declare @fileTest as varchar(50)
SELECT @fileTest  = ID FROM A_TASK_REF_FILES WHERE TASK_ID = @ID
declare @curFileState as smallint
SELECT @curFileState = HAS_FILE FROM A_TASKS WHERE ID = @ID
if @fileTest is not null
	begin
--	print 'This one has a File'
	if isnull(@curFileState,'') != 1 
		begin
		UPDATE A_TASKS SET HAS_FILE = 1 WHERE ID = @ID
		end
	end
else
	begin
--	print 'This one does not have a File'	
	if isnull(@curFileState,'') != 0
		begin
		UPDATE A_TASKS SET HAS_FILE = 0 WHERE ID = @ID
		end
	end

declare @monTest as varchar(50)
SELECT @monTest  = ID FROM A_MONITOR_TEMPLATES WHERE TASK_ID = @ID
declare @curMonState as smallint
SELECT @curMonState = HAS_MONITOR FROM A_TASKS WHERE ID = @ID
if @monTest is not null
	begin
--	print 'This one has a Monitor'
	if isnull(@curMonState,'') != 1 
		begin
		UPDATE A_TASKS SET HAS_MONITOR = 1 WHERE ID = @ID
		end
	end
else
	begin
--	print 'This one does not have a Monitor'	
	if isnull(@curMonState,'') != 0
		begin
		UPDATE A_TASKS SET HAS_MONITOR = 0 WHERE ID = @ID
		end
	end


declare @actStartDate datetime,@parentID varchar(50),@parentStartDate dateTime
SELECT @actStartDate = ACTUAL_START_DATE,@parentID = PARENT_ID FROM A_TASKS WHERE ID = @ID
SELECT @parentStartDate = ACTUAL_START_DATE FROM A_TASKS WHERE ID = @parentID
if @parentStartDate is null and @actStartDate is not null
	begin
	UPDATE A_TASKS SET ACTUAL_START_DATE = @actStartDate WHERE ID = @parentID
	end
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASKS_TAKE_BACK_TASK]    Script Date: 6/3/2019 2:03:41 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO






CREATE     PROCEDURE [dbo].[A_SP_TASKS_TAKE_BACK_TASK]
@newID nvarchar(50) OUTPUT,
@messages nvarchar(2000) OUTPUT,
@ID nvarchar(50),
@strNTLogin varchar(50)
AS

print 'Taking Back a Task'

print 'Making sure this is the person who Originally Requested it'
declare @TESTER as varchar(50)
SELECT @TESTER = ID FROM A_TASKS WHERE ORIG_REQUESTOR_ID = @strNTLogin and ID = @ID
if @TESTER is null
	begin
	print 'This is not yours to Take Back'
	set @newID = 'Not yours to Take Back'
	goto fin
	end

print 'I am going to take it back this'
print 'Get the current Active Task Assignee'
declare @curID as varchar(50)
SELECT @curID = ID FROM A_TASK_ASSIGNEE WHERE TASK_ID = @ID AND ACTIVE = '1'
if @curID is NULL
	begin
	print 'I can not find the current Active Task Assignee'
	set @newID = 'I can not find the current Active Task Assignee'
	goto fin
	end

exec A_SP_TASK_SEND_EMAIL_UPDATE @ID,'takenBack',@strNTLogin
print 'Set the old one to ReAssigned and inactive'
UPDATE A_TASK_ASSIGNEE SET STATUS = 'TAKEN_BACK', ACTIVE = 0,ASSIGNEE_CURRENTLY_ACCEPTED = 0 WHERE ID = @curID
print 'Now insert a new one into A_TASK_ASSIGNEE '
INSERT INTO A_TASK_ASSIGNEE (ID,TASK_ID,PERSON_ASSIGNED,ROLE_ASSIGNED,REQUEST_DATE,DRCM,MODBY,ACTIVE,STATUS,
REQUESTOR)
VALUES (newID(),@ID,@strNTLogin,NULL,getDate(),getDate(),@strNTLogin,'1','REQUESTED',@strNTLogin)

exec A_SP_TASK_SET_REQUESTEE_FROM_ASSIGNEE_TABLE @ID,@strNTLogin
exec A_SP_TASKS_UPDATE_DATA @ID, @strNTlogin
exec A_SP_TASK_AUTO_ACCEPT @ID,@strNTLogin
fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASKS_SEARCH]    Script Date: 6/3/2019 2:03:41 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO













/*
STORED PROCEDURE CALL: 
- MODULE: AnswerAlpha\asp/ActualTasks/searchTasks.asp
*/
CREATE                                          PROCEDURE [dbo].[A_SP_TASKS_SEARCH]
@fieldList nvarchar(4000),
@alias nvarchar(50),
@strWHERE nvarchar(4000),
@strPurposes varchar(4000),
@strObjects varchar(4000),
@strProjects varchar(4000),
@strSort nvarchar(500),
@strNTLogin nvarchar(50)
as

declare @isStandardSearch int
set @isStandardSearch = 0
if @fieldList is null
	begin
		print 'The field list is so null so we know this a standard search from searchDiscussions.asp'
		set @isStandardSearch =1
	end


--build the sql for the query
declare @sql as nvarchar(4000)
declare @myCo varchar(50)

SELECT @myCo = COMPANY 
FROM A_APPROVED_PEOPLE 
WHERE ID=@strNTLogin


--dbo.A_FN_TASK_GET_STANDARD_SQL_STRING(@fieldList,@alias,@strNTlogin)

if @fieldList = '' or @fieldList is NULL 
begin

set @fieldList = 'DISTINCT ID, 
				SORT_ID, 
                DESCRIPTION, 
                STATUS, 
                REQUESTOR, 
                CHILD_ORDER, 
                CREATED_BY, 
                CREATE_DATE, 
                SYSTEM_TASK, 
                PROCEDURE_ID, 
                REQUESTEE_ID, 
                GROUP_REQUESTEE_ID, 
                ORIG_PLANNED_START_DATE, 
                ORIG_PLANNED_STOP_DATE, 
                CUR_PLANNED_START_DATE, 
                CUR_PLANNED_STOP_DATE, 
                ACTUAL_START_DATE, 
                ACTUAL_STOP_DATE, 
                CUR_PLANNED_COUNTER_START, 
                LATEST_REQUESTEE_NAME, 
                HAS_DISCUSSION, 
                HAS_SURVEY, 
                HAS_CHILD, 
                HAS_REF_PROC, 
                HAS_FILE, 
                ORIG_REQUESTOR_ID, 
                HAS_REF_OBJ, 
                HAS_MONITOR, 
                ORIG_REQUESTOR_NAME, 
                COLOR_CODE,
				LAST_REQUEST_DATE,
				PARENT_ID,
				PARENT_LIST,
				isParent,
				PRIORITY,
				PRIORITY_NAME, 
				COMPANY_NAME,
				CHILD_STATUS,
				PROCEDURE_STEP_ID, 
				LAST_COMMENT_WRITER,
				LAST_COMMENT_DRCM,
				LAST_COMMENT,
				IS_QUOTE,
				IS_QUOTE_ACCEPT,
				IS_FILL,
				CO_ID,
				FILL_ID,
				PURCHASE_ITEM_ID,
				PURCHASE_HIST_ID,
				PURCHASE_ITEM_ROLE,
				ASSIGNEE_NAME,ASSIGNEE_ID,ASSIGNEE_STATUS '
 				

end


set @sql ='SELECT ' + @fieldList + ' FROM A_V_TASK_SEARCH ' + isNull(@alias,'') + ' '
--We need to add some standard security in here
set @sql = @sql + 'WHERE ('
--Requestee can see non creating 
set @sql = @sql + '(REQUESTEE_ID = ''' + @strNTLogin + ''' AND STATUS <> ''CREATING'')'
-- Add myCompany allowed to see and my child companies allowed to see
set @sql = @sql + ' OR (ALLOWED_CO_ID = ''' + @myCo + ''' AND STATUS <> ''CREATING'')' 
set @sql = @sql + ' OR (ALLOWED_CO_ID IN (SELECT CHILD_COMPANY FROM A_COMPANIES_CHILD_LOOKUP_TABLE WHERE COMPANY = ''' + @myCo + ''') AND STATUS <> ''CREATING'')'
-- Add Im specified to see
set @sql = @sql + ' OR (SPECIFIED_PERSON_ID = ''' + @strNTLogin + ''' AND STATUS <> ''CREATING'')' 
-- Add persons subbordinates
set @sql = @sql + ' OR (REQUESTEE_ID IN (SELECT SUBORDINATE FROM A_PEOPLE_SUB_LOOKUP_TABLE WHERE BOSS = ''' + @strNTLogin + ''') AND STATUS <> ''CREATING'')'
--Now check to see if our role is the one assigned..  we should see those
set @sql = @sql + ' OR (GROUP_REQUESTEE_ID IN (SELECT ROLE_ID FROM A_PERSON_ROLES WHERE PERSON_ID = ''' + @strNTLogin + ''')  AND STATUS <> ''CREATING'') '
--Now check to see if we Created this one
set @sql = @sql + ' OR (CREATED_BY = ''' + @strNTLogin + ''')'
set @sql = @sql + ' OR (ORIG_REQUESTOR_ID = ''' + @strNTLogin + ''') '
set @sql = @sql + ' OR (ASSIGNEE_ID IN (SELECT SUBORDINATE FROM A_PEOPLE_SUB_LOOKUP_TABLE WHERE BOSS = ''' + @strNTLogin + ''') AND STATUS <> ''CREATING'')'
--We still need more security here about invited companies and security clearance levels
--end the Security 
set @sql = @sql + ')'


set @sql = @sql + ' AND ' +  @strWhere


if @isStandardSearch = 1  
	begin
	exec A_SP_Z_PROJECTS_PURPOSES_AND_OBJECTS_SEARCH
		@strPurposes,'A_TASKS','PURPOSES','S', @sql output, @strNTLogin
	exec A_SP_Z_PROJECTS_PURPOSES_AND_OBJECTS_SEARCH
		@strObjects,'A_TASKS','OBJECT', 'S', @sql output, @strNTLogin
	exec A_SP_Z_PROJECTS_PURPOSES_AND_OBJECTS_SEARCH
		@strProjects,'A_TASKS','PROJECT', 'S', @sql output, @strNTLogin
	end 

if len(@strSort) > 0
	begin
	  set @sql = @sql + @strSort
	end

print 'SQL = ' + @SQL
EXEC(@SQL)
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASKS_REASSIGN_TASK]    Script Date: 6/3/2019 2:03:41 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO








CREATE      PROCEDURE [dbo].[A_SP_TASKS_REASSIGN_TASK]
@newID nvarchar(50) OUTPUT,
@messages nvarchar(2000) OUTPUT,
@ID nvarchar(50),
@REQUESTEE_ID varchar(50),
@GROUP_REQUESTEE_ID varchar(50),
@COMMENTS nvarchar(4000),
@strNTLogin varchar(50)
AS
print 'ReAssigning a Task'

print 'Making sure this is the person who Originally Requested it'
declare @TESTER as varchar(50)
SELECT @TESTER = ID FROM A_TASKS WHERE ORIG_REQUESTOR_ID = @strNTLogin and ID = @ID
if @TESTER is null
	begin
	print 'This is not yours to reAssign'
	set @newID = 'Not yours to reAssign'
	goto fin
	end
if (@REQUESTEE_ID is not null) and (@GROUP_REQUESTEE_ID is not null)
	begin
	print 'Assigned both a group and a person exiting'
	set @newID = 'Assigned to both a person and a group does not work'
	goto fin
	end

print 'I am going to reassign this'
print 'Get the current Active Task Assignee'
declare @curID as varchar(50)
SELECT @curID = ID FROM A_TASK_ASSIGNEE WHERE TASK_ID = @ID AND ACTIVE = '1'
if @curID is NULL
	begin
	print 'I can not find the current Active Task Assignee'
	set @newID = 'I can not find the current Active Task Assignee'
	goto fin
	end
print 'Set the old one to ReAssigned and inactive'
UPDATE A_TASK_ASSIGNEE SET STATUS = 'REASSIGNED', ACTIVE = 0,ASSIGNEE_CURRENTLY_ACCEPTED = 0 WHERE ID = @curID
print 'Now insert a new one into A_TASK_ASSIGNEE '
INSERT INTO A_TASK_ASSIGNEE (ID,TASK_ID,PERSON_ASSIGNED,ROLE_ASSIGNED,REQUEST_DATE,DRCM,MODBY,ACTIVE,STATUS,
REQUESTOR)
VALUES (newID(),@ID,@REQUESTEE_ID,@GROUP_REQUESTEE_ID,getDate(),getDate(),@strNTLogin,'1','REQUESTED',@strNTLogin)
print 'Adding the ReAssignment Comments to the comments box.'
UPDATE A_TASKS SET COMMENT = isNull(COMMENT,'') + char(13) + @COMMENTS WHERE ID = @ID

exec A_SP_TASK_SET_REQUESTEE_FROM_ASSIGNEE_TABLE @ID,@strNTLogin
exec A_SP_TASKS_UPDATE_DATA @ID, @strNTlogin
exec A_SP_TASK_AUTO_ACCEPT @ID,@strNTLogin

exec A_SP_TASK_SEND_EMAIL_UPDATE @ID,'reassigned',@strNTLogin


fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASKS_FORWARD_TASK]    Script Date: 6/3/2019 2:03:42 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO





CREATE      PROCEDURE [dbo].[A_SP_TASKS_FORWARD_TASK]
@newID nvarchar(50) OUTPUT,
@messages nvarchar(2000) OUTPUT,
@ID nvarchar(50),
@REQUESTEE_ID varchar(50),
@GROUP_REQUESTEE_ID varchar(50),
@strNTLogin varchar(50)
AS
print 'Forwarding a Task'

print 'Making sure this is the person assigned and accepted'
declare @TESTER as varchar(50)
SELECT @TESTER = ID FROM A_TASKS WHERE REQUESTEE_ID = @strNTLogin and ID = @ID
if @TESTER is null
	begin
	print 'This is not yours to forward'
	set @newID = 'Not yours to forward'
	goto fin
	end
if (@REQUESTEE_ID is not null) and (@GROUP_REQUESTEE_ID is not null)
	begin
	print 'Assigned both a group and a person exiting'
	set @newID = 'Assigned to both a person and a group does not work'
	goto fin
	end

print 'I am going to Forward this'
print 'Get the current Active Task Assignee'
declare @curID as varchar(50)
SELECT @curID = ID FROM A_TASK_ASSIGNEE WHERE TASK_ID = @ID AND ACTIVE = '1'
if @curID is NULL
	begin
	print 'I can not find the current Active Task Assignee'
	set @newID = 'I can not find the current Active Task Assignee'
	goto fin
	end
print 'Set the old Task Assignee to forwarded and inactive'
UPDATE A_TASK_ASSIGNEE SET STATUS = 'FORWARDED', ACTIVE = 0,ASSIGNEE_CURRENTLY_ACCEPTED = 0 WHERE ID = @curID
print 'Set the Task itself to have no assignee at all because we will get one later'
UPDATE A_TASKS SET REQUESTEE_ID = NULL, GROUP_REQUESTEE_ID = NULL WHERE ID = @ID
print 'Now insert a new one into A_TASK_ASSIGNEE '
INSERT INTO A_TASK_ASSIGNEE (ID,TASK_ID,PERSON_ASSIGNED,ROLE_ASSIGNED,REQUEST_DATE,DRCM,MODBY,ACTIVE,STATUS,
REQUESTOR)
VALUES (newID(),@ID,@REQUESTEE_ID,@GROUP_REQUESTEE_ID,getDate(),getDate(),@strNTLogin,'1','REQUESTED',@strNTLogin)

exec A_SP_TASK_SET_REQUESTEE_FROM_ASSIGNEE_TABLE @ID,@strNTLogin
exec A_SP_TASKS_UPDATE_DATA @ID, @strNTlogin
exec A_SP_TASK_AUTO_ACCEPT @ID,@strNTLogin
exec A_SP_TASK_SEND_EMAIL_UPDATE @ID,'forwarded',@strNTLogin
fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASKS_FOR_PURCH_ITEM_AND_PART_SHOW_ACTIVE_TASKS]    Script Date: 6/3/2019 2:03:42 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[A_SP_TASKS_FOR_PURCH_ITEM_AND_PART_SHOW_ACTIVE_TASKS]
@purchItem varchar(50),
@actPart varchar(50)
AS
create TABLE #tempTasks (ID varchar(50))
INSERT INTO #tempTasks 
	SELECT TASK_ID FROM A_TASK_ORDER_INFORMATION WHERE PURCHASE_ITEM_ID = @purchItem
INSERT INTO #tempTasks 
	SELECT ID FROM A_TASKS WHERE PARENT_ID IN 
	(SELECT ID FROM #tempTasks)

create TABLE #tempTasks2 (ID varchar(50))
if @actPart is not null
	begin
	INSERT INTO #tempTasks2
		SELECT TASK_ID FROM A_TASK_ACTUAL_PARTS_LINKED_WHEN_FINISHED WHERE ACTUAL_PART_ID = @actPart
	INSERT INTO #tempTasks2
		SELECT ID FROM A_TASKS WHERE PARENT_ID IN 
		(SELECT ID FROM #tempTasks2)
	end
else
	INSERT INTO #tempTasks2	SELECT ID FROM #tempTasks
	

SELECT DISTINCT 
[PARENT_ID], [STEP_ID], [DESCRIPTION], [STATUS], [REQUESTOR], [COMPLETED_BY], [PH_STEP_ID], 
[PRINT_ORDER], [RECURSION_NUMBER], [HAS_SURVEY], [HAS_CHILD], [HAS_REF_PROC], [HAS_FILE], 
[SYSTEM_TASK], [HAS_MONITOR] 
FROM A_V_TASKS_WITH_PROCEDURE_STEP_DATA 
	WHERE STEP_ID IN (SELECT t1.ID FROM #tempTasks t1,#tempTasks2 t2 WHERE t1.ID = t2.ID)
	AND STATUS IN ('REQUESTED','ACCEPTED')
ORDER BY PRINT_ORDER
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASKS_FIND_FOR_WORKER_BUTTONS]    Script Date: 6/3/2019 2:03:42 PM ******/
