CREATE          PROCEDURE [dbo].[A_SP_TASK_START_FOLLOWING_STEPS]
@ID varchar(50),
@strNTLogin varchar(50)
AS
if @ID is null goto fin
print 'In A_SP_TASK_START_FOLLOWING_STEPS'
print 'This occurs when a task is finished.  Updating following tasks'
declare @procedureID varchar(50),@procedureStepID varchar(50),@parentID varchar(50),@parentStatus varchar(50)
SELECT @procedureID = PROCEDURE_ID,@procedureStepID = PROCEDURE_STEP_ID,@parentID = PARENT_ID FROM A_TASKS WHERE ID = @ID
SELECT @parentStatus = STATUS FROM A_TASKS WHERE ID = @parentID
if @parentStatus in ('REQUESTED','CREATING')
	goto fin
print 'Proc ID = ' + isNull(@procedureID,'NULL')
declare @myRec as int
SELECT @myRec = RECURSION_NUMBER FROM A_TASKS WHERE ID = @ID


Declare @it nvarchar(50)
Declare @curs Cursor
set @curs = Cursor For 
SELECT ID FROM A_TASKS WHERE  PARENT_ID = @parentID AND RECURSION_NUMBER = @myRec and STATUS = 'PENDING_PARENT_ACCEPTANCE'
--AND
--		PROCEDURE_STEP_ID IN 
--			(SELECT ID FROM A_PROCEDURE_STEPS WHERE
--				 PROCEDURE_ID = 
--				(SELECT HISTORY_REF_ID FROM A_PROCEDURES WHERE ID = @procedureID) 
--			AND	
--				ID IN 
--				(SELECT MY_STEP FROM A_PROCEDURE_STEP_PRECEDING_STEPS WHERE PREV_STEP = @procedureStepID
--				)
--			)
			
declare @myStepID varchar(50),@myProcID varchar(50),@myParentID varchar(50)

open @curs
Fetch Next from @curs Into @it
while (@@fetch_status = 0)
	Begin
	print 'Looking at task = ' + @it
	if (SELECT STATUS FROM A_TASKS WHERE ID = @it) in ('PENDING_PARENT_ACCEPTANCE','Qued')
		begin
		SELECT 
			@myProcID = PROCEDURE_ID,
			@myParentID = PARENT_ID,
			@myStepID = PROCEDURE_STEP_ID 
		FROM A_TASKS WHERE ID = @it

		if not Exists(
			SELECT ID,STATUS FROM A_TASKS WHERE RECURSION_NUMBER = @myRec AND PARENT_ID = @myParentID AND STATUS NOT IN ('FINISHED','CLOSED') AND
				PROCEDURE_STEP_ID IN 
				(
					SELECT ID FROM A_PROCEDURE_STEPS WHERE PROCEDURE_ID = 
					(
						SELECT HISTORY_REF_ID FROM A_PROCEDURES WHERE ID = @myProcID
					) 
					AND	ID IN 
					(
						SELECT PREV_STEP FROM A_PROCEDURE_STEP_PRECEDING_STEPS WHERE MY_STEP = @myStepID
					)
				)
			)
			begin
				print 'It is time to execute this step'
				if exists(SELECT * FROM A_TASKS WHERE REQUESTEE_ID is NULL AND GROUP_REQUESTEE_ID IS NULL AND ID = @it)
					begin
					UPDATE A_TASKS SET REQUESTEE_ID = (SELECT REQUESTEE_ID  FROM A_TASKS WHERE ID = @ID) WHERE ID = @it
					exec A_SP_TASK_UPDATE_TASK_ASSIGNEE @it,@strNTLogin
					end
				exec A_SP_TASK_SUBMIT null,null,@it,@strNTLogin
			end
			else
				print 'Not time to execute yet'
		end
	Fetch Next from @curs Into @it
	End
close @curs

if exists(SELECT * FROM A_V_TASK_WITH_ORDER_INFORMATION 
			WHERE ID = @ID AND PURCHASE_ITEM_ROLE = 'TO_SHIP')
	begin
	print 'This was the ship to task so we should start all tasks that are not ship to tasks now'
	set @curs = Cursor For 
		SELECT ID FROM A_V_TASK_WITH_ORDER_INFORMATION 
			WHERE PARENT_ID = (SELECT PARENT_ID FROM A_TASKS WHERE ID = @ID)
				 AND PURCHASE_ITEM_ROLE = 'CHILD_PROC' 
					AND TASK_STATUS = 'PENDING_PARENT_ACCEPTANCE'
	open @curs
		Fetch Next from @curs Into @it
		while (@@fetch_status = 0)
			Begin
			print 'Found a task with number = ' + @it
			exec A_SP_TASK_SUBMIT null,null,@it,@strNTLogin
			Fetch Next from @curs Into @it
		End
	close @curs
	end


if exists(SELECT * FROM A_V_TASK_WITH_ORDER_INFORMATION 
			WHERE ID = @ID AND PURCHASE_ITEM_ROLE = 'CHILD_PROC')
	begin
	print 'This was the Procedure task so we should start the ship from task'
	set @curs = Cursor For 
		SELECT ID FROM A_V_TASK_WITH_ORDER_INFORMATION 
			WHERE PARENT_ID = (SELECT PARENT_ID FROM A_TASKS WHERE ID = @ID)
				 AND PURCHASE_ITEM_ROLE = 'FROM_SHIP' 
					AND TASK_STATUS = 'PENDING_PARENT_ACCEPTANCE'
	open @curs
		Fetch Next from @curs Into @it
		while (@@fetch_status = 0)
			Begin
			print 'Found a task with number = ' + @it
			exec A_SP_TASK_SUBMIT null,null,@it,@strNTLogin
			Fetch Next from @curs Into @it
		End
	close @curs
	end






Deallocate @curs

fin:
print 'Out Of A_SP_TASK_START_FOLLOWING_STEPS'
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASK_SET_REQUESTEE_FROM_ASSIGNEE_TABLE]    Script Date: 6/3/2019 2:03:49 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO








CREATE       PROCEDURE [dbo].[A_SP_TASK_SET_REQUESTEE_FROM_ASSIGNEE_TABLE]
@ID varchar(50),
@strNTlogin varchar(50)
AS
declare @PER as varchar(50)
declare @ROLE as varchar(50)
declare @REQ as varchar(50)
declare @REQ_DATE as varchar(50)
declare @STATUS as varchar(50)

SELECT @REQ_DATE = REQUEST_DATE,@STATUS = STATUS,@REQ = REQUESTOR, @PER = PERSON_ASSIGNED, @ROLE = ROLE_ASSIGNED FROM A_TASK_ASSIGNEE WHERE TASK_ID = @ID AND ACTIVE = 1
IF @PER is not null
	begin
	print 'The person is not null in the active task assignee row so setting the person to ' + @PER
	UPDATE A_TASKS SET REQUESTEE_ID = @PER, REQUESTOR = @REQ,DRCM = getDate(),MODBY = @strNTLogin WHERE ID = @ID
	end
IF @ROLE is not null
	begin
	print 'The Role is not null in the active task assignee row so setting the Role to ' + @ROLE
	UPDATE A_TASKS SET REQUESTEE_ID = NULL,GROUP_REQUESTEE_ID = @ROLE, REQUESTOR = @REQ,DRCM = getDate(),MODBY = @strNTLogin WHERE ID = @ID
	end

declare @curStat as varchar(50)
SELECT @curStat = STATUS FROM A_TASKS WHERE ID = @ID
if @STATUS = 'REQUESTED'
	begin
	if isNull(@curStat,'') != 'REQUESTED' 
		begin
		UPDATE A_TASKS SET 
		--STATUS = 'REQUESTED',
		DRCM = getDate(),MODBY = @strNTLogin WHERE ID = @ID
		end
	if @REQ_DATE is not null
		begin
		UPDATE A_TASKS SET LAST_REQUEST_DATE = @REQ_DATE WHERE ID = @ID
		end
	end
if @STATUS = 'ACCEPTED'
	begin
	if isNull(@curStat,'') = 'REQUESTED' --If it is not accepted or finished we need to update it
		begin
		UPDATE A_TASKS SET STATUS = 'ACCEPTED',DRCM = getDate(),MODBY = @strNTLogin WHERE ID = @ID
		end
	end

if @REQ_DATE is not null
	begin
	UPDATE A_TASKS SET LAST_REQUEST_DATE = @REQ_DATE WHERE ID = @ID
	end
else
	begin
	SELECT top 1 @REQ_DATE = REQUEST_DATE FROM A_TASK_ASSIGNEE WHERE TASK_ID = @ID AND REQUEST_DATE is not null ORDER BY REQUEST_DATE DESC 
	UPDATE A_TASKS SET LAST_REQUEST_DATE = @REQ_DATE WHERE ID = @ID
	end
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASK_SET_PROGRESS]    Script Date: 6/3/2019 2:03:49 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE     PROCEDURE [dbo].[A_SP_TASK_SET_PROGRESS]
@newID nvarchar(50) OUTPUT,
@messages nvarchar(2000) OUTPUT,
@ID nvarchar(50),
@ROOT_ID varchar(50),
@TASK_DONE_LIST varchar(8000),
@strNTLogin varchar(50)
AS
if @TASK_DONE_LIST is null
	goto fin
declare @retData as varchar(8000),@retID as varchar(50)
CREATE TABLE #TempItems	(IT varchar(50))
INSERT INTO #TempItems Exec A_SP_Z_SPLIT @TASK_DONE_LIST,'---'

if (exists(SELECT * FROM #TempItems WHERE IT = @ID) or (@ROOT_ID = @ID))
	begin
	print 'This one should be accepted and completed ' + @ID
 	if exists(SELECT * FROM A_TASKS WHERE ID = @ID and STATUS = 'REQUESTED')
 		exec A_SP_TASK_ACCEPT @retData OUTPUT,@retID OUTPUT,@ID,@strNTLogin
 	if not(exists(SELECT * FROM A_TASKS WHERE PARENT_ID = @ID))
 		exec A_SP_TASK_QUICK_CLOSE @retData OUTPUT,@retID OUTPUT,@ID,@strNTLogin
	end
declare @curs as cursor,@curID as varchar(50)
set @curs = CURSOR FOR SELECT ID FROM A_TASKS WHERE PARENT_ID = @ID ORDER BY dbo.leadingSpaces(ID,50)
open @curs
fetch next from @curs into @curID
while @@fetch_Status = 0
	begin
	exec A_SP_TASK_SET_PROGRESS @newID OUTPUT,@messages OUTPUT,
		@curID,@ROOT_ID,@TASK_DONE_LIST,@strNTLogin

	fetch next from @curs into @curID
	end 


fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASK_SEND_EMAIL_UPDATE]    Script Date: 6/3/2019 2:03:50 PM ******/
