CREATE      PROCEDURE [dbo].[A_SP_TASK_RESTART]
@newID varchar(200) OUTPUT,
@msgs varchar(200) OUTPUT,
@taskID varchar(50),
@strNTLogin varchar(50)
AS
declare @mainReq varchar(50)
print 'Restarting task ' + @taskID
UPDATE A_TASKS SET STATUS = 'REQUESTED' WHERE ID = @taskID
SELECT @mainReq = REQUESTOR FROM A_TASKS WHERE ID = @taskID
declare @curs as CURSOR, @it varchar(50)
set @curs = CURSOR FOR SELECT ID FROM A_TASKS WHERE PARENT_ID = @taskID
open @curs
fetch next from @curs into @it
while @@fetch_status = 0
	begin
	exec A_SP_TASK_DELETE_TASK_FOREVER @it,@mainReq
	fetch next from @curs into @it
	end 
deallocate @curs
exec A_SP_TASK_CREATE_CHILD_TASKS_FOR_PROCEDURE_STEPS @taskID,@mainReq
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASK_REQUEST_PURCHASE_TASK_IF_IT_IS_TIME]    Script Date: 6/3/2019 2:03:50 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO



CREATE   PROCEDURE [dbo].[A_SP_TASK_REQUEST_PURCHASE_TASK_IF_IT_IS_TIME]
@taskID varchaR(50)
AS
declare @purchItemID varchar(50)
SELECT @purchItemID = PURCHASE_ITEM_ID FROM A_V_TASK_WITH_ORDER_INFORMATION 
	WHERE TASK_ID = @taskID

if @purchItemID is not null
	begin
	print 'We have a purchase Item ID of ' + @purchItemID
	print 'We need to find if any of the previous purchase Item Tasks are not finished'
	if exists (SELECT * FROM A_V_TASK_WITH_ORDER_INFORMATION 
		WHERE TASK_STATUS NOT IN ('FINISHED','CLOSED') AND
			PURCHASE_ITEM_ID IN (SELECT PREV FROM A_ORDER_ITEM_PRECEDENTS WHERE
				FOL = @purchItemID)
		)
		begin
		print 'This task has previous purchase items that need to be done'
		UPDATE A_TASKS SET STATUS = 'WAITING_ON_PREVIOUS_TASKS' WHERE ID = @taskID
		end
	else
		begin
		declare @req varchar(50)
		SELECT @req = REQUESTOR FROM A_TASKS WHERE ID = @taskID
		exec A_SP_TASK_SUBMIT null,nulll,@taskID,@req
		end
	end
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASK_REJECT]    Script Date: 6/3/2019 2:03:51 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO






CREATE           PROCEDURE [dbo].[A_SP_TASK_REJECT]
	@newObjID as varchar(50) OUTPUT,
	@messages as nvarchar(500) OUTPUT,
	@taskID varchar(50),
	@reason nvarchar(2000),
	@strNTLogin varchar(50)
AS

declare @curPerReq as varchar(50)
declare @curGroupReq as varchar(50)

SELECT @curPerReq = REQUESTEE_ID,@curGroupReq = GROUP_REQUESTEE_ID FROM A_TASKS WHERE ID = @taskID
if @curPerReq is not null
	begin
	if @curPerReq != @strNTLogin  
		begin
		set @newObjID = 'ERROR - You are not the assignee'
		goto fin
		end
	end
else
	begin
	print 'You are not the assignee...  so are you in the group assigned?'
	if @strNTLogin not in (SELECT PERSON FROM A_V_ROLES_APPROVED_WITH_PEOPLE_IDS WHERE ROLE_ID = @curGroupReq)
		begin
		set @newObjID = 'ERROR - You are nto in this asssigned Group'
		goto fin
		end
	else
		begin
		print 'You are a member of the group so accept it first'
		declare @RET_STATUS2 as varchar(50),
				@MSGS2 as varchar(50)
		exec A_SP_TASK_ACCEPT @RET_STATUS2 OUTPUT,@MSGS2 OUTPUT,@taskID,@strNTLogin
		print 'Finished Accepting now doing something else Ret Status = ' + isNull(@RET_STATUS2,'NULL')
		if @RET_STATUS2 is not null
			begin
				print 'Error Accepting this task'
				print 'ERROR: ' + @RET_STATUS2
				goto fin
			end
		end
	end
print 'lets get the data about the current Task Assignee'
declare @requestee as varchar(50)
declare @roleRequestee as varchar(50)
declare @aID as varchar(50)
declare @requestor as varchar(50)
SELECT @requestor = REQUESTOR,@requestee = PERSON_ASSIGNED,@roleRequestee = ROLE_ASSIGNED,@aID = ID FROM A_TASK_ASSIGNEE WHERE TASK_ID = @taskID AND ACTIVE = 1
print'Reject the current assignment'
exec A_SP_TASK_SEND_EMAIL_UPDATE @taskID,'rejected',@strNTLogin
UPDATE A_TASK_ASSIGNEE SET STATUS = 'REJECTED', REJECTED_BY = @strNTLogin, 
REASON_REJECTED = @reason, REJECTION_DATE = getDate(),ACTIVE = 0,ASSIGNEE_CURRENTLY_ACCEPTED = 0,DRCM = getDate()
WHERE ID = @aID
print 'Assign it to the requestor'
INSERT INTO A_TASK_ASSIGNEE (ID,REQUESTOR,TASK_ID,PERSON_ASSIGNED,ASSIGNEE_CURRENTLY_ACCEPTED,ASSIGN_DATE,ASSIGNER,ACCEPTED_DATE,REQUEST_DATE,DRCM,MODBY,ACTIVE,STATUS)
Values (newID(),@requestor,@taskID,@requestor,1,getDate(),@strNTLogin,getDate(),getDate(),getDate(),@strNTLogin,1,'REQUESTED')
UPDATE A_TASKS SET REQUESTEE_ID = NULL, GROUP_REQUESTEE_ID = NULL WHERE ID = @taskID
exec A_SP_TASK_SET_REQUESTEE_FROM_ASSIGNEE_TABLE @taskID,@strNTLogin
exec A_SP_TASKS_UPDATE_DATA @taskID,@strNTLogin



fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASK_QUICK_CLOSE]    Script Date: 6/3/2019 2:03:51 PM ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[A_SP_TASK_QUICK_CLOSE]
@RET_STATUS as varchar(500) OUTPUT,
@MSGS as varchar(50) OUTPUT,
@ID as varchar(50),
@strNTLogin as varchar(50)
AS
print 'Quick Closing a task'
declare @curPerReq as varchar(50)
declare @curGroupReq as varchar(50)
declare @parentSys varchar(50)
SELECT @parentSys = SYSTEM_TASK FROM A_TASKS WHERE ID = (SELECT PARENT_ID FROM A_TASKS WHERE ID = @ID)
SELECT @curPerReq = REQUESTEE_ID,@curGroupReq = GROUP_REQUESTEE_ID FROM A_TASKS WHERE ID = @ID
if @curPerReq is not null
	begin
	if @curPerReq != @strNTLogin  
		begin
		set @RET_STATUS = 'ERROR - You are not the assignee. You are ' + @strNTLogin + ' and the assignee is ' + @curPerReq
		goto fin
		end
	end
else
	begin
	print 'You are not the assignee...  so are you in the group assigned'
	if not exists (SELECT ID FROM A_PERSON_ROLES WHERE PERSON_ID = @strNTLogin AND ROLE_ID = @curGroupReq)
		begin
		set @RET_STATUS = 'ERROR - You are not in the assigned group and cannot perform this task.'
		goto fin
		end
	else
		begin
		print 'You are a member of the group so accept it first'
		declare @RET_STATUS2 as varchar(50),
				@MSGS2 as varchar(50)
		exec A_SP_TASK_ACCEPT @RET_STATUS2 OUTPUT,@MSGS2 OUTPUT,@ID,@strNTLogin
		print 'Finished Accepting now doing something else Ret Status = ' + isNull(@RET_STATUS2,'NULL')
		if @RET_STATUS2 is not null
			begin
				print 'Error Accepting this task'
				print 'ERROR: ' + @RET_STATUS2
				goto fin
			end
		end
	end
print 'OK I am allowed to close it.'

exec A_SP_TASK_CHECK_MONITORS_TO_GO_TO_DNR @ID



declare @errMsg varchar(100)
--print 'Check to see if the task has children and should not be closed'
--if exists(SELECT * FROM A_TASKS WHERE
--	ID = @ID AND CHILD_STATUS = 'NOT_FINISHED')
--	begin
--	set @RET_STATUS = 'ERROR - Children tasks not completed'
--	goto fin
--	end


print 'Check to see if the task has any monitors that can not be automatically closed'

declare @curs as cursor,@it varchar(50),@typ varchar(50),@res varchar(4000)
set @curs = cursor for SELECT ID,MONITOR_TYPE FROM A_V_MONITOR_TEMPLATES_WITH_RESULTS 
	WHERE TASK_ID = @ID AND PRINT_RESULT IS NULL
open @curs
fetch next from @curs into @it,@typ
while @@fetch_status = 0
	begin
	DELETE FROM A_MONITOR_RESULTS WHERE MONITOR_TEMPLATE_ID = @it		
	if @typ = 'YES_NO' SELECT @res = YES_NO_ANSWER FROM A_V_MONITOR_TEMPLATES_WITH_RESULTS WHERE ID = @it
	if @typ is not null
		INSERT INTO A_MONITOR_RESULTS (ID,MONITOR_TEMPLATE_ID,TEXT_VAL,PRINT_RESULT,DRCM,MODBY,COMMENT)
			VALUES (newID(),@it,@RES,@RES,getDate(),@strNTLogin,null)
		
	fetch next from @curs into @it,@typ
	end


if exists(SELECT * FROM A_V_MONITOR_TEMPLATES_WITH_RESULTS 
	WHERE TASK_ID = @ID AND PRINT_RESULT IS NULL)
	begin
	set @RET_STATUS = 'ERROR - MONITOR NOT COMPLETED'
	goto fin
	end


if @parentSys <> 'SYS_DNR'
	begin
	print 'Check to see if the task has failing monitors that stop it from closing'
	if exists(SELECT * FROM A_MONITOR_TEMPLATES 
		WHERE TASK_ID = @ID AND IS_PASSING=0 AND FAIL_ACTION not in ('CONTINUE','ENDPROCEDURE'))
		begin
		set @RET_STATUS = 'ERROR - A Failing Monitor Must Be Corrected'
		goto fin
		end
	end

--ADD Code to check monitors
print 'Monitors OK'
print 'Check to see if the task is for quoting an order'
exec A_SP_TASK_FINISH_CHECK_ORDER_QUOTE_DATA @errMsg OUTPUT,@ID
if @errMsg is not null
	begin
	print 'This ones quote is not completed must not close'
	print 'Error msg = ' + @errMsg
	set @RET_STATUS = @errMsg
	goto fin
	end

print 'Check to see if it is already closed'
if exists (SELECT * FROM A_TASKS WHERE ID = @ID AND STATUS IN ('FINISHED','CLOSED'))
	goto fin

print 'Set the Stop Date and Stop Counter if they have not already been set'
declare @actStopDate as dateTime
declare @actStopCount as numeric
declare @cID as varchar(50)
SELECT @cID = COUNTER,@actStopDate = ACTUAL_STOP_DATE,@actStopCount = ACTUAL_COUNTER_STOP FROM A_TASKS WHERE ID = @ID
if @actStopDate is NULL
	begin
		declare @myDate as datetime
		set @myDate = getDate()
		exec A_SP_TASK_DATES_UPDATE @ID,'ACTUAL_STOP',@myDate,@strNTLogin
		exec A_SP_TASK_UPDATE_ALL_DATES @ID,@strNTlogin
		set @actStopDate = getDate()
	end

print 'Now for the timer'
declare @counterVal as numeric
if @cID is not null
	begin
	print 'We have a counter'
	if @actStopCount is NULL
		begin
		print 'The count in the task was null'
		select top 1 @counterVal = VAL FROM A_COUNTERS_RECORDINGS WHERE DATE_RECORDED < @actStopDate ORDER BY DATE_RECORDED DESC
		end
	else
		begin
		print 'The count in the task was not null so we dont need to do anything'
		end
	end

print 'Now check if it is a send or recieve with no action object'
declare @sysID varchar(50),@objID varchar(50),@qty float
SELECT @objID = OBJECT_ID FROM A_TASK_OBJECT_LINK WHERE TASK_ID = @ID
SELECT @qty = QTY FROM A_V_ACTUAL_PARTS_APPROVED_DATA WHERE ID = @objID
SELECT @sysID = SYSTEM_TASK FROM A_TASKS WHERE ID = @ID
if @sysID in ('SYS_RECEIVE','SYS_SEND')
	begin
	if not exists(SELECT * FROM A_TASK_ACTION_OBJECT_LINK WHERE TASK_ID = @ID)
		begin
		INSERT INTO A_TASK_ACTION_OBJECT_LINK
			(ID,TASK_ID,OBJECT_ID,RELATIONSHIP,DRCM,MODBY,QTY)
			SELECT newID(),@ID,OBJECT_ID,'ACTION_OBJECT',getDate(),@strNTLogin,@qty FROM
				A_TASK_OBJECT_LINK WHERE TASK_ID = @ID
		end
	end


print 'Counter and Dates Updated.  Change the Status'

exec A_SP_TASK_FINISH @ID,@strNTLogin

fin:


		print @RET_STATUS
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASK_PROCEDURE_CREATE_CHILDREN_TASKS_STARTING_WITH_CERTAIN_STEP]    Script Date: 6/3/2019 2:03:51 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE       PROCEDURE [dbo].[A_SP_TASK_PROCEDURE_CREATE_CHILDREN_TASKS_STARTING_WITH_CERTAIN_STEP]
@startStepID varchar(50),
@recurNumber int,
@PARENT_ID  varchar(50),
@repeatFromStep varchar(50)
AS
print 'The parent Task is ' + @PARENT_ID
print 'recur step is ' + @repeatFRomStep
print 'RecurNumber = '
print @recurNumber

declare @procID varchar(50),@requestor varchar(50),@requesteeRole varchar(50),
	@stepName nvarchar(2000),@systemID varchar(50),@newTaskID nvarchar(50),
	@messages nvarchar(2000),@taskComment nvarchar(2000),
	@SUBMIT_STATUS varchar(50),@newID varchar(50), @phID varchar(50),
	@supplierID varchar(50),@showStepsInAP smallInt,@requesteeID varchar(50),
	@SPECIFIC_LOCATION varchar(50)

SELECT @procID = PROCEDURE_ID,@requestor = ORIG_REQUESTOR_ID FROM A_TASKS WHERE ID = @PARENT_ID
SELECT @phID = HISTORY_REF_ID FROM A_PROCEDURES WHERE ID = @procID
if exists(SELECT * FROM A_TASKS 
		WHERE PARENT_ID = @PARENT_ID AND PROCEDURE_ID = @procID AND 
		PROCEDURE_STEP_ID = @startStepID and RECURSION_NUMBER = @recurNumber 
		and REPEAT_FROM_STEP = @repeatFromStep)
	begin
	print 'Already have this one so done here'
	goto DONE_WITH_STEP
	end

if exists(SELECT * FROM A_TASKS 
		WHERE PARENT_ID = @PARENT_ID AND PROCEDURE_ID = @procID AND 
		PROCEDURE_STEP_ID = @repeatFromStep and RECURSION_NUMBER = @recurNumber 
		and REPEAT_FROM_STEP = @repeatFromStep)
	begin
	print 'We just finished making this thing to the point where we started from'
	goto DONE_WITH_STEP
	end


		
print 'We need to get all the data to make a task out of this step ' + @startStepID
exec sp_GetUniqueID3 @newID OUTPUT
select @requesteeRole = OWNER_ROLE_ID,@stepName = STEP_TEXT,@systemID = SYSTEM_TASK
	FROM A_V_PROCEDURE_STEPS_WITH_OWNER_LABOR WHERE ID = @startStepID
select @supplierID = HISTORY_REF_ID FROM A_COMPANIES WHERE ID = dbo.FN_ROLE_GET_COMPANY(@requesteeRole)
print 'requesteeRole ' + isnull(@requesteeRole,'NULL')
if @requesteeRole is null
	begin
	select @requesteeID = REQUESTEE_ID FROM A_TASKS WHERE ID = @PARENT_ID
	if @requesteeID is null
		begin
		select @requesteeRole = GROUP_REQUESTEE_ID FROM A_TASKS WHERE ID = @PARENT_ID
		if @requesteeRole is null
			set @requesteeID = null
		end
	end
print 'Step Name ' + @stepName
print 'systemID ' + isNull(@systemID,'NULL')
print 'Inserting this task'
SELECT @SPECIFIC_LOCATION = SPECIFIC_LOCATION FROM A_PROCEDURE_STEPS WHERE ID = @startStepID
exec A_SP_TASKS_UPDATE_TASK @newTaskID OUTPUT,@messages OUTPUT,
	null, --ID
	@PARENT_ID, --Parent,
	@requestor,--Requestor
	@requesteeID, --REQUESTEE_ID,
	@requesteeRole, --GROUP_REQUESTEE_ID
	@stepName, --DESCRIPTION 
	@stepName, --Title 
	@systemID, --SYSTEM_TASK,
	null, --COMMENT,
	'3', --Security Level
	null, --counter
	null, --orig planned Start Date
	null, --orig planned stop date,
	null, --@ORIG_PLANNED_COUNTER_START numeric,
	null, --@ORIG_PLANNED_COUNTER_STOP numeric,
	null, --@CUR_PLANNED_START_DATE dateTime,
	null, --@CUR_PLANNED_STOP_DATE dateTime,
	null, --@CUR_PLANNED_COUNTER_START numeric,
	null, --@CUR_PLANNED_COUNTER_STOP numeric,
	null, --@ACTUAL_START_DATE dateTime,
	null, --@ACTUAL_STOP_DATE dateTime,
	null, --@ACTUAL_COUNTER_START numeric,
	null, --@ACTUAL_COUNTER_STOP numeric,
	@procID, --@REF_PROC_LIST varchar(8000),
	null, --@REF_FILE_LIST varchar(8000),
	null, --@DISCUSSIONS varchar(8000),
	null, --@SURVEYS varchar(8000),
	null, --@MEETINGS varchar(8000),
	null, --Object varchar(8000),
	null, --@COMPANIES varchar(8000),
	null, --@SYSTEM_PEOPLE_TO_EMAIL varchar(8000),
	'1', --@PRIORITY smallInt,
	null, --@ADDITIONAL_ASSIGNEES varchar(8000),
	@requesteeID --strNTLogin
	print 'Created A Task with the ID of ' + @newTaskID
	
	
UPDATE A_TASKS SET 
	[PROCEDURE_ID] = @procID, 
	PROCEDURE_STEP_ID = @startStepID,
	STATUS = 'PENDING_PARENT_ACCEPTANCE',
	REPEAT_FROM_STEP = @repeatFromStep	
	WHERE ID = @newTaskID

if @recurNumber > 1
	begin
	UPDATE A_TASKS SET 
	RECURSION_NUMBER = @recurNumber,
	STATUS = 'Qued'
	WHERE ID = @newTaskID
	exec A_SP_TASK_FIGURE_OUT_PROCEDURE_START_DATE_TIME @newTaskID
	-- If this is the first task at this recursion number then we need to go ahead 
	-- and submit it.
	declare @prevTask varchar(50)
	SELECT @prevTask = PREV_TASK_ID FROM A_V_TASKS_WITH_PROCEDURE_STEP_DATA WHERE STEP_ID = @newTaskID
	if @prevTask is null
		begin
		declare @myQdate datetime,@sql varchar(50)
		select @myQDate = dateAdd(dd,-7,ORIG_PLANNED_START_DATE) FROM A_TASKS WHERE ID = @newTaskID
		set @sql = 'exec A_SP_TASK_SUBMIT null,null,''' + @newTaskID + ''',''' + @requestor + ''''
		if @myQDate > getDate()
			exec A_SP_ADMIN_SQL_TO_RUN_QUE_UP_WITH_DATE @sql,@myQDate,@requestor
		else
			exec(@sql)
		end

	if not exists(SELECT * FROM A_TASK_ORDER_INFORMATION WHERE TASK_ID = @newTaskID)
		INSERT INTO A_TASK_ORDER_INFORMATION (TASK_ID,ACTUAL_TO_LOC,MODBY,DRCM)
			VALUES (@newTaskID,@SPECIFIC_LOCATION,@requesteeID,getDate())
	else
		UPDATE A_TASK_ORDER_INFORMATION
			SET ACTUAL_TO_LOC = @SPECIFIC_LOCATION
			WHERE TASK_ID = @newTaskID

	INSERT INTO A_TASK_OBJECT_LINK 
		(ID,TASK_ID,OBJECT_ID,DRCM,MODBY)
	SELECT newID(),@newTaskID,OBJECT_ID,getDate(),@requesteeID
		FROM A_TASK_OBJECT_LINK WHERE TASK_ID = @PARENT_ID
	exec A_SP_TASK_CREATE_MONITORS_FROM_PROCEDURE_INFO @newTaskID,@requesteeID
	exec A_SP_TASK_AUTOMATIC_ORDER_UPDATER @newTaskID,@requesteeID
	exec A_SP_TASK_FIGURE_OUT_PROCEDURE_START_DATE_TIME @newTaskID

	end

print 'Now we need to make all the steps that were waiting on this step to complete'
Declare @it nvarchar(50)
Declare @curs Cursor
set @curs = Cursor For SELECT ID FROM A_PROCEDURE_STEPS WHERE 
							ID IN (SELECT MY_STEP FROM A_PROCEDURE_STEP_PRECEDING_STEPS WHERE
							PREV_STEP = @startStepID)
open @curs
Fetch Next from @curs Into @it
while (@@fetch_status = 0)
Begin
exec A_SP_TASK_PROCEDURE_CREATE_CHILDREN_TASKS_STARTING_WITH_CERTAIN_STEP
	@it,@recurNumber,@PARENT_ID,@repeatFromStep
	Fetch Next from @curs Into @it
End
close @curs
Deallocate @curs




DONE_WITH_STEP:


fin:

print 'Finished with A_SP_TASK_PROCEDURE_CREATE_CHILDREN_TASKS_STARTING_WITH_CERTAIN_STEP'
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASK_POPULATE_LINKED_ACTUAL_PARTS_WHEN_FINISHED_II]    Script Date: 6/3/2019 2:03:52 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
