CREATE  PROCEDURE [dbo].[A_SP_TASK_FIGURE_OUT_CHILD_STATUS]
@ID varchar(50),
@strNTLogin varchar(50)
AS

if exists (	SELECT * FROM A_TASKS 
			WHERE PARENT_ID = @ID 
			)
		UPDATE A_TASKS SET HAS_CHILD = 1 WHERE ID = @ID
else 
		UPDATE A_TASKS SET HAS_CHILD = 0 WHERE ID = @ID

if exists (
			SELECT * FROM A_TASKS 
			WHERE PARENT_ID = @ID 
			AND STATUS not in ('FINISHED','CLOSED')
			)
		UPDATE A_TASKS SET CHILD_STATUS = 'NOT_FINISHED',HAS_CHILD = 1 WHERE ID = @ID
else 
	UPDATE A_TASKS SET CHILD_STATUS = 'FINISHED' WHERE ID = @ID
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASK_FIGURE_COMPLETION_DATA]    Script Date: 6/3/2019 2:04:04 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO



CREATE   PROCEDURE [dbo].[A_SP_TASK_FIGURE_COMPLETION_DATA]
@taskID varchar(50),
@strNTLogin varchar(50)
AS
declare @taskHasChild tinyint,@stat varchar(50),@parentID varchar(50),@procStepID varchar(50),@curStepText varchar(4000),@realID varchar(50)
SELECT 
	@realID = ID,
	@taskHasChild = HAS_CHILD, 
	@stat = STATUS,
	@procStepID = PROCEDURE_STEP_ID,
	@parentID = PARENT_ID
FROM A_TASKS 
WHERE ID = @taskID


if @realID is null
	goto fin
else
	print 'Processing Task = ' + @realID

declare @numSubTasks float,@subTasksComplete float,@numSubTaskHours float,@numSubTaskHoursComplete float,
@percComplete float,@numSubTasksComplete int,@timeComplete float,@totSecs float,@hours float

if isNull(@taskHASChild,0) = 0
	begin
	set @numSubTasks = 1

    SELECT @totSecs = sum(s.DURATION * t.SECS) FROM dbo.A_PROCEDURE_STEPS s INNER JOIN
                     dbo.A_Z_UNITS_TIME_TO_SECS t ON s.DURATION_TYPE = t.FROM_UNIT
                     WHERE s.ID = @procStepID

   set @numSubTaskHours=CAST(@totSecs/60/60 AS float);

	print 'This task has no children so its completion is based on itself'
	if @stat in ('FINISHED','CLOSED','COMPLETED')
		begin
		SET @numSubTasksComplete = 1
		set @numSubTaskHoursComplete = @numSubTaskHours
		set @percComplete = 100
		set @timeComplete = 100
		end
	else
		begin
		SET @numSubTasksComplete = 0
		set @numSubTaskHoursComplete = 0
		set @percComplete = 0
		set @timeComplete = 0
		end
	end
else
	begin
	SELECT @numSubTasks = count(ID) FROM A_TASKS WHERE PARENT_ID = @taskID
	SELECT @numSubTasksComplete = count(ID) FROM A_TASKS WHERE PARENT_ID = @taskID AND STATUS in ('FINISHED','CLOSED','COMPLETED')
	SELECT top 1 @curStepText = Title FROM A_TASKS WHERE PARENT_ID = @taskID AND STATUS in ('REQUESTED','ACCEPTED')
	print 'Cur Step = ' + @curStepText
	SELECT 
		@numSubTasks = count(NUM_SUB_TASKS),
		@numSubTasksComplete = sum(NUM_SUB_TASKS_COMPLETE),
		@numSubTaskHours = sum(MY_TOT_HOURS),
		@numSubTaskHoursComplete = sum(MY_COMP_HOURS)
	FROM A_TASK_COMPLETION_STATS 
	WHERE PARENT_TASK_ID = @taskID
	if isnull(@numSubTasks,0) <> 0
		set @percComplete = (@numSubTasksComplete / @numSubTasks) * 100
	else
		print 'PercComplete not figured'
	if isnull(@numSubTaskHours,0) <> 0
		set @timeComplete = (@numSubTaskHoursComplete / @numSubTaskHours) * 100
	end

DELETE FROM A_TASK_COMPLETION_STATS WHERE TASK_ID = @taskID
INSERT INTO A_TASK_COMPLETION_STATS 
	(TASK_ID,PERC_COMPLETE,TIME_COMPLETE,
	DRCM,MODBY,NUM_SUB_TASKS,MY_TOT_HOURS,
	MY_COMP_HOURS,PARENT_TASK_ID,NUM_SUB_TASKS_COMPLETE,CUR_STEP_TEXT)
VALUES
	(@taskID,@percComplete,@timeComplete,
	getDate(),@strNTLogin,@numSubTasks,@numSubTaskHours,
	@numSubTaskHoursComplete,@parentID,@numSubTasksComplete,@curStepText)
declare @fillID varchar(50),@tID varchar(50)
SELECT @fillID = FILL_ITEM_ID FROM A_TASK_ORDER_INFORMATION WHERE TASK_ID = @taskID
declare @curs as CURSOR,@it varchar(50)
set @curs = CURSOR FOR SELECT ID FROM A_FILLS WHERE BATCH_PARENT = @fillID
open @curs
fetch next from @curs into @it
while @@fetch_status = 0
	begin
	SELECT @tID = TASK_ID FROM A_TASK_ORDER_INFORMATION WHERE FILL_ITEM_ID = @it
	print 'updating batched task ' + @tID
	DELETE FROM A_TASK_COMPLETION_STATS WHERE TASK_ID = @tID
	INSERT INTO A_TASK_COMPLETION_STATS 
		(TASK_ID,PERC_COMPLETE,TIME_COMPLETE,
		DRCM,MODBY,NUM_SUB_TASKS,MY_TOT_HOURS,
		MY_COMP_HOURS,PARENT_TASK_ID,NUM_SUB_TASKS_COMPLETE,CUR_STEP_TEXT)
	VALUES
		(@tID,@percComplete,@timeComplete,
		getDate(),@strNTLogin,@numSubTasks,@numSubTaskHours,
		@numSubTaskHoursComplete,@parentID,@numSubTasksComplete,@curStepText)
	fetch next from @curs into @it
	end
close @curs
deallocate @curs


if @parentID is not null
	exec A_SP_TASK_FIGURE_COMPLETION_DATA @parentID,@strNTLogin

fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASK_END_PROCEDURE_SPECED_IN_MONITORS]    Script Date: 6/3/2019 2:04:04 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO





CREATE    PROCEDURE [dbo].[A_SP_TASK_END_PROCEDURE_SPECED_IN_MONITORS]
@taskID varchar(50),
@strNTLogin varchar(50)
AS
print 'Checking monitors to see if we need to stop the procedure.'
begin transaction

declare @curs2 as cursor,@childID as varchar(50),@myParent2 varchar(50)
if not exists(SELECT * FROM A_MONITOR_TEMPLATES WHERE TASK_ID = @taskID AND IS_PASSING = 0 AND FAIL_ACTION = 'ENDPROCEDURE')
	begin
	print 'This task will not end the procedure'
	goto fin
	end

print 'There is a failing monitor that also says close the procedure.'
declare @requestorID varchar(50),@requesteeID varchar(50),@procID varchar(50),@stepID varchar(50),@PARENT_ID varchar(50)
SELECT @PARENT_ID = PARENT_ID FROM A_TASKS WHERE ID = @taskID
declare @curs as  cursor,@it as varchar(50),@r varchar(50)
set @curs = cursor for SELECT ID,ORIG_REQUESTOR_ID
				FROM A_TASKS 
				WHERE PARENT_ID = @PARENT_ID AND STATUS NOT IN ('FINISHED','CLOSED') ORDER BY ID
open @curs
fetch next from @curs into @it,@r
while @@fetch_status = 0
	begin
	set @curs2 = CURSOR FOR SELECT ID FROM A_TASKS WHERE PARENT_ID = @it
	open @curs2
	fetch next from @curs2 into @childID
	while @@fetch_status = 0
		begin
		print 'Deleting a Child task (should not happen much)' + @childID
		exec  A_SP_TASK_DELETE_TASK_FOREVER @childID,@strNTLogin
		fetch next from @curs2 into @childID
		end
	close @curs2
	deallocate @curs2

	SELECT @myParent2 = PARENT_ID FROM A_TASKS WHERE ID = @it
	UPDATE A_TASKS SET PARENT_ID = @myParent2 WHERE PARENT_ID = @it
	DELETE FROM A_MONITOR_RESULTS WHERE MONITOR_TEMPLATE_ID IN 
					(SELECT ID FROM A_MONITOR_TEMPLATES WHERE TASK_ID = @it)
	DELETE FROM A_MONITOR_TEMPLATES WHERE TASK_ID = @it
	DELETE FROM A_TASKS WHERE ID = @it
	fetch next from @curs into @it,@r
	end

declare @sql varchar(3000)
set @sql = 'exec A_SP_TASK_FIGURE_OUT_CHILD_STATUS ''' + @PARENT_ID + ''',''' + @strNTLogin + ''''
exec A_SP_ADMIN_SQL_TO_RUN_QUE_UP @sql,@strNTLogin

set @sql = 'exec A_SP_TASK_CHECK_STATUS ''' + @PARENT_ID + ''',''' + @strNTLogin + ''''
exec A_SP_ADMIN_SQL_TO_RUN_QUE_UP @sql,@strNTLogin




fin:
if @@trancount > 0 COMMIT TRANSACTION
print 'Finished A_SP_TASK_END_PROCEDURE_SPECED_IN_MONITORS with no errors'
return 0

PROBLEM:
if @@trancount > 0 	ROLLBACK TRANSACTION
print ' There was a problem in A_SP_TASK_END_PROCEDURE_SPECED_IN_MONITORS and we will terminate and not finish anything '
return 1
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASK_DELETE_TASK_FOREVER]    Script Date: 6/3/2019 2:04:05 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO











CREATE          PROCEDURE [dbo].[A_SP_TASK_DELETE_TASK_FOREVER]
@ID varchar(50),
@strNTLogin varchar(50)
AS
declare @tester as varchar(50)
SELECT @tester = ID FROM A_TASKS WHERE ID = @ID AND (ORIG_REQUESTOR_ID = @strNTLogin or @strNTLogin IN (SELECT BOSS FROM A_PEOPLE_SUB_LOOKUP_TABLE WHERE SUBORDINATE = ORIG_REQUESTOR_ID))
if @tester is null
	begin
	print 'You can not delete it'
	goto fin
	end

declare @curs as CURSOR,@it varchar(50)
set @curs = CURSOR FOR SELECT ID FROM A_TASKS WHERE PARENT_ID = @ID
open @curs
fetch next from @curs into @it
while @@fetch_status = 0
	begin
	print 'Deleting Child task' + @it
	exec  A_SP_TASK_DELETE_TASK_FOREVER @it,@strNTLogin
	fetch next from @curs into @it
	end
close @curs
deallocate @curs

declare @myParent as varchar(50)
SELECT @myParent = PARENT_ID FROM A_TASKS WHERE ID = @ID
UPDATE A_TASKS SET PARENT_ID = @myPArent WHERE PARENT_ID = @ID
DELETE FROM A_MONITOR_RESULTS WHERE MONITOR_TEMPLATE_ID IN (SELECT ID FROM A_MONITOR_TEMPLATES WHERE TASK_ID = @ID)
DELETE FROM A_MONITOR_TEMPLATES WHERE TASK_ID = @ID
DELETE FROM A_TASKS WHERE ID = @ID


declare @sql varchar(3000)
set @sql = 'exec A_SP_TASK_FIGURE_OUT_CHILD_STATUS ''' + @myParent + ''',''' + @strNTLogin + ''''
exec A_SP_ADMIN_SQL_TO_RUN_QUE_UP @sql,@strNTLogin

set @sql = 'exec A_SP_TASK_CHECK_STATUS ''' + @myParent + ''',''' + @strNTLogin + ''''
exec A_SP_ADMIN_SQL_TO_RUN_QUE_UP @sql,@strNTLogin


fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASK_DATES_UPDATE]    Script Date: 6/3/2019 2:04:05 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO









CREATE        PROCEDURE [dbo].[A_SP_TASK_DATES_UPDATE]
@taskID varchar(50),
@dateType varchar(50),
@dateValue datetime,
@strNTLogin varchar(50)
AS
declare @tester datetime
	SELECT @tester = THE_DATE FROM A_TASK_DATES
		WHERE DATE_TYPE = @dateType AND TASK_ID = @taskID AND IS_CURRENT = 1

if @dateValue is not null
	begin
	if @tester is NULL or @tester != @dateValue
		begin
		UPDATE A_TASK_DATES SET IS_CURRENT = 0 WHERE TASK_ID = @taskID AND DATE_TYPE = @dateType
		INSERT INTO A_TASK_DATES (ID,DATE_TYPE,THE_DATE,DRCM,MODBY,TASK_ID,IS_CURRENT)
		VALUES (newID(),@dateType,@dateValue,getDAte(),@strNTLogin,@taskID,1)
		end
	end
else
	begin
	if @tester is not null
		begin
		--	print 'Since the new value is null we need to just make sure there is no value by setting all to null'
		UPDATE A_TASK_DATES SET IS_CURRENT= 0 WHERE TASK_ID = @taskID AND DATE_TYPE = @dateType
		end
	end
declare @sql varchar(2000)
set @sql = 'UPDATE A_TASKS SET ' + @dateType + '_DATE = ''' + convert(varchar(50),@dateValue) + ''' WHERE ID = ''' + @taskID + ''''
exec(@sql)

if @dateType = 'ORIG_PLANNED_START'
	begin
	exec A_SP_TASK_DATES_UPDATE @taskID,'CUR_PLANNED_START',@dateValue,@strNTLogin
	set @sql = 'UPDATE A_TASKS SET ' + 'CUR_PLANNED_START' + '_DATE = ''' + convert(varchar(50),@dateValue) + ''' WHERE ID = ''' + @taskID + ''''
	exec(@sql)
	end

if @dateType = 'ORIG_PLANNED_STOP'
	begin
	exec A_SP_TASK_DATES_UPDATE @taskID,'CUR_PLANNED_STOP',@dateValue,@strNTLogin
	set @sql = 'UPDATE A_TASKS SET ' + 'CUR_PLANNED_STOP' + '_DATE = ''' + convert(varchar(50),@dateValue) + ''' WHERE ID = ''' + @taskID + ''''
	end
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASK_CREATE_MONITORS_FROM_PROCEDURE_INFO_II]    Script Date: 6/3/2019 2:04:06 PM ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO




CREATE  PROCEDURE [dbo].[A_SP_TASK_CREATE_MONITORS_FROM_PROCEDURE_INFO_II] 
@taskID varchar(50),
@procID varchar(50),
@stepID varchar(50),
@notShowingSteps tinyInt,
@strNTLogin varchar(50)

AS
if exists(SELECT * FROM #tempProcsAlreadyProcessed WHERE PROC_ID = @procID and STEP_ID = @stepID) goto fin
INSERT INTO #tempProcsAlreadyProcessed(PROC_ID,STEP_ID)VALUES(@procID,@stepID)
declare @showSteps varchar(50),@it nvarchar(50),@curs Cursor,@procHistID varchar(50),@newMonitorID varchar(50)

print 'Creating the monitors for a task for a procedure'
if @stepID is null
	begin
	print 'the step is null so we need to go ahead and do this for the whole procedure'
	SELECT @showSteps = STEPS_IN_AP FROM A_V_PROCEDURES_APPROVED_DATA WHERE ID = @procID
	print 'show Steps = ' + isNull(@showSteps,'NULL')
	if @showSteps is null or @showSteps = 0 or @notShowingSteps = 1
		begin
		print 'We do not show the steps so we need to call this procedure for every step'
		set @curs = Cursor For SELECT STEP_ID FROM A_V_APPROVED_PROCEDURE_STEPS WHERE APPROVED_PROC_ID = @procID
		open @curs
		Fetch Next from @curs Into @it
		while (@@fetch_status = 0)
			Begin
			print 'processig step = ' + @it
			exec A_SP_TASK_CREATE_MONITORS_FROM_PROCEDURE_INFO_II @taskID,@procID,@it,1,@strNTLogin
			Fetch Next from @curs Into @it
			End
		close @curs
		Deallocate @curs	
		end
	end
else
	begin
	print 'We are dealing with a step, so we just need to get all the monitors from the linked procedures.'
	set @curs = Cursor For SELECT PROCEDURE_LINK FROM A_PROCEDURE_STEP_PROCEDURE_LINK WHERE PROCEDURE_STEP = @stepID
	open @curs
	Fetch Next from @curs Into @it
	while (@@fetch_status = 0)
		Begin
		print 'processig proc = ' + @it
		exec A_SP_TASK_CREATE_MONITORS_FROM_PROCEDURE_INFO_II @taskID,@it,null,1,@strNTLogin
		Fetch Next from @curs Into @it
		End
	close @curs
	Deallocate @curs	
	end
	





	print 'so we made all the monitors for the sub data, now to make all the monitors for this item'
	SELECT @procHistID = HISTORY_REF_ID FROM A_PROCEDURES WHERE ID = @procID
	if @stepID is null
		begin
		print 'Step ID is Null'
		print 'SELECT ID FROM A_MONITOR_TEMPLATES WHERE PROCEDURE_ID = ''' + isNull(@procHistID,'NULL') + ''' and STEP_ID = ''' + isNull(@stepID,'NULL') + ''' and TASK_ID IS NULL'
		set @curs = Cursor For SELECT ID FROM A_MONITOR_TEMPLATES WHERE PROCEDURE_ID = @procHistID and STEP_ID is null AND TASK_ID is NULL
		end
	else
		begin
		print 'We are using this to get them '
		print 'SELECT ID FROM A_MONITOR_TEMPLATES WHERE PROCEDURE_ID = ''' + isNull(@procHistID,'NULL') + ''' and STEP_ID = ''' + @stepID + ''' and TASK_ID IS NULL'
		set @curs = Cursor For SELECT ID FROM A_MONITOR_TEMPLATES WHERE PROCEDURE_ID = @procHistID and STEP_ID = @stepID and TASK_ID IS NULL

		end

	open @curs
	Fetch Next from @curs Into @it
	while (@@fetch_status = 0)
		Begin
		print 'processig monitor = ' + @it
		exec A_SP_MONITOR_COPY @newMonitorID OUTPUT,@it,1,@strNTLogin
		UPDATE A_MONITOR_TEMPLATES SET TASK_ID = @taskID,PROCEDURE_ID = NULL,STEP_ID = null WHERE ID = @newMonitorID
		UPDATE A_TASKS SET HAS_MONITOR = 1 WHERE ID = @taskID
		Fetch Next from @curs Into @it
		End
	close @curs
	Deallocate @curs	
	
	





	print 'Now we need to add all the info for the monitors for the main procedure or step'






fin:
GO

