CREATE   PROCEDURE [dbo].[A_SP_TASK_AUTO_ACCEPT] 
@ID varchar(50),
@strNTLogin varchar(50)
AS
print 'This function is not going to be used anymore'
goto fin


declare @requestee as varchar(50)
SELECT @requestee = REQUESTEE_ID FROM A_TASKS WHERE ID = @ID
if @requestee is null
	begin
		goto fin
	end
declare @tester as varchar(50)
SELECT @tester = ID FROM A_PEOPLE_SUB_LOOKUP_TABLE WHERE BOSS = @strNTlogin and SUBORDINATE = @requestee
if (@tester is not null) OR (@strNTlogin = @requestee)
	begin
	UPDATE A_TASKS SET STATUS = 'ACCEPTED' WHERE ID = @ID
	UPDATE A_TASK_ASSIGNEE SET ASSIGNEE_CURRENTLY_ACCEPTED = 1,ASSIGN_DATE = getDate(),ASSIGNER=@strNTlogin,
	ACCEPTED_DATE = getDate(),STATUS='ACCEPTED' WHERE TASK_ID = @ID AND ACTIVE = 1 AND PERSON_ASSIGNED = @requestee
	end

fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASK_ASSUME_CONTROL]    Script Date: 6/3/2019 2:04:13 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE               PROCEDURE [dbo].[A_SP_TASK_ASSUME_CONTROL] 
@RET_STATUS as varchar(500) OUTPUT,
@MSGS as varchar(500) OUTPUT,
@ID as varchar(50),
@strNTLogin as varchar(50)
AS
print 'Assuming a task'
print 'Verifying that I am a person who can accept it'
declare @requestee as varchar(50)
declare @roleRequestee as varchar(50)
SELECT @requestee = REQUESTEE_ID,@roleRequestee = GROUP_REQUESTEE_ID FROM A_TASKS WHERE ID = @ID
declare @tester as varchar(50),@taskStat varchar(50)
declare @stepRoles as nvarchar(max)
SELECT @taskStat = STATUS FROM A_TASKS WHERE ID = @ID              

SELECT @StepRoles=(SELECT Roles FROM A_V_TASKS_WITH_PROCEDURE_STEP_DATA WHERE STEP_ID=@ID)

 

 IF NOT EXISTS(SELECT ROLE_ID FROM A_APPROVED_ROLE_ASSIGNEES WHERE PERSON=@strNTLogin AND (ROLE_ID 
 IN (SELECT * from dbo.SplitString(@StepRoles)) 
 OR
 ROLE_ID IN (SELECT ROLE_ID FROM A_V_PROCEDURE_ROLES_TO_VIEW
 WHERE PROCEDURE_OBJ_ID IN ( SELECT ProcObjId FROM Portal_WorkOrders
 WHERE TaskId = @ID)))
 )
	BEGIN
	SET @RET_STATUS = 'ERROR - You are not a member of the role that this task was assigned to.'
	GOTO fin
    END

ELSE
   BEGIN
IF @taskStat not in ('ACCEPTED')
	BEGIN
	SET @RET_STATUS = 'ERROR - This task is not started so it can not be assumed.'
	GOTO fin
	END

declare @fwdID varchar(50),@fwdMSG varchar(50)
exec A_SP_TASKS_FORWARD_TASK 
@fwdID OUTPUT,
@fwdMSG OUTPUT,
@ID,@strNTLogin,null,@requestee

declare @accStat varchar(50),@accMSG varchar(50)
exec A_SP_TASK_ACCEPT 
@accStat OUTPUT,
@accMSG OUTPUT,
@ID,@strNTLogin


fin:
End
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASK_ADD_TO_TREE_TABLE]    Script Date: 6/3/2019 2:04:13 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO








CREATE      PROCEDURE [dbo].[A_SP_TASK_ADD_TO_TREE_TABLE]
@ID varchar(50),
@LEV integer,
@exAll smallint
AS
print 'First Checking to see if we are in the expand All List'
If @ID in (SELECT ID FROM #tempExpandAllList)
	begin
	print 'ID = ' + @ID + 'Is in the expand all list'
	set @exAll = 1
	end
print 'Insert My ID and Level into the tree table'
declare @tester as varchar(50)
SELECT TOP 1  @tester = ID FROM A_TASKS WHERE PARENT_ID = @ID
IF @tester is not null
	set @tester = '1'
INSERT INTO #tempCoTree(ID,LEV,HAS_CHILD,EXPANDED) VALUES(@ID,@LEV,CONVERT(smallint,@tester),0)
IF ((@ID in (SELECT ID FROM #tempExpandList)) or (@exAll = 1))
	begin
	UPDATE #tempCoTree SET EXPANDED = 1 WHERE ID = @ID
	print 'This one needs to be expanded so make a cursor for children and do it'
	Declare @it nvarchar(50)
	Declare @curs Cursor
	set @curs = Cursor For SELECT ID
		--STEP_ID 
		FROM A_V_TASKS_WITH_PROCEDURE_STEP_ORDER_II
		--A_V_TASKS_WITH_PROCEDURE_STEP_ORDER 
		WHERE PARENT_ID = @ID 
		ORDER BY STEP_ORDER,ACTUAL_STOP_DATE,ACTUAL_START_DATE,CUR_PLANNED_START_DATE,ORIG_PLANNED_START_DATE
	open @curs
	Fetch Next from @curs Into @it
	set @LEV = @LEV + 1
	while (@@fetch_status = 0)
		Begin
		print 'Adding  a child ' + @it
		exec A_SP_TASK_ADD_TO_TREE_TABLE @it,@LEV,@exAll
		Fetch Next from @curs Into @it
		End
	close @curs
	Deallocate @curs
	end
GO

/****** Object:  StoredProcedure [dbo].[A_SP_TASK_ADD_PROCEDURE_AS_CHILD_TASK]    Script Date: 6/3/2019 2:04:13 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE  PROCEDURE [dbo].[A_SP_TASK_ADD_PROCEDURE_AS_CHILD_TASK]
@newObjID varchar(50) OUTPUT,
@messages varchar(500) OUTPUT,
@PARENT_TASK_ID varchar(50),
@PROC_HIST_ID nvarchar(50),
@strNTLogin varchar(50)
AS
print 'Adding a procedure as a child task to an existing task ' + @PARENT_TASK_ID

declare 
	@PROC_ID varchar(50),
	@systemID varchar(50),
	@procedureName varchar(4000),
	@taskObject varchar(50),
	@newTaskID nvarchar(50),
	@taskComment nvarchar(2000), 
	@SUBMIT_STATUS varchar(50),
	@requesteeID varchar(50),
	@stepInAP varchar(10)

SELECT	@stepInAP = STEPS_IN_AP,
	@PROC_ID = ID,
	@procedureName = NAME,
	@systemID = SYSTEM_ID,
	@taskComment = 'Child Task = ' + @PARENT_TASK_ID
FROM A_V_PROCEDURES_APPROVED_DATA
WHERE HISTORY_REF_ID = @PROC_HIST_ID

SELECT @requesteeID = REQUESTEE_ID	FROM A_TASKS WHERE ID = @PARENT_TASK_ID

SELECT @taskObject = OBJECT_ID FROM A_TASK_OBJECT_LINK	WHERE TASK_ID = @PARENT_TASK_ID

makeTasks:
print '@requesteeID = ' + isNull(@requesteeID,'NULL')

if @requesteeID is null
	begin
		set @requesteeID = @strNTLogin
	end

print 'Making a new task now'
exec A_SP_TASKS_UPDATE_TASK @newTaskID OUTPUT,@messages OUTPUT,
	null, --ID
	@PARENT_TASK_ID, --Parent,
	@strNTLogin,--Requestor
	@requesteeID, --REQUESTEE_ID,
	null, --GROUP_REQUESTEE_ID
	@procedureName, --DESCRIPTION 
	@procedureName, --Title
	@systemID, --SYSTEM_TASK,
	@taskComment, --COMMENT,
	'3', --Security Level
	null, --counter
	null, --orig planned Start Date
	null, --orig planned stop date,
	null, --@ORIG_PLANNED_COUNTER_START numeric,
	null, --@ORIG_PLANNED_COUNTER_STOP numeric,
	null, --@CUR_PLANNED_START_DATE dateTime,
	null, --@CUR_PLANNED_STOP_DATE dateTime,
	null, --@CUR_PLANNED_COUNTER_START numeric,
	null, --@CUR_PLANNED_COUNTER_STOP numeric,
	null, --@ACTUAL_START_DATE dateTime,
	null, --@ACTUAL_STOP_DATE dateTime,
	null, --@ACTUAL_COUNTER_START numeric,
	null, --@ACTUAL_COUNTER_STOP numeric,
	@PROC_ID, --@REF_PROC_LIST varchar(8000),
	null, --@REF_FILE_LIST varchar(8000),
	null, --@DISCUSSIONS varchar(8000),
	null, --@SURVEYS varchar(8000),
	null, --@MEETINGS varchar(8000),
	@taskObject, --Object varchar(8000),
	null, --@COMPANIES varchar(8000),
	null, --@SYSTEM_PEOPLE_TO_EMAIL varchar(8000),
	'1', --@PRIORITY smallInt,
	null, --@ADDITIONAL_ASSIGNEES varchar(8000),
	@strNTLogin --strNTLogin
	print 'Created A Task with the ID of ' + @newTaskID
	set @newObjID = @newTaskID

	UPDATE A_TASKS SET PROCEDURE_ID = @PROC_ID WHERE ID = @newTaskID
print 'Create all the monitors for the task'
	exec A_SP_TASK_CREATE_MONITORS_FROM_PROCEDURE_INFO @newTaskID,@strNTLogin


print 'Now we need to make sure all the child tasks are under way as well.'
declare @sql varchar(8000)
set @sql = 'exec A_SP_TASK_CREATE_CHILD_TASKS_FOR_PROCEDURE_STEPS ''' + @newTaskID + ''',''' + @strNTLogin + ''''
print @sql
exec (@sql)

print ' Now accept the task'
set @sql = 'exec A_SP_TASK_ACCEPT null,null,''' + @newTaskID + ''',''' + @requesteeID + ''''
print @sql
exec(@sql)
fin:
GO

