SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE                 PROCEDURE [dbo].[A_SP_QUOTE_ITEM_UPDATE_ITEM]
@newID nvarchar(50) OUTPUT,
@messages nvarchar(2000) OUTPUT,
@QUOTE_OBJ_ID varchar(50),
@ID varchar(50),
@PROD_OR_LIST varchar(50),
@QTY varchar(50),
@RECURRING nvarchar(50),
@SPECIAL_DISCOUNT varchar(50),
@PROD_PRICE_LIST nvarchar(50),
@SPECIAL_DIS_REASON nvarchar(4000),
@COMMENT nvarchar(4000),
@PARENT_ID varchar(50),
@PROC_SYS_ID varchar(50),
@dest varchar(50),
@FROM_LOC varchar(50),
@TO_LOC varchar(50),
@UNIT_PRICE varchar(50),
@UNIT_ESTIMATE varchar(50),
@TYP_PROD_TIME varchar(50),
@TYP_PROD_TIME_UNIT varchar(50),
@TYP_PROD_CAPACITY varchar(50),
@TYP_PROD_CAPACITY_UNIT varchar(50),
@MAX_QTY_AT_ONE_TIME varchar(50),
@MAX_QTY_EVER varchar(50),
@MIN_QTY varchar(50),
@DEBIT_ACCOUNT_TRIGGER varchar(50),
@CANCELATION_FEE varchar(50),
@strNTLogin varchar(50)
AS
if @QUOTE_OBJ_ID is null or @PROD_OR_LIST is null goto fin

print 'In A_SP_QUOTE_ITEM_UPDATE_ITEM'
declare @PRODUCT as varchar(50)

print 'So, PROD_OR_LIST is either the price list or the product, we need to check that out'
print 'Check to see if it is the Product first'
declare @prodTester as varchar(50)
SELECT @prodTester = ID FROM A_V_PRODUCTS_APPROVED_DATA WHERE ID = @PROD_OR_LIST
if @prodTester is null
	begin
	print 'This is not the product, so it must be the list price'
	SELECT @PRODUCT = PRODUCT FROM A_V_PROD_PRICE_LIST_BY_APPROVED_ID WHERE ID = @PROD_OR_LIST
	print 'They must have picked a new list price so set the list price = ' + @PROD_OR_LIST
	SET @PROD_PRICE_LIST = @PROD_OR_LIST
	end
else
	begin
	print 'The selected Item is still a product so we need to assume they did not change anything.'
	SET @PRODUCT = @PROD_OR_LIST
	end

print 'Got the Product ID of ' + @PRODUCT
print 'Got the Product List Price ID of  ' + @PROD_PRICE_LIST

print 'Since the quote Object ID could be need to get the real ID'
declare @QUOTE_ID as varchar(50)
SELECT @QUOTE_ID = ID FROM A_QUOTES_HISTORY WHERE OBJECT_ID = @QUOTE_OBJ_ID
print 'Got the real Quote ID of ' + @QUOTE_ID

print 'A_SP_QUOTE_ITEM_UPDATE_ITEM for quote = ' + isNull(@QUOTE_ID,'NULL')
if @ID is null
	begin
	exec sp_GetUniqueID3 @ID OUTPUT
	print 'Got a new ID for this one ' + @ID
	INSERT INTO A_QUOTE_ITEMS (ID,QUOTE_ID,PRODUCT_ID,DRCM,MODBY)
	VALUES (@ID,@QUOTE_ID,@PRODUCT,getDate(),@strNTLogin)
	end
UPDATE A_QUOTE_ITEMS
SET
PRODUCT_ID = @PRODUCT,
DRCM = getDate(),
MODBY = @strNTLogin,
QTY = @QTY,
RECURRING = @RECURRING,
SPECIAL_DISCOUNT = @SPECIAL_DISCOUNT,
SPECIAL_DISC_REASON = @SPECIAL_DIS_REASON,
COMMENTS = @COMMENT,
PROD_PRICE_LIST = @PROD_PRICE_LIST,
PROC_SYS_ID = @PROC_SYS_ID,
DEST = @DEST,
FROM_LOC = @FROM_LOC,
TO_LOC = @TO_LOC,
UNIT_PRICE = @UNIT_PRICE,
UNIT_ESTIMATE = @UNIT_ESTIMATE,
TYP_PROD_TIME = @TYP_PROD_TIME,
TYP_PROD_TIME_UNIT = @TYP_PROD_TIME_UNIT,
TYP_PROD_CAPACITY = @TYP_PROD_CAPACITY,
MAX_QTY_AT_ONE_TIME = @MAX_QTY_AT_ONE_TIME,
MAX_QTY_EVER = @MAX_QTY_EVER,
MIN_QTY = @MIN_QTY,
DEBIT_ACCOUNT_TRIGGER = @DEBIT_ACCOUNT_TRIGGER,
TYP_PROD_CAPACITY_UNIT = @TYP_PROD_CAPACITY_UNIT,
CANCELATION_FEE = @CANCELATION_FEE
WHERE ID = @ID

if @PARENT_ID is not null UPDATE  A_QUOTE_ITEMS SET PARENT = @PARENT_ID WHERE ID = @ID

print 'If this was a shipping procedure we will need to make the precedents of the parent to follow it'
if @PROC_SYS_ID = 'SYS_SHIPPING'
	begin
		if @DEST = 'to'
			begin
			print 'Update the precednce of the parent to follow this one'
			DELETE FROM A_QUOTE_ITEM_PRECEDENTS WHERE FOL = @PARENT_ID AND PREV = @ID
			INSERT INTO A_QUOTE_ITEM_PRECEDENTS (ID,FOL,PREV,DRCM,MODBY) VALUES(newID(),@PARENT_ID,@ID,getDate(),@strNTLogin)
			end
		if @DEST = 'from'
			begin
			print 'Update the precednce of the child to follow the parent'
			DELETE FROM A_QUOTE_ITEM_PRECEDENTS WHERE FOL =  @ID AND PREV = @PARENT_ID
			INSERT INTO A_QUOTE_ITEM_PRECEDENTS (ID,PREV,FOL,DRCM,MODBY) VALUES(newID(),@PARENT_ID,@ID,getDate(),@strNTLogin)
			end
	end

exec A_SP_QUOTE_ITEM_UPDATE_CHILD_QUOTE_ITEMS @ID,@strNTLogin
exec A_SP_QUOTE_ITEM_SET_PRICE @ID,@strNTLogin
--Update the unit price to the overide price if necessary
declare @parent as varchar(50)
SELECT @parent = PARENT FROM A_ORDER_ITEMS WHERE ID = @ID
exec A_SP_QUOTE_ITEM_SET_PRICE @parent,@strNTLogin
set @newID = @ID

fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_QUOTE_ITEM_UPDATE_CHILD_QUOTE_ITEMS]    Script Date: 6/3/2019 2:04:57 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO







CREATE       PROCEDURE [dbo].[A_SP_QUOTE_ITEM_UPDATE_CHILD_QUOTE_ITEMS] 
@ID varchar(50),
@strNTLogin varchar(50)
AS

declare @myQuoteID as varchar(50)

print 'Adding the child quotes for quote item = ' + @ID
print 'We need to get the quote id'
SELECT @myQuoteID = QUOTE_ID FROM A_QUOTE_ITEMS WHERE ID = @ID

print 'Now Insert all the child prod prices and qtys as sub order items'
declare @pplID varchar(50),@qty as real
SELECT @pplID = PROD_PRICE_LIST,@qty = QTY FROM A_QUOTE_ITEMS WHERE ID = @ID

print 'We have the price list now we need to figure out what the children price lists are and add them if they are not in here already'
declare @newID varchar(50),
		@CHILD varchar(50),
		@CHILD_QTY varchar(50),
		@CHILD_PRODUCT_ID varchar(50)
Declare @it nvarchar(50)
Declare @curs Cursor
set @curs = Cursor For SELECT CHILD_ID,QTY,PRODUCT
	FROM A_V_PROD_PRICE_LIST_APPROVED_CHILDREN_WITH_PARENT WHERE PARENT_ID = @pplID
	AND CHILD_ID NOT IN (SELECT PROD_PRICE_LIST FROM A_QUOTE_ITEMS WHERE PARENT = @ID)
open @curs
Fetch Next from @curs Into @CHILD,@CHILD_QTY,@CHILD_PRODUCT_ID
while (@@fetch_status = 0)
Begin
	exec sp_GetUniqueID3 @newID OUTPUT
	INSERT INTO A_QUOTE_ITEMS (ID,QUOTE_ID,PARENT,PROD_PRICE_LIST,DRCM,MODBY,QTY,PRODUCT_ID)
	values (@newID,@myQuoteID,@ID,@CHILD,getDate(),@strNTLogin,@CHILD_QTY,@CHILD_PRODUCT_ID)
	Fetch Next from @curs Into @CHILD,@CHILD_QTY,@CHILD_PRODUCT_ID
End
close @curs
Deallocate @curs

print 'Just finished adding them'
print 'Updating the children quote Items figuring out their price and all that jazz ' + @pplID
declare @pDisc as varchar(50), @cnt as int
declare @pDiscReason as nvarchar(4000)
set @cnt = 0
set @curs = Cursor For SELECT ID FROM A_QUOTE_ITEMS WHERE PARENT = @ID
open @curs
Fetch Next from @curs Into @it
while (@@fetch_status = 0)
Begin
	print 'We are looking at the child which is  = ' + @it
	if @cnt = 0 
		begin
		select @pDisc = SPECIAL_DISCOUNT, @pDiscReason = SPECIAL_DISC_REASON FROM A_ORDER_ITEMS WHERE ID = @ID
		UPDATE A_QUOTE_ITEMS SET SPECIAL_DISCOUNT = NULL, SPECIAL_DISC_REASON = NULL WHERE ID = @ID
		end
	if @pDisc is not null
		begin
		
		UPDATE A_QUOTE_ITEMS SET SPECIAL_DISCOUNT = @pDisc, SPECIAL_DISC_REASON = @pDiscReason WHERE ID = @it
		end
	exec A_SP_QUOTE_ITEM_UPDATE_CHILD_QUOTE_ITEMS @it,@strNTLogin
	exec A_SP_QUOTE_ITEM_SET_PRICE @it,@strNTLogin
	set @cnt = @cnt + 1
	Fetch Next from @curs Into @it
End
close @curs
Deallocate @curs

exec A_SP_QUOTE_ITEM_SET_PRICE @ID,@strNTLogin
GO

/****** Object:  StoredProcedure [dbo].[A_SP_QUOTE_ITEM_SET_PRICE]    Script Date: 6/3/2019 2:04:57 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO










CREATE          procedure [dbo].[A_SP_QUOTE_ITEM_SET_PRICE] 
@ID varchar(50),
@strNTLogin varchar(50)
AS
print 'Get the parent ID and Parent Qty of ID = ' + @ID
declare @parentQTY as int
declare @parentID as varchar(50)
declare @myPPL as varchar(50)
declare @specDisc as real
SELECT @parentID = p.ID, @parentQTY = isNULL(p.QTY,1),
	@myPPL = c.PROD_PRICE_LIST,
	@specDisc = isNull(c.SPECIAL_DISCOUNT,0)
	FROM  A_QUOTE_ITEMS c LEFT OUTER JOIN
          A_QUOTE_ITEMS p ON c.PARENT = p.ID
	WHERE c.ID = @ID

print 'SELECT  p.ID, p.QTY,c.PROD_PRICE_LIST,
	c.SPECIAL_DISCOUNT FROM A_QUOTE_ITEMS p, A_QUOTE_ITEMS c
	WHERE c.PARENT =+ p.ID AND c.ID = ''' + @ID + ''''

print 'Special Discount = ' 
print @specDisc
print 'PPL = '
print @myPPL
print 'Get a total of the children unit prices'
declare @tester as varchar(50)
SELECT @tester = ID FROM A_QUOTE_ITEMS WHERE PARENT =@ID
declare @myPrice REAL
declare @childPrice REAL
declare @totalPrice REAL



if @tester is not null
	begin
	SELECT @childPrice = SUM((TOTAL_PRICE)) FROM A_QUOTE_ITEMS WHERE PARENT = @ID
	print 'The price of my children is '
	print @childPrice
	SELECT @myPrice = UNIT_PRICE FROM A_QUOTE_ITEMS WHERE ID = @ID
	if @myPrice is NULL
		begin
		print 'Getting Price from PPL '
		print 'SELECT UNIT_PRICE FROM A_V_PROD_PRICE_LIST_BY_APPROVED_ID WHERE ID = ' + isNULL('''' + @myPPL + '''',NULL)
		SELECT @myPrice = UNIT_PRICE FROM A_V_PROD_PRICE_LIST_BY_APPROVED_ID WHERE ID = @myPPL
		end
	print 'My Unit Price = ' + convert(varchar(50),@myPrice )
	set @totalPrice = isNull((1-(@specDisc/100)) * @myPrice,0) + isNull(@childPrice,0)
	end
else
	begin
	SELECT @myPrice = UNIT_PRICE FROM A_QUOTE_ITEMS WHERE ID = @ID
	if @myPrice is NULL
		begin
		print 'Getting Price from PPL '
		print 'SELECT UNIT_PRICE FROM A_V_PROD_PRICE_LIST_BY_APPROVED_ID WHERE ID = ' + isNULL('''' + @myPPL + '''',NULL)
		SELECT @myPrice = UNIT_PRICE FROM A_V_PROD_PRICE_LIST_BY_APPROVED_ID WHERE ID = @myPPL
		end 
	print 'MyUnit Price is '
	print convert(nvarchar(50),@myPrice)
	set @totalPrice = (1-(@specDisc/100)) * @myPrice
	end		

UPDATE A_QUOTE_ITEMS SET
	UNIT_PRICE = @myPrice,
	PARENT_QTY = @parentQTY, 
	TOTAL_QTY = isNULL(@parentQTY,1) * QTY,
	TOTAL_PRICE = (isNULL(@parentQTY,1) * QTY) * @totalPrice
WHERE ID = @ID

SELECT * FROM A_QUOTE_ITEMS WHERE ID = @ID
GO

