while (@@fetch_status = 0)
Begin
	print 'looking at task ID = ' + @taskID
	exec A_SP_TASK_UPDATE_BASED_ON_PURCHASE_INFO @taskID,@strNTLogin
	Fetch Next from @curs Into @taskID
End
close @curs
Deallocate @curs
