CREATE      PROCEDURE [dbo].[A_SP_PURCHASE_UPDATE_STATUS]
@phID varchar(50)
AS
print 'We are updating the status for Purchase Hist ID = ' + isNULL(@phID,'NULL')
declare @tester varchar(50), @ret varchar(50)
declare @c as CURSOR, @ordID varchar(50)
set @c = CURSOR FOR SELECT ID FROM A_ORDER_ITEMS WHERE PURCHASE_HIST_ID = @phID
open @c
fetch next from @c INTO @ordID
while @@fetch_status = 0
	begin
	exec A_SP_PURCHASE_ITEM_GET_ACCOUNT_STATUS @ret OUTPUT,@ordID
	if @ret = 'ITEM_NEEDS_ACCOUNT'
		begin
		UPDATE A_PURCHASES_HISTORY SET PURCHASE_STATUS = @ret
		goto fin
		end
	fetch next from @c INTO @ordID
	end
close @c
deallocate @c

UPDATE A_PURCHASES_HISTORY SET PURCHASE_STATUS = @ret WHERE ID = @phID

fin:
exec A_SP_PURCHASE_UPDATE_FORECAST_FUNNEL_FOR_PURCHASE_ITEMS @phID,'SYSTEM'
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PURCHASE_UPDATE_PURCHASE_STATUS]    Script Date: 6/3/2019 2:05:03 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE  PROCEDURE [dbo].[A_SP_PURCHASE_UPDATE_PURCHASE_STATUS]
@purchHistID varchar(50),
@strNTLogin varchar(50)
AS
if (EXISTS (SELECT * FROM A_FILLS WHERE PURCH_ITEM_ID IN (SELECT ID FROM A_ORDER_ITEMS
		WHERE PURCHASE_HIST_ID = @purchHistID AND FILL_OBJ_ID IS NULL)))
	begin
	UPDATE A_PURCHASES_HISTORY SET PURCHASE_STATUS = 'WAITING_FILLS' WHERE ID = @purchHistID
	end
else
	begin
	UPDATE A_PURCHASES_HISTORY SET PURCHASE_STATUS = 'ALL_FILLED' WHERE ID = @purchHistID
	end

declare @taskID varchar(50),@taskStatus varchar(50)
SELECT @taskID = TASK_ID FROM A_TASK_ORDER_INFORMATION WHERE 
	PURCHASE_HIST_ID = @purchHistID 
	AND PURCHASE_ITEM_ID IS NULL
	AND FILL_ID IS NULL
if @taskID is not null
	begin
	SELECT @taskStatus = STATUS FROM A_TASKS WHERE ID = @taskID
	UPDATE A_PURCHASES_HISTORY 
		SET PURCHASE_STATUS = 
		(SELECT case when (@taskStatus = 'REQUESED') then 'ALL_FILLED' 
		when (@taskStatus = 'PURCHASE_EXECUTING') then 'EXECUTING'
		when (@taskStatus = 'FINISHED') then 'FINISHED'
		when (@taskStatus = 'CLOSED') then 'CLOSED'
		else 'ALL_FILLED'
		end)
	WHERE ID = @purchHistID
	end
GO

