	UPDATE A_ORDER_ITEMS SET MT_NUM = @myNum WHERE ID = @purchItemID
	SELECT ID AS PURCHASE_ITEM_ID FROM A_ORDER_ITEMS WHERE ID = @purchItemID
	end




