print 'Invoicing order Item # ' + isNull(@ID,'NULL') + ' FILL ITEM ID = ' + isNull(@FILL_ITEM_ID,'NULL')
declare @acctID varchar(50),@price money,@invoiceID varchar(50),@nextInvoiceDate datetime,@firstInvoiceDate datetime,
