/****** Object:  StoredProcedure [dbo].[A_SP_PURCHASE_AUTO_FILL_IF_FUTURE_FILL_READY]    Script Date: 6/3/2019 2:05:14 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO




CREATE    PROCEDURE [dbo].[A_SP_PURCHASE_AUTO_FILL_IF_FUTURE_FILL_READY]
@purchID varchar(50),
@strNTLogin varchar(50)
AS
print 'Auto Filling if possible'
if not exists(SELECT * FROM A_PURCHASE_FUTURE_FILL_ITEM WHERE PURCHASE_ID = @purchID)
	goto fin

declare @fillObj varchar(50),@pHistID varchar(50),@taskID varchar(50),@creatorID varchar(50),
	@fillID varchar(50),@fillActPartID varchar(50),@fillActPartObjID varchar(50)
SELECT @fillObj = FILL_OBJ_ID, @creatorID = MODBY	FROM A_PURCHASE_FUTURE_FILL_ITEM WHERE PURCHASE_ID = @purchID
SELECT @fillActPartID = ROOT FROM A_OBJECTS WHERE ID = @fillObj
print 'We can auto fill this one with fill obj id  = ' + @fillObj
SELECT @pHistID = HISTORY_REF_ID FROM A_PURCHASES WHERE ID = @purchID
print 'get the task ID from phist = ' + @pHistID
SELECT @taskID = TASK_ID,@fillID = ID FROM A_V_FILLS_SEARCH WHERE PURCHASE_HIST_ID = @pHistID AND FILL_BY = 'CUSTOMER'
print 'Fill ID = ' + @fillID
declare @RET_STATUS as varchar(50),@MSGS as varchar(50)


exec A_SP_TASK_ACCEPT @RET_STATUS OUTPUT,@MSGS OUTPUT,@taskID,@creatorID
if @RET_STATUS is not NULL and @RET_STATUS <> ''
	begin
	print 'Error Accepting Task'
	goto fin
	end

if @fillObj is not null and @fillID is not null
	exec A_SP_FILLS_UPDATE_FILL @RET_STATUS OUTPUT,@MSGS OUTPUT,@fillID,@fillActPartID,@creatorID


fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PURCHASE_APPEND_ORDER]    Script Date: 6/3/2019 2:05:14 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO




CREATE    PROCEDURE [dbo].[A_SP_PURCHASE_APPEND_ORDER]
@newID varchar(50) OUTPUT,
@msgs varchar(2000) OUTPUT,
@strPurchaseObjID varchar(50),
@orderID varchar(50),
@strNTLogin varchar(50)
AS
begin Transaction
declare @purchID varchar(50)
SELECT @purchID = ID FROM A_PURCHASES_HISTORY WHERE OBJECT_ID = @strPurchaseObjID
create table #tempIDs (ID varchar(50))
print 'Adding all the items'
Declare @it nvarchar(50), @curs Cursor, @itemID varchar(50)
set @curs = Cursor For SELECT ID FROM A_V_ORDER_WITH_QUOTE_ITEMS WHERE ORDER_ID = @orderID and PURCHASE_HIST_ID IS NULL
open @curs
if @@error <> 0 goto PROBLEM
Fetch Next from @curs Into @it
if @@error <> 0 goto PROBLEM
declare @itemCount int
set @itemCount = 0
while (@@fetch_status = 0)
Begin
	set @itemCount = @itemCount + 1
	print 'Creating Item number ' + convert(varchar(50),@itemCount)
	exec sp_GetUniqueID3 @itemID OUTPUT
	insert into #tempIDs (ID) values(@itemID)
	if @itemCount = 1
		set @newID = @itemID
	print 'Adding a new Purchase Item with the ID of ' + @itemID + ' It is for old item # ' + @it
	INSERT INTO [dbo].[A_ORDER_ITEMS]
	([ID], [SOURCE_ID], [PARENT_QTY],  
	[PRODUCT_ID], [PROD_PRICE_LIST], [QUOTE_ID], 
	[PROC_SYS_ID], [ADD_COST_ID], [TOTAL_QTY], 
	[QTY], [UNIT_PRICE], [UNIT_ESTIMATE], 
	[COMMENTS], [DRCM], [MODBY], [TOTAL_PRICE], 
	[DEST], [FROM_LOC], [TO_LOC], [SPECIAL_DISCOUNT], 
	[SPECIAL_DISC_REASON], [EXPEDITE_PRODUCTION], 
	[EXPEDITE_REASON], [FLAT_RATE], [EX_DESC], 
	[EST_WEIGHT], [EST_WEIGHT_UNIT], [PPL_HIST_ID], 
	[RECURRING], [RECUR_PERIOD], [RECUR_COUNT], 
	[RECUR_START_DATE], [RECUR_STOP_DATE], 
	[RECUR_ACCOUNT], [RECUR_AUTO_FILL], [PURCHASE_HIST_ID])
	SELECT 
	@itemID, [ID], [PARENT_QTY],  
	[PRODUCT_ID], [PROD_PRICE_LIST], [QUOTE_ID], 
	[PROC_SYS_ID], [ADD_COST_ID], [TOTAL_QTY], 
	[QTY], [UNIT_PRICE], [UNIT_ESTIMATE], 
	[COMMENTS], getDate(), @strNTLogin, [TOTAL_PRICE], 
	[DEST], [FROM_LOC], [TO_LOC], [SPECIAL_DISCOUNT], 
	[SPECIAL_DISC_REASON], [EXPEDITE_PRODUCTION], 
	[EXPEDITE_REASON], [FLAT_RATE], [EX_DESC], 
	[EST_WEIGHT], [EST_WEIGHT_UNIT], [PPL_HIST_ID], 
	[RECURRING], [RECUR_PERIOD], [RECUR_COUNT], 
	[RECUR_START_DATE], [RECUR_STOP_DATE], 
	[RECUR_ACCOUNT], [RECUR_AUTO_FILL], @purchID
	FROM A_ORDER_ITEMS WHERE ID = @it
	if @@error <> 0 goto PROBLEM	
	print 'Inserted an Order ITem'
	Fetch Next from @curs Into @it
End
close @curs
Deallocate @curs

print 'Added all the items now I need to put all the precedents in'
INSERT INTO A_ORDER_ITEM_PRECEDENTS (ID,PREV,FOL,DRCM,MODBY)
SELECT newID(),PREV_ID,FOL_ID,getDate(),@strNTLogin FROM A_V_QUOTE_PRECEDENTS_FROM_ORDER_IDS WHERE PURCHASE_HIST_ID = @purchID

print 'Now I need to set up all the parent child relationships'
UPDATE A_ORDER_ITEMS SET PARENT = 
	(SELECT PARENT_ID 
		FROM A_V_QUOTE_ITEM_PARENTS_USING_ORDER_ITEM_FOR_RELATIONSHIP 
		WHERE CHILD_ID = A_ORDER_ITEMS.ID AND PARENT_ID IN (SELECT ID FROM #tempIDs))
WHERE PURCHASE_HIST_ID = @purchID AND A_ORDER_ITEMS.ID IN (SELECT ID FROM #tempIDs)

if @@error <> 0 goto PROBLEM


print 'Update the status of the whole purchase now'
exec A_SP_PURCHASE_UPDATE_STATUS @purchID

fin:
print 'Finished the Creating the Purchase with no problem'
--SELECT @newID =  OBJECT_ID FROM A_PURCHASES_HISTORY WHERE ID = @purchID
if @@trancount > 0 COMMIT TRANSACTION

declare @prodTime float,@prodUnit varchar(50),@parent varchar(50)
SELECT @prodTime = PRODUCTION_TIME, @prodUnit = PRODUCTION_TIME_UNIT,@parent = PARENT
	FROM A_V_ORDER_ITEMS_ALL_DATA WHERE ID = @itemID
print 'ORDER ITEM = ' + @itemID
print 'prod Unit = ' + @prodUnit
print @prodTime
if @prodTime is not null
	begin
	UPDATE A_ORDER_ITEMS SET DUE_DATE = dbo.A_FN_DATE_TIME_ADD_USING_UNITS(@prodUnit,getDate(),@prodTime) WHERE ID = @itemID
	UPDATE A_ORDER_ITEMS SET DUE_DATE = 
		(SELECT MAX(DUE_DATE) FROM A_ORDER_ITEMS WHERE PARENT = @parent)
		WHERE ID = @parent

	end


return 0

PROBLEM:
print 'There was some sort of problem makig the quote and we are going to not finish'
if @@TRANCOUNT > 0 ROLLBACK TRANSACTION
return 1
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PURCHASE_AGREEMENTS_SEARCH_FOR_ACTUAL_PART]    Script Date: 6/3/2019 2:05:15 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO


CREATE       PROCEDURE [dbo].[A_SP_PURCHASE_AGREEMENTS_SEARCH_FOR_ACTUAL_PART]
	@strWhere nvarchar(2000),
	@strSort nvarchar(1000),
	@actPartID varchar(50),
	@strNTLogin varchar(50)
AS
declare @myCO varchar(50),@partID varchar(50),@partTypeID varchar(50)

exec A_SP_GET_PERSON_COMPANY @strNTLogin,@myCO OUTPUT
print 'My Co = ' + @myCO
SELECT @partID = PART_ID FROM A_V_ACTUAL_PARTS_APPROVED_DATA WHERE ID = @actPArtID
SELECT @partTypeID = PART_TYPE FROM A_V_PARTS_APPROVED_DATA WHERE ID = @partID
create table #tempPossibleParts(ID varchar(50))
INSERT INTO #tempPossibleParts (ID) VALUES (@partID)
INSERT INTO #tempPossibleParts (ID) 
	SELECT EXT_PART_ID FROM A_V_PARTS_EXTERNAL_PART_LOOKUP WHERE INT_PART_ID = @partID
INSERT INTO #tempPossibleParts (ID) 
	SELECT INT_PART_ID FROM A_V_PARTS_EXTERNAL_PART_LOOKUP WHERE EXT_PART_ID = @partID
declare @so varchar(8000)
exec A_SP_Z_UTIL_GET_COMMA_ID_LIST 'SELECT ID FROM #tempPossibleParts',@so OUTPUT

declare @sql nvarchar(4000)
set @sql = 
'SET QUOTED_IDENTIFIER OFF 
	SELECT DISTINCT * FROM A_V_ORDERS_WITH_ITEMS_AND_APPLICABLE_OBJECTS o1 WHERE 
(
	(
		(
		o1.APP_OBJECT IN (''' + replace(@so,',',''',''') + ''')
		) 
	AND PARENT IS NULL
	and not exists
	(SELECT * FROM A_V_ORDERS_WITH_ITEMS_AND_APPLICABLE_OBJECTS o2 WHERE 
		o1.ORDER_ID = o2.ORDER_ID 
		AND 
		NOT
			(
		o1.APP_OBJECT IN (''' + replace(@so,',',''',''') + ''')
			)

		AND PARENT IS NULL )  
	)
	or
	(
	o1.APP_OBJECT = ''' + isNull(@partTypeID,'')  + ''' 
	AND PARENT IS NULL
	and not exists
	(SELECT * FROM A_V_ORDERS_WITH_ITEMS_AND_APPLICABLE_OBJECTS o2 WHERE o1.ORDER_ID = o2.ORDER_ID AND o2.APP_OBJECT <> ''' + isNull(@partTypeID,'') + ''' AND PARENT IS NULL )  
	)
)
'
if len(@strWhere) > 0
		set @sql = @sql + ' AND ' + @strWhere + ' '

if len(@strSort) > 0
		set @sql = @sql + @strSort

print isNull(@sql,'NULL')
drop table #tempPossibleParts
exec (@sql)
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PURCHASE_ADD_QUOTE_LINK]    Script Date: 6/3/2019 2:05:15 PM ******/
