/****** Object:  StoredProcedure [dbo].[A_SP_PRODUCT_GET_PURCHASING_DETAIL_DATA]    Script Date: 6/3/2019 2:05:31 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO



CREATE  PROCEDURE [dbo].[A_SP_PRODUCT_GET_PURCHASING_DETAIL_DATA] 
@prodID varchar(50),
@pplID varchar(50),
@strNTLogin varchar(50)
AS
declare @myRootCo varchar(50),@myCo varchar(50)
SELECT @myRootCo = ROOT_COMPANY,@myCo = COMPANY FROM A_V_PEOPLE_APPROVED_DATA

print 'Getting the product purchasing details info.'
CREATE TABLE #tempP (
	PPL_ID varchar(50),
	PRODUCT_NAME nvarchar(1000),
	PRODUCT_ID varchar(50),
	MIN_QUANTITY float,
	PRODUCTION_TIME float,
	PRODUCTION_TIME_UNIT varchar(50),
	CAPACITY float,
	CAPACITY_UNIT varchar(50),
	SUPPLIER_ID varchar(50),
	SUPPLIER_PN nvarchar(100),
	SUPPLIER_PART_NAME nvarchar(200),
	CUSTOMER_PN nvarchar(50),
	CUSTOMER_PART_NAME nvarchar(200),
	SUPPLIER_NAME varchar(50),
	PROCEDURE_ID varchar(50),
	PROC_SYS_ID varchar(50),
	SUP_PART_ID varchar(50),
	CUST_PART_ID varchar(50),
	SUP_OBJ_ID varchar(50),
	CUST_OBJ_ID varchar(50),
	AVAILABILITY tinyInt
)
INSERT INTO #tempP (
	PPL_ID,
	PRODUCT_NAME,
	PRODUCT_ID,
	MIN_QUANTITY,
	PRODUCTION_TIME,
	PRODUCTION_TIME_UNIT,
	CAPACITY,
	CAPACITY_UNIT
)
	SELECT 
	ID,
	PRODUCT_NAME,
	PRODUCT,
	MIN_QUANTITY,
	PRODUCTION_TIME,
	PRODUCTION_TIME_UNIT,
	CAPACITY,
	CAPACITY_UNIT
		FROM A_V_PROD_PRICE_LIST_APPROVED_DATA WHERE ID = @pplID

declare @supplierID varchar(50),@procID varchar(50),@appObjID varchar(50)
SELECT @supplierID = SUPPLIER_ID,@procID = PROCEDURE_ID,@appObjID = APP_OBJECT 
	FROM A_V_PRODUCTS_APPROVED_DATA WHERE ID = (SELECT PRODUCT_ID FROM #tempP)
UPDATE #tempP SET SUPPLIER_ID = @supplierID,PROCEDURE_ID = @procID
UPDATE #tempP SET SUPPLIER_NAME = (SELECT NAME FROM A_V_COMPANIES_APPROVED_DATA WHERE ID = @supplierID)
UPDATE #tempP SET AVAILABILITY = (SELECT AVAILABILITY FROM A_V_PRODUCTS_APPROVED_DATA WHERE ID = (SELECT PRODUCT_ID FROM #tempP)) 

declare @histID varchar(50),@objTable varchar(50)
SELECT @histID = OBJ_ID, @objTable = OBJ_TABLE 
	FROM A_OBJECTS 
	WHERE ROOT = @appObjID AND STATUS LIKE 'APPROVED%'


declare @supPartHistID varchar(50),@supPartNum nvarchar(1000),@custPartID varchar(50), @custPartNum nvarchar(1000),
	@supPartName nvarchar(1000),@custPartName nvarchar(1000),@custPartHistID varchar(50), @supObjID varchar(50),
	@custObjID varchar(50),@supPartID varchar(50)
if @objTable = 'A_PARTS_HISTORY' 
	begin
	SELECT @supPartHistID = ID,@supPartNum = COMPANY_PART_NUMBER,@supPartName = NAME,@supObjId = OBJECT_ID
		FROM A_PARTS_HISTORY WHERE ID = @histID
	SELECT @supPartID = ROOT FROM A_OBJECTS WHERE ID = @supObjID
	UPDATE #tempP SET SUP_OBJ_ID= @supObjID,SUPPLIER_PN = @supPartNum,SUPPLIER_PART_NAME = @supPartName,SUP_PART_ID = @appObjID

	end



declare @procSysID varchar(50)
SELECT @procSysID =  SYSTEM_ID
	FROM A_V_PROCEDURES_APPROVED_DATA WHERE ID = (SELECT PROCEDURE_ID FROM #tempP)
UPDATE #tempP SET PROC_SYS_ID = @procSysID
--if @procSysID = 'SYS_PROVIDE_AND_STAY'
--	begin
	print 'This is a provide and stay'
	if @supplierID <> @myCo and @supplierID <> @myRootCo
		begin
		print 'We need to figure out the customer Part Number too.'
		print 'The supplier part history number is ' + @supPartID
		SELECT @custPartHistID = dbo.A_SP_PART_FIND_MY_RELATED_PART(@supPartID,@strNTLogin)
		print 'The Part ID = ' + isNull(@custPartHistID,'NULL')
		if @custPartHistID is not null
			begin
			print 'Looking for my part' + @custPartHistID
			SELECT @custPartNum = COMPANY_PART_NUMBER,@custPartName = NAME,@custPartID = OBJECT_ID,@custObjId = OBJECT_ID
				FROM A_PARTS_HISTORY WHERE ID = @custPartHistID
			UPDATE #tempP SET CUST_OBJ_ID= @custObjID,CUSTOMER_PN = @custPartNum,CUSTOMER_PART_NAME = @custPartName,CUST_PART_ID = @custPartID
			end


		end

--	end








SELECT * FROM #tempP
DROP TABLE #tempP
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PRODUCT_GET_PART_AVAILABILITY_FOR_LOCATION]    Script Date: 6/3/2019 2:05:31 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[A_SP_PRODUCT_GET_PART_AVAILABILITY_FOR_LOCATION] 
@ID varchar(50) OUTPUT,
@msgs varchar(50) OUTPUT,
@locID varchar(50),
@prodID varchar(50),
@PPL_ID varchar(50),
@strNTLogin varchar(50)
AS
print 'Getting the product parts availibility for the loc = ' + @locID


declare @pplHistID varchar(50)
SELECT @pplHistID = HISTORY_REF_ID FROM A_PROD_PRICE_LIST WHERE ID = @PPL_ID

CREATE TABLE #partsList (
	PART_ID varchar(50),
	QTY float
)

INSERT INTO #partsList (QTY,PART_ID)
SELECT sl.QTY,o.ROOT FROM 
A_PROD_PRICE_LIST_SUB_PRICE_LISTS sl,
A_APPROVED_OBJECTS ao,
A_OBJECTS o
WHERE 
sl.PARENT = @pplHistID 
and sl.RELATIONSHIP = 'PARTS_PROVIDE_STAY'
and ao.ID = APPROVED_OBJ_ID
and o.ID = ao.OBJ_REF_ID 
and o.OBJ_TABLE = 'A_PARTS_HISTORY'

CREATE TABLE #partsListSummary (
	ID int Identity,
	PART_ID varchar(50),
	PART_NAME nvarchar(50),
	QTY float,
	LOCATION_NAME nvarchar(1000),
	QTY_HAVE float,
	QTY_DIFF float,
	MAX_MAKE float
)

INSERT INTO #partsListSummary (PART_ID,PART_NAME,QTY,LOCATION_NAME,QTY_HAVE)
SELECT prod.PART_ID,ap.PART_DESC,prod.QTY,LOCATION_NAME,SUM(ap.QTY) 
	FROM #partsList prod LEFT OUTER JOIN
                      A_V_ACTUAL_PARTS_APPROVED_DATA ap ON prod.PART_ID = ap.PART_ID
	WHERE ap.LOCATION = @locID
	GROUP BY prod.PART_ID,ap.PART_DESC,prod.QTY,LOCATION_NAME


UPDATE #partsListSummary SET MAX_MAKE = round(QTY_HAVE / QTY,0)

SELECT @ID = convert(varchar(50),min(MAX_MAKE)) FROM #partsListSummary
INSERT INTO #partsListSummary (PART_NAME,QTY)
	VALUES('ZZZZZZZZZZZZZZZ_NO_NAME',@ID)

print 'ID = ' + isnull(@ID,'NULL')
SELECT * FROM #partsListSummary
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PRODUCT_GET_OPPURTUNITY_NUMBERS]    Script Date: 6/3/2019 2:05:32 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO




CREATE     PROCEDURE [dbo].[A_SP_PRODUCT_GET_OPPURTUNITY_NUMBERS]
	@ID nvarchar(50),
	@strNTLogin nvarchar(50)
AS
print 'Create the Temp Table'
CREATE TABLE #TempItems	(ID varchar(50),TOT int,HAVE int,NEED int,CUST_ID varchar(50))
Declare @it nvarchar(50)
declare @tot int,@have int,@need int
Declare @curs Cursor
print 'We are making a cursor'


set @curs = Cursor For SELECT DISTINCT(CUR_OWNER) FROM A_V_PRODUCTS_WITH_ACTUAL_PARTS_THEY_ARE_USED_ON 
	WHERE PRODUCT_ID = @ID
open @curs
Fetch Next from @curs Into @it
while (@@fetch_status = 0)
Begin
	print 'Finding oppurtunity data for customer = ' + @it
	SELECT @TOT =  SUM(QTY) FROM A_V_PRODUCTS_WITH_ACTUAL_PARTS_THEY_ARE_USED_ON
		WHERE PRODUCT_ID = @ID AND CUR_OWNER = @it
	print 'Total possible = '
	print @TOT
	print 'The Product ID = ' + @ID + ' And the cur oxer = ' + @it
	SELECT @have = SUM(QTY) FROM A_V_PRODUCTS_WITH_ACTUAL_PARTS_THEY_ARE_USED_ON
		WHERE PRODUCT_ID = @ID AND CUR_OWNER = @it AND PROD_STATUS = 'PROD_INSTALLED'
	print 'Total Have = '
	set @have = isNull(@have,0)
	print @have
	set @need = @tot - @have
	INSERT INTO #TempItems (ID,TOT,HAVE,NEED,CUST_ID) VALUES 
	(@ID,@tot,@have,@need,@it)
	Fetch Next from @curs Into @it
End
close @curs
Deallocate @curs


SELECT t.*
,c.NAME AS CO_NAME
,p.NAME AS PRODUCT_NAME
,p.ID AS PRODUCT_ID
FROM #TempItems t
,A_V_COMPANIES_APPROVED_DATA c
,A_V_PRODUCTS_APPROVED_DATA p
where 
t.CUST_ID = c.ID 
AND t.ID = p.ID
GO

