CREATE PROCEDURE [dbo].[A_SP_PROD_PRICE_LIST_GET_CHILDREN_PRICE_LISTS]
-- '5936','PARTS_PROVIDE_TAKE_BACK','5203' 
@PPL_ID varchar(50),
