	exec A_SP_PROCEDURE_STEP_FIGURE_OUT_LAST_MOD_DATE @stepID



	fetch next from @curs into @stepID
	end





success:
goto fin

problem:
print 'Could not find a PH_ID to update the steps last modified dates'

fin:
GO

