CREATE  PROCEDURE [dbo].[A_SP_PROCEDURE_STEPS_CREATE_ALL_RELATED_STEPS]
@procHistID varchar(50)
as
delete FROM A_PROCEDURE_STEPS_RELATED_STEPS WHERE 
	(
	STEP_ID in (SELECT ID FROM A_PROCEDURE_STEPS WHERE PROCEDURE_ID = @procHistID)
	OR
	REL_STEP_ID in (SELECT ID FROM A_PROCEDURE_STEPS WHERE PROCEDURE_ID = @procHistID)
	)
declare @curs as cursor,@stepID varchar(50)
set @curs = CURSOR FOR SELECT ID FROM A_PROCEDURE_STEPS s WHERE OLD_STEP_ID is null and 
	exists(SELECT ID FROM A_PROCEDURE_STEPS WHERE OLD_STEP_ID = s.ID)
	and PROCEDURE_ID = @procHistID
open @curs
declare @cnt as int
set @cnt = 1
fetch NEXT FROM @curs into @stepID
while @@fetch_status = 0
begin
	print @cnt
	set @cnt = @cnt + 1
	print 'Finding all related steps to step = ' + @stepID
	exec A_SP_PROCEDURE_STEPS_CREATE_RELATED_STEPS_FOR_ONE @stepID
	fetch NEXT FROM @curs into @stepID
end
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PROCEDURE_STEPS_COMPARE_TWO_STEPS]    Script Date: 6/3/2019 2:05:53 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[A_SP_PROCEDURE_STEPS_COMPARE_TWO_STEPS]
@hasChanged tinyint OUTPUT,
@step1 varchar(50),
@step2 varchar(50)
AS
print 'Looking for differences between ' + @step1 + ' and ' + @step2
if @step1 = @step2
	goto isSame
print 'Checking text'
if not exists (SELECT ID FROM A_PROCEDURE_STEPS table1 
				WHERE ID = @step1 AND 
					EXISTS(
						SELECT * FROM A_PROCEDURE_STEPS table2 
						WHERE ID = @step2 AND table2.STEP_TEXT = table1.STEP_TEXT
					)
				)
	begin
	print 'These are different'
	goto isDifferent
	end





isSame:
set @hasChanged = 0
goto fin
isDifferent:
set @hasChanged = 1
goto fin


fin:
GO

