/****** Object:  StoredProcedure [dbo].[A_SP_PROCEDURE_SET_PRINT_ORDER]    Script Date: 6/3/2019 2:06:01 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE     PROCEDURE [dbo].[A_SP_PROCEDURE_SET_PRINT_ORDER]
@PID nvarchar(50),
@strNTLogin nvarchar(50)
AS

declare @PRINT_ORDER as int
set @PRINT_ORDER = 1

print 'so first we are going to set all the null steps to be print order 1'
UPDATE A_PROCEDURE_STEPS SET PRINT_ORDER = '1' WHERE PROCEDURE_ID = @PID
declare @maxCnt as integer
SELECT @maxCnt = count(ID) FROM A_PROCEDURE_STEPS WHERE PROCEDURE_ID = @PID

print 'Now that we have done that we should set the rest of them = to max until we set them really'
UPDATE A_PROCEDURE_STEPS SET PRINT_ORDER = @maxCnt
WHERE PROCEDURE_ID = @PID AND 
ID IN 
(SELECT MY_STEP 
	FROM A_PROCEDURE_STEP_PRECEDING_STEPS 
	WHERE PROCEDURE_ID = @PID AND PREV_STEP is not NULL)

print 'Now We are going to have to go through the steps exactly maxCnt times to make sure we set them properly'
declare @cnt as int
set @cnt = 1

while @cnt < @maxCnt
	begin
	UPDATE A_PROCEDURE_STEPS SET PRINT_ORDER = (@cnt + 1) 
	WHERE ID in
		(SELECT MY_STEP 
		FROM A_V_PROCEDURE_STEP_PREV_W_PRNT_ORDER 
		WHERE PROCEDURE_ID = @PID AND PRINT_ORDER =@cnt)
	set @cnt = @cnt + 1
	end
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PROCEDURE_SECTION_REORDER_COMMENTS]    Script Date: 6/3/2019 2:06:02 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE procedure [dbo].[A_SP_PROCEDURE_SECTION_REORDER_COMMENTS]
@ID as varchar(50),
@LOC as varchar(50)
AS
declare @curs as CURSOR,
	@it as varchar(50)
Declare @counter int  
set @counter =0
print 'Reordering the comments for the procedure ' + @ID + 'AND LOC = ' + @LOC
set @curs = Cursor For 
SELECT ID FROM A_PROCEDURE_COMMENTS WHERE PROC_HIST_ID = @ID AND LOC = @LOC
	ORDER BY PRINT_ORDER
open @curs
Fetch Next from @curs Into @it
while (@@fetch_status = 0)
	Begin
	set @counter = @counter +1 
	print 'reordering= ' + @it
        print 'counter = ' + convert(varchar(50),@counter)	
	UPDATE A_PROCEDURE_COMMENTS SET PRINT_ORDER = @counter WHERE ID = @it
 	Fetch Next from @curs Into @it
	End
close @curs
Deallocate @curs
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PROCEDURE_ROLL_UP_DURATION]    Script Date: 6/3/2019 2:06:02 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO



CREATE   PROCEDURE [dbo].[A_SP_PROCEDURE_ROLL_UP_DURATION]
@ID varchar(50)
AS
declare @totSecs as float
SELECT @totSecs = sum(s.DURATION * t.SECS)
	FROM dbo.A_PROCEDURE_STEPS s INNER JOIN
         dbo.A_Z_UNITS_TIME_TO_SECS t ON s.DURATION_TYPE = t.FROM_UNIT
	WHERE s.PROCEDURE_ID = @ID
print '@totSecs = ' + convert(varchar(50),@totSecs)
declare @maxUnit float
SELECT @maxUnit = max(t.SECS) 
	FROM dbo.A_PROCEDURE_STEPS s INNER JOIN
         dbo.A_Z_UNITS_TIME_TO_SECS t ON s.DURATION_TYPE = t.FROM_UNIT
	WHERE s.PROCEDURE_ID = @ID
print 'max unit = ' + convert(varchar(50),@maxUnit)
declare @maxUnitID varchar(50)
SELECT @maxUnitID = FROM_UNIT FROM A_Z_UNITS_TIME_TO_SECS WHERE SECS = @maxUnit
print 'id = ' + @maxUnitID
declare @totOfMaxUnit float
set @totOfMaxUnit = @totSecs / @maxUnit
print 'tot of Unit = ' + convert(varchar(50),@totOfMaxUnit)
declare @currentTime float
SELECT @currentTime = (p.DURATION * T.SECS) 
	FROM A_PROCEDURES_HISTORY p INNER JOIN A_Z_UNITS_TIME_TO_SECS t
		ON p.DURATION_TYPE = t.FROM_UNIT
		WHERE p.ID = @ID
print 'procTime = ' + isNull(convert(varchar(50),@currentTime),'NULL')
if @totOfMaxUnit is not null
--if (@currentTime is null) or  (@currentTime < @totSecs)
	begin
	print 'Need to adjust the time'
	UPDATE A_PROCEDURES_HISTORY SET 
		DURATION = @totOfMaxUnit, 
		DURATION_TYPE = @maxUnitID
	WHERE ID  = @ID
	end
GO

