CREATE     procedure [dbo].[A_SP_PROCEDURE_GET_APPROVED_OBJECTS_BY_RELATIONSHIP] 
@PROC_OBJ_ID nvarchar(50),
@PROC_STEP_ID nvarchar(50),
@RELATIONSHIP nvarchar(50),
@strNTLogin nvarchar(50)
AS
declare @pid as nvarchar(50)
SELECT @pid = ID FROM A_PROCEDURES_HISTORY WHERE OBJECT_ID = @PROC_OBJ_ID
print '@pid = ' + isnull(@pid,'NULL')
if @pid is null and @PROC_STEP_ID is not null
	begin
		SELECT * FROM A_V_PROCEDURE_OBJECT_LINK_DATA WHERE RELATIONSHIP = @RELATIONSHIP AND STEP_ID = @PROC_STEP_ID
	end
if @RELATIONSHIP is not null
	if @PROC_STEP_ID is not null 
		begin
		SELECT * FROM A_V_PROCEDURE_OBJECT_LINK_DATA WHERE PROCEDURE_ID = @pid AND RELATIONSHIP = @RELATIONSHIP AND STEP_ID = @PROC_STEP_ID
		end
	else
		begin
		SELECT * FROM A_V_PROCEDURE_OBJECT_LINK_DATA WHERE PROCEDURE_ID = @pid AND RELATIONSHIP = @RELATIONSHIP AND STEP_ID is null
		end
else
	if @PROC_STEP_ID is not null 
		begin
		print 'SELECT * FROM A_V_PROCEDURE_OBJECT_LINK_DATA WHERE PROCEDURE_ID = ' + @pid + ' AND STEP_ID = ''' + isNULL(@PROC_STEP_ID,'NULL') + ''''
		SELECT * FROM A_V_PROCEDURE_OBJECT_LINK_DATA WHERE PROCEDURE_ID = @pid AND STEP_ID = @PROC_STEP_ID
		end
	else
		begin
		SELECT * FROM A_V_PROCEDURE_OBJECT_LINK_DATA WHERE PROCEDURE_ID = @pid AND STEP_ID is null
		end
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PROCEDURE_FIX_PRECEDING_STEPS_BASED_ON_PRINT_ORDER]    Script Date: 6/3/2019 2:06:09 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[A_SP_PROCEDURE_FIX_PRECEDING_STEPS_BASED_ON_PRINT_ORDER]
@procHistID varchar(50),
@strNTlogin varchar(50)
AS
DELETE FROM A_PROCEDURE_STEP_PRECEDING_STEPS WHERE PROCEDURE_ID = @procHistID
declare @curs as CURSOR,@curStep varchar(50),@prevStep varchar(50)
set @curs = CURSOR FOR SELECT ID 
		FROM A_PROCEDURE_STEPS 
			WHERE PROCEDURE_ID = @procHistID 
				ORDER BY PRINT_ORDER
open @curs
fetch next from @curs into @curStep
while @@fetch_status = 0
	begin
	if @prevStep is not null
		begin
		INSERT INTO A_PROCEDURE_STEP_PRECEDING_STEPS
			(ID,MY_STEP,PREV_STEP,DRCM,MODBY,PROCEDURE_ID)
		VALUES
			(newID(),
			@curStep,
			@prevStep,
			getDate(),
			@strNTLogin,
			@procHistID
			)
		end
	set @prevStep = @curStep
	fetch next from @curs into @curStep
	end
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PROCEDURE_DELETE]    Script Date: 6/3/2019 2:06:09 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO








CREATE       PROCEDURE [dbo].[A_SP_PROCEDURE_DELETE]
@strID nvarchar(50),
@strNTLogin nvarchar(50)
AS
print 'Deleting a procedure'
begin transaction
print 'Delete all the preceding step data'
DELETE FROM A_PROCEDURE_STEP_PRECEDING_STEPS WHERE PROCEDURE_ID = @strID
if @@error <> 0 goto Problem
print 'Delete all the preceding step data using in'
DELETE FROM A_PROCEDURE_STEP_PRECEDING_STEPS 
	WHERE 
		MY_STEP in (SELECT ID FROM A_PROCEDURE_STEPS WHERE PROCEDURE_ID = @strID) OR
		PREV_STEP in (SELECT ID FROM A_PROCEDURE_STEPS WHERE PROCEDURE_ID = @strID)

if @@error <> 0 goto Problem
print 'Delete all the preceding step data'
DELETE FROM A_PROCEDURE_STEP_PRECEDING_STEPS WHERE PROCEDURE_ID = @strID
if @@error <> 0 goto Problem

print 'delete the procedure object links'
DELETE FROM A_PROCEDURE_OBJECT_LINK WHERE PROCEDURE_ID = @strID
if @@error <> 0 goto Problem
print 'delete the steps'
DELETE FROM A_PROCEDURE_STEPS WHERE PROCEDURE_ID = @strID
if @@error <> 0 goto Problem
print 'make any copies of this one not followed'
UPDATE A_PROCEDURE_STEP_PRECEDING_STEPS SET OLD_PROCEDURE_ID = NULL 
WHERE OLD_PROCEDURE_ID = @strID
if @@error <> 0 goto Problem
print 'Delete any place we are referred to as copied'
UPDATE A_PROCEDURE_STEPS SET OLD_PROCEDURE_ID = NULL WHERE OLD_PROCEDURE_ID = @strID
if @@error <> 0 goto Problem
print 'DElete anything in monitors that might relate to this'
DELETE FROM A_MONITOR_TEMPLATES WHERE PROCEDURE_ID = @strID
if @@error <> 0 goto Problem
print 'Delete The Procedure Now'
DELETE FROM A_PROCEDURES_HISTORY WHERE ID = @strID
if @@error <> 0 goto Problem
print 'Finished Deleting the procedure stuff'

fin:
commit transaction
return 0

Problem:
rollback transaction
return 1
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PROCEDURE_CREATE_PLACE_HOLDER]    Script Date: 6/3/2019 2:06:10 PM ******/
