CREATE PROCEDURE [dbo].[A_SP_PART_PRODUCT_MAKE_PRICE_LIST] 
@partObjID varchar(50),
@prodObjID varchar(50),
@creatingPerson varchar(50)
AS
declare @myPrice money,@partID varchar(50)
SELECT @myPrice = PRICE,@partID = ID FROM A_PARTS_HISTORY WHERE OBJECT_ID = @partObjID
if @myPrice is null goto fin

declare @sql varchar(8000),@specList varchar(8000),@custList varchar(8000),
@custExList varchar(8000)

set @sql = 'SELECT CUST_ID FROM A_PARTS_FUTURE_CUSTOMERS WHERE PART_ID = ''' + @partID + ''''
exec A_SP_Z_UTIL_GET_COMMA_ID_LIST @sql,@custList OUTPUT
set @sql = 'SELECT CUST_ID FROM A_PARTS_FUTURE_EXCEPTIONS WHERE PART_ID = ''' + @partID + ''''
exec A_SP_Z_UTIL_GET_COMMA_ID_LIST @sql,@custExList OUTPUT
set @sql = 'SELECT SPEC_ID FROM A_PARTS_FUTURE_SPECIAL_DISTRIBUTIONS WHERE PART_ID = ''' + @partID + ''''
exec A_SP_Z_UTIL_GET_COMMA_ID_LIST @sql,@specList OUTPUT

declare @pplObjID varchar(50), @messages varchar(2000)
exec A_SP_PROD_PRICE_LIST_UPDATE
	@pplObjID  OUTPUT,
	@messages  OUTPUT,
	null, --objID
	@prodObjID,
	@custList,--@CUSTOMERS varchar(8000),
	'UNIT', --@UNIT varchar(50),
	null,--@MIN_QUANTITY varchar(50),
	null, --@UNIT_PRICE varchar(50),
	null,--@EST_UNIT_PRICE varchar(50),
	null,--@EST_LABOR_PRICE varchar(50),
	null,--@EST_PARTS_PROV_STAY varchar(50),
	null,--@EST_PARTS_PROV_TAKE_BACK varchar(50),
	null,--@EST_PARTS_CONSUMED varchar(50),
	'ESTIMATED',--@INVOICE_FROM varchar(50),
	null,--@PRODUCTION_TIME varchar(50),
	'TIME_SYS_SECONDS',--@PRODUCTION_TIME_UNIT varchar(50),
	null,--@CAPACITY varchar(50),
	'minute',--@CAPACITY_UNIT varchar(50),
	@specList,-- varchar(8000),
	@custExList,--@CUSTOMER_EXCEPTIONS varchar(8000),
	'1',--@FOR_INDIVIDUAL_SALE tinyInt,
	@creatingPerson-- varchar(50)


declare @strPrice varchar(50)
set @strPrice = convert(varchar(50),@myPrice)
exec A_SP_PROD_PRICE_LIST_QUICK_ADD_UNIT_COST 
@pplObjID,
@strPrice,
'Cost of Item',
'QTY_BASED',
'UNIT',
@creatingPerson


UPDATE A_OBJECTS 
	SET STATUS = 'APPROVED',LOCKED_BY=NULL,LOCKED_BY_NAME=NULL 
	WHERE ID = @pplObjID

exec A_SP_PROD_PRICE_LIST_FINISH_APPROVAL_WF null,@pplObjID,@creatingPerson










fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PART_MAKE_CROSS_COMPANY_PART_FOR_ACTUAL_PART]    Script Date: 6/3/2019 2:06:57 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE  PROCEDURE [dbo].[A_SP_PART_MAKE_CROSS_COMPANY_PART_FOR_ACTUAL_PART]
@actPartID varchar(50),
@fillID varchar(50),
@destCo varchar(50),
@strNTLogin varchar(50)
AS
declare @curCo varchar(50),@partID varchar(50)
declare @destCoName varchar(50)
declare @purchItemID varchar(50),@purchaser varchar(50),@phID varchar(50),@partHistID varchar(50)
declare @partIDObjectID varchar(50),@newPartID varchar(50)

SELECT @partID = PART_ID FROM A_V_ACTUAL_PARTS_APPROVED_DATA WHERE ID = @actPartID
print 'Checking to make sure a part is crossable betwix two companies.'
print 'Get the part ID'
SELECT @partHistID = HISTORY_REF_ID,@partIDObjectID = OBJECT_ID FROM A_V_PARTS_APPROVED_DATA WHERE ID = @partID
print 'get the company that this actual part part ID is registered too'
SELECT @curCo = CREATING_CO FROM A_OBJECTS WHERE ID = @partIDObjectID
if @destCo is null
	begin
	if @fillID is null goto PROBLEM
	SELECT @purchItemID = PURCH_ITEM_ID FROM A_FILLS WHERE ID = @fillID
	SELECT @phID = PURCHASE_HIST_ID FROM A_ORDER_ITEMS WHERE ID = @purchItemID
	SELECT @purchaser = PURCHASER FROM A_PURCHASES_HISTORY WHERE ID = @phID
	SELECT @destCo = ROOT_COMPANY FROM A_V_PEOPLE_APPROVED_DATA WHERE ID = @purchaser
	end

SELECT @destCoName = NAME FROM A_V_COMPANIES_APPROVED_DATA WHERE ID = @destCO
print 'The destination company = ' + @destCo + ' ' + @destCoName
print 'The part hist id = ' + @partHistID + ' '
print 'now that I have the destination company I can cross ref this part'

print 'First check to see if they already have a part related to this part'
SELECT @newPartID = LOCAL_PART_ID FROM A_V_PARTS_WITH_RELATED_EXTERNAL_CO_INFO 
	WHERE EXTERNAL_PART_ID = @partID AND LOCAL_CO = @destCo

if @newPartID is not null or @curCo = @destCo goto createPartsForSubParts


print 'There is not a part at the dest co that corresponds to this part so we need to make it'
exec A_SP_PART_COPY_FOR_EXTERNAL_COMPANY
@newPartID OUTPUT,
@partID,
@destCo,
@strNTLogin


createPartsForSubParts:
Declare @it nvarchar(50), @curs Cursor,@newSubPartID varchar(50)
set @curs = Cursor For SELECT ID FROM A_V_ACTUAL_PARTS_APPROVED_DATA WHERE PARENT_ID = @actPartID
open @curs
Fetch Next from @curs Into @it
while (@@fetch_status = 0)
Begin
	print 'Creating a cross Ref Part for = ' + @it
	exec A_SP_PART_MAKE_CROSS_COMPANY_PART_FOR_ACTUAL_PART @it,null,@destCo,@strNTLogin
	Fetch Next from @curs Into @it
End
close @curs
Deallocate @curs



fin:
return 0






PROBLEM:
print 'There was a problem'
return 1
GO

