/****** Object:  StoredProcedure [dbo].[A_SP_PART_HIERARCHY_ADD_ITEM_TO_TREE_TABLE]    Script Date: 6/3/2019 2:06:58 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO






CREATE   PROCEDURE [dbo].[A_SP_PART_HIERARCHY_ADD_ITEM_TO_TREE_TABLE]
@ID varchar(50),
@LEV integer,
@exAll smallint
AS
declare @childID varchar(50)
print 'First Checking to see if we are in the expand All List'
If @ID in (SELECT ID FROM #tempExpandAllList)
	begin
	print 'ID = ' + @ID + 'Is in the expand all list'
	set @exAll = 1
	end
print 'Insert My ID and Level into the tree table'
declare @tester as varchar(50)
SELECT TOP 1 @tester = ID FROM A_V_PARTS_GET_SUB_PART_DATA WHERE ROOT = (@ID)
print 'Checking for Child using ID = ' + @ID
if @tester is not null
	begin
	set @tester = '1'
	end
else
	set @tester = '0'
print 'Inserting my ID into temp table ' + @ID
INSERT INTO #tempAPTree(ID,LEV,HAS_CHILD,EXPANDED) VALUES(@ID,@LEV,convert(smallInt,@tester),0)
IF ((@ID in (SELECT ID FROM #tempExpandList)) or (@exAll = 1))
	begin
	UPDATE #tempAPTree SET EXPANDED = 1 WHERE ID = @ID
	print 'This one needs to be expanded so make a cursor for children and do it'
	Declare @it nvarchar(50)
	Declare @curs Cursor
	set @curs = Cursor For SELECT SUB_PART_ID FROM A_V_PARTS_GET_SUB_PART_DATA 
	WHERE ROOT = @ID ORDER BY SUB_PART_NAME
	open @curs
	Fetch Next from @curs Into @it
	set @LEV = @LEV + 1
	while (@@fetch_status = 0)
		Begin
		print 'Adding  a child ' + @it
		print 'Since this is the approved ID we need to change to the history ref id'
		SELECT @childID = PARTS_HISTORY_ID FROM A_PARTS WHERE ID = @it
		exec A_SP_PART_HIERARCHY_ADD_ITEM_TO_TREE_TABLE @childID,@LEV,@exAll
		Fetch Next from @curs Into @it
		End
	close @curs
	Deallocate @curs
	end
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PART_GET_SUB_PART_LOCATION_LIST]    Script Date: 6/3/2019 2:06:58 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[A_SP_PART_GET_SUB_PART_LOCATION_LIST]
@partID varchar(50),
@strNTLogin varchar(50)
AS
declare @pHistID varchar(50)
SELECT @pHistID = HISTORY_REF_ID FROM A_V_PARTS_APPROVED_DATA WHERE ID =@partID

create table #subPartList (PART_ID varchar(50),QTY float)
INSERT INTO #subPartList SELECT PART_ID,qTY FROM A_PARTS_SUB_PARTS WHERE PARENT = @pHistID
create table #locationList (LOC_ID varchar(50),MAX_MAKES float)

declare @curs2 cursor,@lID varchar(50),@mq float,@myMin float
declare @curs cursor,@pid varchar(50),@q float,@cnt int
set @curs = cursor for SELECT PART_ID,QTY FROM #subPartList
open @curs
fetch next from @curs  into @pID,@q
set @cnt = 0
while @@fetch_status = 0 
	begin
	if @cnt = 0
		begin
		INSERT INTO #locationList (LOC_ID,MAX_MAKES)
			SELECT LOCATION,isnull((sum(QTY)/@q),0) 
				FROM A_V_ACTUAL_PARTS_APPROVED_DATA 
				WHERE PART_ID = @pID AND AP_STATUS = 'ap_available' AND LOCATION IS NOT NULL
				GROUP BY LOCATION
		end
	else
		begin
			set @curs2 = cursor for SELECT LOC_ID,MAX_MAKES FROM #locationList
			open @curs2
			fetch next from @curs2  into @lID,@mq
			while @@fetch_status = 0
				begin 
				select @myMin = isNull((SELECT (SUM(QTY)/@q) FROM A_V_ACTUAL_PARTS_APPROVED_DATA 
					WHERE PART_ID = @pID AND LOCATION = @lID AND AP_STATUS = 'ap_available'
					GROUP BY LOCATION),0)
				print 'Found ' + isnull(convert(nvarchar(50),@myMin),'NULL') + ' items for part ID = ' + isNull(@pID,'NULL') + ' at loc = ' + isNull(@lID,'NULL')
				if @myMin > @mq
					set @myMin = @mq
				UPDATE #locationList SET MAX_MAKES = @myMin WHERE LOC_ID = @lID
				fetch next from @curs2  into @lID,@mq
				end
		end
	set @cnt = @cnt + 1
	fetch next from @curs into @pID,@q
	end	
deallocate @curs
SELECT vl.*,l.MAX_MAKES from
	#locationList l, A_V_LOCATIONS_APPROVED_DATA vl WHERE
	l.LOC_ID = vl.ID AND MAX_MAKES > 0
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PART_CREATE_SERVICE_PRODUCT]    Script Date: 6/3/2019 2:06:59 PM ******/
