CREATE      PROCEDURE [dbo].[A_SP_PART_CREATE_SERVICE_PRODUCT]
@objID as varchar(50),
@strNTLogin as varchar(50)
AS
BEGIN TRANSACTION
DECLARE @wfsID varchar(50)
SELECT @wfsID = WFS_ID FROM A_OBJECTS WHERE ID = @objID
declare @creatorID varchar(50)
SELECT @creatorID = STARTED_BY FROM A_WORKFLOWS_STARTED WHERE ID = @wfsID

print 'Creating a service product for obj = ' + @objID
declare @ID varchar(50),@PART_NAME nvarchar(200),@procName nvarchar(500),@supplierCo varchar(50)
SELECT @ID = ID,@PART_NAME = NAME,@procName = isNull(PROC_VERB + ' ','Service to ') + isNull(NAME,' Unnamed Part'),
	@supplierCo = SUPPLIER_CO
	FROM A_PARTS_HISTORY WHERE OBJECT_ID = @objID

declare @creatingCo varchar(50)
SELECT @creatingCo = ROOT_COMPANY FROM A_V_PEOPLE_APPROVED_DATA WHERE ID = @creatorID

declare @procObjID varchar(50),@procMessages nvarchar(500)
exec A_SP_PROCEDURES_UPDATE_ONE_PROCEDURE
	@procObjID OUTPUT,
	@procMessages OUTPUT,
	null,
	@creatingCo,
	null,
	@procName,
	null,
	0,
	0,
	4,
	null,
	0,
	'TIME_SYS_MINUTES',
-- Removed by Greg 02-13-2014
--	NULL,NULL,NULL,NULL,NULL,
	@creatorID

UPDATE A_OBJECTS 
	SET STATUS = 'APPROVED',LOCKED_BY=NULL,LOCKED_BY_NAME=NULL 
	WHERE ID = @procObjID
exec A_SP_PROCEDURES_FINISH_WF null,@procObjId,@creatorID

declare @creatingDept as varchar(50),
	@creatingPerson as varchar(50),
	@root as varchar(50),
	@tester as varchar(50),
	@pName as varchar(500),
	@psID as varchar(50)
print 'objID = ' + @objID
SELECT @pName = @procName,@ROOT = ROOT, @creatingPerson = CREATED_BY FROM A_OBJECTS WHERE ID = @objID
SELECT @creatingDept = COMPANY FROM A_V_PEOPLE_APPROVED_DATA WHERE ID = @creatingPerson
print 'Root ' + @ROOT
print 'Creating Dept = ' + @creatingDept
print 'creator = ' + @creatingPerson
set @psID = @procObjID


SELECT @tester = ID FROM A_PRODUCTS_HISTORY 
WHERE APP_OBJECT = @ROOT AND 
PROCEDURE_ID = @psID

if @tester is not null
	begin
	print 'This Product is already made'
	goto fin
	end

declare @newID as varchar(50)
declare @msg as nvarchar(4000)
exec A_SP_PRODUCT_UPDATE_ONE_PRODUCT
@newID OUTPUT,
@msg OUTPUT,
null,
null,
@supplierCo,
@pName,
'',
@psID,
@ROOT,
'0',
NULL,
NULL,
'1',
NULL,
NULL,
-- Edit by Greg 2/13/2014
NULL,
NULL,
NULL,
NULL,
NULL,
-- end Edit
@creatingPerson

UPDATE A_OBJECTS 
	SET STATUS = 'APPROVED',LOCKED_BY=NULL,LOCKED_BY_NAME=NULL 
	WHERE ID = @newID

exec A_SP_PRODUCTS_FINISH_WF null,@newID,@creatingPerson

exec A_SP_PART_PRODUCT_MAKE_PRICE_LIST @objID,@newID,@creatingPerson


if @@ERROR <> 0 goto problem
fin:
if @@trancount > 0 COMMIT TRANSACTION
print 'Finished A_SP_PARTS_CREATE_AUTO_PRODUCT with no errors'
return 0

PROBLEM:
if @@trancount > 0 	ROLLBACK TRANSACTION
print ' There was a problem in A_SP_PARTS_CREATE_AUTO_PRODUCT and we will terminate and not finish anything '
return 1
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PART_CREATE_A_PART_FOR_CUSTOMER_LIKE_MINE]    Script Date: 6/3/2019 2:06:59 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO





CREATE     PROCEDURE [dbo].[A_SP_PART_CREATE_A_PART_FOR_CUSTOMER_LIKE_MINE]
@partID varchar(50),
@extParentID varchar(50),
@qty float,
@custID varchar(50),
@strNTLogin varchar(50)
AS

declare @rootCustID varchar(50)
SELECT @rootCustID = ROOT_CO FROM A_V_COMPANIES_APPROVED_DATA WHERE ID = @custID
print 'First check to see if they already have a part related to this part'
declare @partDesc nvarchar(200),
	@ph varchar(50),
	@objID varchar(50),
	@creatorCo varchar(50),
	@custAdmin varchar(50),
	@newID varchar(50)

SELECT @ph = PARTS_HISTORY_ID FROM A_PARTS WHERE ID = @partID

SELECT @objID = LOCAL_PART_ID, @newID = LOCAL_PH_ID
	FROM A_V_PARTS_WITH_RELATED_EXTERNAL_CO_INFO 
	WHERE EXTERNAL_PART_ID = @partID AND LOCAL_CO = @rootCustID
if @objID is not null
	begin
	print 'This part is already referenced by this customer as ' + @objID
	goto createChildren
	end

print ''
print 'In A_SP_PART_CREATE_A_PART_FOR_CUSTOMER_LIKE_MINE'
print 'I am going to set up a part for customer = ' + isNULL(@rootCustID,'NULL')
print 'The part is going to be just like my part ' + isNull(@partID,'NULL')

if 	@creatorCo  = @rootCustID
begin
	print 'This is the same company that made the part.'
	goto fin
end

print 'We are going to creater this part like we are an admin of the customer'
SELECT @custAdmin = p.ID
	FROM A_V_ROLES_APPROVED_WITH_PEOPLE_IDS ra INNER JOIN
         A_V_PEOPLE_APPROVED_DATA p ON ra.PERSON = p.ID
	WHERE (ra.IS_ADMIN = 1) AND p.ROOT_COMPANY = @rootCustID
print 'The customer Admin is ' + isNULL(@custAdmin,'NULL')
if @custAdmin is null 
	begin
	print 'There is no Admin at this customer so I can not make the part'
	goto fin
	end

SELECT @ph = PARTS_HISTORY_ID FROM A_PARTS WHERE ID = @partID
SELECT @partDesc = '(' + c.name + ') ' + p.NAME 
	FROM A_PARTS_HISTORY p,A_V_COMPANIES_APPROVED_DATA c 
	WHERE  p.COMPANY = c.ID AND p.ID = @ph
print 'The new Part name will be ' + isNull(@partDesc,'NULL')


exec sp_GetUniqueID3 @newID OUTPUT
INSERT INTO A_PARTS_HISTORY
([ID], [UNIT], [NAME], [DRCM], [MODBY], [COMPANY], [UNIT_SHIPPING_WEIGHT], [COMPANY_PART_NUMBER], 
[SUPPLIER_SEE_INSTALL_BASE], [SUPPLIER_SEE_AVAILABILITY], [CUSTOMER_SEE_AVAILABILITY])
SELECT 
@newID, [UNIT], @partDesc, getDate(), @custAdmin, @rootCustID, [UNIT_SHIPPING_WEIGHT], [COMPANY_PART_NUMBER], 
[SUPPLIER_SEE_INSTALL_BASE], [SUPPLIER_SEE_AVAILABILITY], [CUSTOMER_SEE_AVAILABILITY] 
	FROM A_PARTS_HISTORY WHERE ID = @ph

SELECT @objID = OBJECT_ID FROM A_PARTS_HISTORY WHERE ID = @newID
print 'We inserted it and we have an object ID of ' + @objID

print 'Now we need to add the external reference to this part'
INSERT INTO 
	A_PARTS_EXTERNAL_EQUALS 
		(ID,PART_ID,EQUAL_PART_ID,DRCM,MODBY)
	VALUES 
		(newID(),@newID,@partID,getDate(),@custAdmin)

print 'Now we need to go ahead and finish the approval'
UPDATE A_OBJECTS SET LOCKED_BY=NULL,STATUS = 'APPROVED', APPROVAL_DATE = getDate() WHERE ID = @objID
exec A_SP_PARTS_FINISH_WF @newID,@objID,@custAdmin

createChildren:
declare @curs as cursor,@it varchar(50),@q float
set @curs = CURSOR FOR SELECT PART_ID,QTY FROM A_PARTS_SUB_PARTS WHERE PARENT = @PH
open @curs
fetch next from @curs into @it,@q
while @@fetch_status =0
	begin
	exec A_SP_PART_CREATE_A_PART_FOR_CUSTOMER_LIKE_MINE
		@it ,
		@objID ,
		@q,
		@custID,
		@strNTLogin



	fetch next from @curs into @it,@q
	end

if @extParentID is not null
	begin
	declare @extParentHistID varchar(50)
	SELECT @extParentHistID = PARTS_HISTORY_ID FROM A_PARTS WHERE ID = @extParentID
	IF NOT EXISTS (SELECT ID FROM A_PARTS_SUB_PARTS WHERE PARENT = @extParentHistID AND PART_ID = @objID)
		INSERT INTO A_PARTS_SUB_PARTS (ID,PARENT,PART_ID,QTY,DRCM,MODBY)
			VALUES (newID(),@extParentHistID,@objID,@qty,getDate(),@strNTLogin)
	end

fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_PART_COPY_FOR_EXTERNAL_COMPANY]    Script Date: 6/3/2019 2:07:00 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO



CREATE   procedure [dbo].[A_SP_PART_COPY_FOR_EXTERNAL_COMPANY]
@newPartID varchar(50) OUTPUT,
@partID varchar(50),
@destCo varchar(50),
@strNTLogin varchar(50)
AS
declare @partHistID varchar(50),@curCo varchar(50),@isNew tinyint
set @isNew = 1
SELECT @partHistID = PARTS_HISTORY_ID FROM A_PARTS WHERE ID = @partID
SELECT @curCo = CREATING_CO FROM A_OBJECTS WHERE OBJ_ID = @partHistID
declare @partDesc nvarchar(2000),@objID varchar(50),@creatorCo varchar(50),
	@custAdmin varchar(50),	@newID varchar(50),@curCustName varchar(50)


SELECT @newPartID = INT_PART_ID 
	FROM A_V_EXTERNAL_PARTS_WITH_COMPANY 
	WHERE EXT_PART_ID = @partID AND EXT_CO = @curCo

if @newPartID is not null
	begin
		print 'This one already exists for this company, so we dont need to create it'
		set @isNew = 0
	 	goto createChildParts

	end

print 'We are going to create this part like we are an admin of the customer'
SELECT @custAdmin = p.ID
	FROM A_V_ROLES_APPROVED_WITH_PEOPLE_IDS ra INNER JOIN
         A_V_PEOPLE_APPROVED_DATA p ON ra.PERSON = p.ID
	WHERE (ra.IS_ADMIN = 1) AND p.ROOT_COMPANY = @destCo

print 'The customer Admin is ' + isNULL(@custAdmin,'NULL')
if @custAdmin is null 
	begin
	print 'There is no Admin at this customer so I can not make the part'
	goto PROBLEM
	end

print 'The part Hist ID is ' + @partHistID
SELECT @partDesc = NAME FROM A_PARTS_HISTORY WHERE ID = @partHistID
print 'The part is ' + @partDesc
print 'The Company ID is ' + @curCo
SElECT @curCustName = NAME FROM A_V_COMPANIES_APPROVED_DATA WHERE ID = @curCo
print 'The Company is ' + @curCustName

SELECT @partDesc = '(' + @curCustName + ') ' + @partDesc

print 'The new Part name will be ' + isNull(@partDesc,'NULL')

exec sp_GetUniqueID3 @newID OUTPUT
INSERT INTO A_PARTS_HISTORY
([ID], [UNIT], [NAME],SPARE,CONSUMABLE,  [COMPANY], [UNIT_SHIPPING_WEIGHT], [COMPANY_PART_NUMBER], 
[SUPPLIER_SEE_INSTALL_BASE], [SUPPLIER_SEE_AVAILABILITY], [CUSTOMER_SEE_AVAILABILITY],[DRCM], [MODBY],WEIGHT_TYPE
)
SELECT 
@newID, [UNIT], @partDesc,SPARE,CONSUMABLE, @destCo, [UNIT_SHIPPING_WEIGHT], [COMPANY_PART_NUMBER], 
1, 1, 0, getDate(), @custAdmin, WEIGHT_TYPE
	FROM A_PARTS_HISTORY WHERE ID = @partHistID

SELECT @objID = OBJECT_ID FROM A_PARTS_HISTORY WHERE ID = @newID
set @newPartID = @objID
print 'We inserted it and we have an object ID of ' + @objID

print 'Now we need to add the external reference to this part'
INSERT INTO 
	A_PARTS_EXTERNAL_EQUALS 
		(ID,PART_ID,EQUAL_PART_ID,DRCM,MODBY)
	VALUES 
		(newID(),@newID,@partID,getDate(),@custAdmin)

createChildParts:
SELECT @newID = obj_ID FROM A_OBJECTS WHERE ID = @newPartID
print 'Now we need to make the children parts'
print 'first delete the existing children'
DELETE FROM A_PARTS_SUB_PARTS WHERE PARENT = @newID
Declare @it nvarchar(50), @curs Cursor,@newSubPartID varchar(50),@qty float,@nn varchar(50)
set @curs = Cursor For SELECT PART_ID,QTY,NICK_NAME 
 	FROM A_PARTS_SUB_PARTS WHERE PARENT = @partHistID
open @curs
Fetch Next from @curs Into @it,@qty,@nn
while (@@fetch_status = 0)
Begin
	print 'Creating a new subPart for this part = ' + @it
	exec A_SP_PART_COPY_FOR_EXTERNAL_COMPANY @newSubPartID OUTPUT,@it,@destCo,@strNTLogin
	INSERT INTO A_PARTS_SUB_PARTS (ID,PARENT,PART_ID,DRCM,MODBY,QTY,NICK_NAME)
 		VALUES (newID(),@newID,@newSubPartID,getDate(),@custAdmin,@qty,@nn)
	set @newSubPartID = null
 	Fetch Next from @curs Into @it,@qty,@nn
End
close @curs
Deallocate @curs

if @isNew = 1
	begin
	print 'Now we need to go ahead and finish the approval since we just made this part'
	UPDATE A_OBJECTS SET STATUS = 'APPROVED', APPROVAL_DATE = getDate(),LOCKED_BY = NULL WHERE ID = @objID
	exec A_SP_PARTS_FINISH_WF @newID,@objID,@custAdmin
	end

fin:
return 0
PROBLEM:
print 'There was an error'
return 1
GO

