CREATE                     PROCEDURE [dbo].[A_SP_ORDER_ITEM_UPDATE_ITEM]
@newID nvarchar(50) OUTPUT,
@messages nvarchar(2000) OUTPUT,
@objID varchar(50),
@ID varchar(50),
@PROD_OR_LIST varchar(50),
@QTY varchar(50),
@RECURRING nvarchar(50),
@SPECIAL_DISCOUNT varchar(50),
@PROD_PRICE_LIST nvarchar(50),
@SPECIAL_DIS_REASON nvarchar(4000),
@COMMENT nvarchar(4000),
@PARENT_ID varchar(50),
@PROC_SYS_ID varchar(50),
@dest varchar(50),
@FROM_LOC varchar(50),
@TO_LOC varchar(50),
@strNTLogin varchar(50)
AS
print 'In A_SP_ORDER_ITEM_UPDATE_ITEM'

print 'First lets determine the product info'
declare @PRODUCT as varchar(50)
print 'So, PROD_OR_LIST is either the price list or the product, we need to check that out'
print 'Check to see if it is the Product first'
declare @prodTester as varchar(50)
SELECT @prodTester = ID FROM A_V_PRODUCTS_APPROVED_DATA WHERE ID = @PROD_OR_LIST
if @prodTester is null
	begin
	print 'This is not the product, so it must be the list price'
	SELECT @PRODUCT = PRODUCT FROM A_V_PROD_PRICE_LIST_BY_APPROVED_ID WHERE ID = @PROD_OR_LIST
	print 'They must have picked a new list price so set the list price = ' + @PROD_OR_LIST
	SET @PROD_PRICE_LIST = @PROD_OR_LIST
	end
else
	begin
	print 'The selected Item is still a product so we need to assume they did not change anything.'
	SET @PRODUCT = @PROD_OR_LIST
	end
print 'Got the Product ID of ' + @PRODUCT
print 'Got the Product List Price ID of  ' + @PROD_PRICE_LIST

declare @firstTime varchar(10), @orderID varchar(50),@quoteID varchar(50),@strType varchar(50)

if @ID is null
	begin
	print 'This is a new one'
	set @firstTime = 'true'
	exec sp_GetUniqueID3 @ID OUTPUT
	print 'Got a new ID for this one ' + @ID
	print 'Now to figure out the quoteID or orderID'
	SELECT @quoteID = OBJ_ID FROM A_OBJECTS WHERE ID = @objID and OBJ_TABLE = 'A_QUOTES_HISTORY'
	SELECT @orderID = OBJ_ID FROM A_OBJECTS WHERE ID = @objID and OBJ_TABLE = 'A_ORDERS_HISTORY'
	if @orderID is null and @quoteID is NULL goto problem
	INSERT INTO A_ORDER_ITEMS (ID,ORDER_ID,QUOTE_ID,PRODUCT_ID,DRCM,MODBY)
	VALUES (@ID,@orderID,@quoteID,@PRODUCT,getDate(),@strNTLogin)
	end
else
	begin
	print 'This is not a new one'
	end


UPDATE A_ORDER_ITEMS
SET
PRODUCT_ID = @PRODUCT,
DRCM = getDate(),
MODBY = @strNTLogin,
QTY = @QTY,
RECURRING = @RECURRING,
SPECIAL_DISCOUNT = @SPECIAL_DISCOUNT,
SPECIAL_DISC_REASON = @SPECIAL_DIS_REASON,
COMMENTS = @COMMENT,
PROD_PRICE_LIST = @PROD_PRICE_LIST,
PROC_SYS_ID = @PROC_SYS_ID,
DEST = @DEST,
FROM_LOC = @FROM_LOC,
TO_LOC = @TO_LOC,
PARENT = @PARENT_ID
WHERE ID = @ID
set @newID = @ID
print 'If this was a shipping procedure we will need to make the precedents of the parent to follow it'
if @PROC_SYS_ID = 'SYS_SHIPPING'
	begin
		print 'Set the weight to be that of the parent'
		UPDATE A_ORDER_ITEMS
			SET EST_WEIGHT = (SELECT EST_WEIGHT FROM A_ORDER_ITEMS WHERE ID = @PARENT_ID),
				EST_WEIGHT_UNIT = (SELECT EST_WEIGHT_UNIT FROM A_ORDER_ITEMS WHERE ID = @PARENT_ID)
			WHERE ID = @ID
		if @DEST = 'to'
			begin
			print 'Update the precednce of the parent to follow this one'
			DELETE FROM A_ORDER_ITEM_PRECEDENTS WHERE FOL = @PARENT_ID AND PREV = @ID
			INSERT INTO A_ORDER_ITEM_PRECEDENTS (ID,FOL,PREV,DRCM,MODBY) VALUES(newID(),@PARENT_ID,@ID,getDate(),@strNTLogin)
		
			end
		if @DEST = 'from'
			begin
			print 'Update the precednce of the child to follow the parent'
			DELETE FROM A_ORDER_ITEM_PRECEDENTS WHERE FOL =  @ID AND PREV = @PARENT_ID
			INSERT INTO A_ORDER_ITEM_PRECEDENTS (ID,PREV,FOL,DRCM,MODBY) VALUES(newID(),@PARENT_ID,@ID,getDate(),@strNTLogin)
			end
	end

declare @myProcID varchar(50),@mySysID varchar(50)
SELECT @myProcID = PROCEDURE_ID  FROM A_V_PRODUCTS_APPROVED_DATA WHERE ID = @PRODUCT
SELECT @mySysID = SYSTEM_ID FROM A_V_PROCEDURES_APPROVED_DATA WHERE ID = @myProcID
UPDATE A_ORDER_ITEMS SET BILL_TYPE = 
	(select case
		when @mySysID in ('SYS_PROVIDE_AND_STAY','SYS_PROVIDE_AND_CONSUMED','SYS_SHIPPING') then 'ACT_EST'
		else 'ESTIMATE'
	end)
	WHERE ID = @ID


if @firstTime = 'true'
	begin
	print 'This is the first time this thing was added to this order so we need to add its children'
	exec A_SP_ORDER_ITEM_UPDATE_CHILD_ORDER_ITEMS @ID,@strNTLogin
	end
	


exec A_SP_ORDER_ITEM_SET_PRICE @ID,@strNTLogin
declare @parent as varchar(50)
SELECT @parent = PARENT FROM A_ORDER_ITEMS WHERE ID = @ID
exec A_SP_ORDER_ITEM_SET_PRICE @parent,@strNTLogin

set @newID = @ID

fin:

return 0


problem:
print 'THERE WAS A PROBLEM'
GO

/****** Object:  StoredProcedure [dbo].[A_SP_ORDER_ITEM_UPDATE_CHILD_ORDER_ITEMS]    Script Date: 6/3/2019 2:07:09 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO




CREATE           PROCEDURE [dbo].[A_SP_ORDER_ITEM_UPDATE_CHILD_ORDER_ITEMS] 
@ID varchar(50),
@strNTLogin varchar(50)
AS
declare @myOrdID as varchar(50), @pplID varchar(50),@myQuoteID varchar(50),
	@qty as real,@parentID as varchar(50),@myProd varchar(50),
	@newID varchar(50),	@CHILD varchar(50),	@CHILD_QTY varchar(50),	
	@CHILD_PRODUCT_ID varchar(50), @it nvarchar(50), 
	@exID varchar(50),@newExID varchar(50), 
	@curs Cursor, @exCurs Cursor

print 'Adding the child orders for order item = ' + @ID
SELECT @myOrdID = ORDER_ID, @myQuoteID = QUOTE_ID, @pplID = PROD_PRICE_LIST,@qty = QTY, @parentID = PARENT 
		FROM A_ORDER_ITEMS WHERE ID = @ID
SELECT @myProd = PRODUCT FROM A_V_PROD_PRICE_LIST_APPROVED_DATA WHERE ID = @pplID

print 'Data:ordID='+isNull(@myOrdID,'NULL')+',pplID='+isNull(@pplID,'NULL')+',qty='+isNull(convert(varchar(50),@qty),'NULL')+
	',parentID='+isNull(isNull(@parentID,'NULL'),'NULL')+',prod='+isNull(@myProd,'NULL')

print 'ADDING Extra Costs for this one'
set @exCurs = Cursor For SELECT ID FROM A_PROD_PRICE_LIST_EXTRA_COSTS 
				WHERE PROD_PRICE_LIST = (SELECT HISTORY_REF_ID FROM A_PROD_PRICE_LIST WHERE ID = @pplID)
open @exCurs
Fetch Next from @exCurs Into @exID
while (@@fetch_status = 0)
	Begin
	print 'Adding Extra cost = ' + @exID
	exec sp_GetUniqueID3 @newExID OUTPUT
	INSERT INTO A_ORDER_ITEMS (ID,ORDER_ID,QUOTE_ID,PARENT,PROD_PRICE_LIST,ADD_COST_ID,DRCM,MODBY,QTY,PRODUCT_ID,EX_DESC)
	SELECT @newExID,@myOrdID,@myQuoteID,@ID,@pplID,@exID,getDate(),@strNTLogin,@qty,@myProd,[DESCRIPTION]
		FROM A_PROD_PRICE_LIST_EXTRA_COSTS WHERE ID = @exID
	exec A_SP_ORDER_ITEM_SET_PRICE @newExID,@strNTLogin
	Fetch Next from @exCurs Into @exID
	End
close @exCurs
deallocate @exCurs

set @curs = Cursor For SELECT CHILD_ID,QTY,PRODUCT
	FROM A_V_PROD_PRICE_LIST_APPROVED_CHILDREN_WITH_PARENT WHERE PARENT_ID = @pplID
	AND CHILD_ID NOT IN (SELECT PROD_PRICE_LIST FROM A_ORDER_ITEMS WHERE PARENT = @ID)
open @curs
Fetch Next from @curs Into @CHILD,@CHILD_QTY,@CHILD_PRODUCT_ID
while (@@fetch_status = 0)
Begin
	exec sp_GetUniqueID3 @newID OUTPUT
	INSERT INTO A_ORDER_ITEMS (ID,ORDER_ID,QUOTE_ID,PARENT,PROD_PRICE_LIST,DRCM,MODBY,QTY,PRODUCT_ID)
	values (@newID,@myOrdID,@myQuoteID,@ID,@CHILD,getDate(),@strNTLogin,@CHILD_QTY,@CHILD_PRODUCT_ID)
	EXEC A_SP_ORDER_ITEM_UPDATE_CHILD_ORDER_ITEMS @newID,@strNTLogin
	Fetch Next from @curs Into @CHILD,@CHILD_QTY,@CHILD_PRODUCT_ID
End
close @curs
Deallocate @curs

exec A_SP_ORDER_ITEM_SET_PRICE @ID,@strNTLogin
GO

/****** Object:  StoredProcedure [dbo].[A_SP_ORDER_ITEM_SET_PRICE]    Script Date: 6/3/2019 2:07:09 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO















CREATE               procedure [dbo].[A_SP_ORDER_ITEM_SET_PRICE] 
@ID varchar(50),
@strNTLogin varchar(50)
AS
print 'Get the parent ID and Parent Qty of ID = ' + @ID
declare @parentQTY as int, @parentID as varchar(50), @myPPL as varchar(50), 
		@myExID as varchar(50),	@specDisc as real, @qty float, @wt float,
		@wtType varchar(50),@sysID varchar(50)


SELECT @parentID = p.ID, @parentQTY = isNULL(p.QTY,1),
	@myPPL = c.PROD_PRICE_LIST,@sysID = c.PROC_SYS_ID,
	@specDisc = isNull(c.SPECIAL_DISCOUNT,0),
	@myExID = c.ADD_COST_ID, @qty = isNull(p.QTY,1),
	@wt = p.EST_WEIGHT, @wtType = p.EST_WEIGHT_UNIT
	FROM  A_ORDER_ITEMS c LEFT OUTER JOIN
          A_ORDER_ITEMS p ON c.PARENT = p.ID
	WHERE c.ID = @ID

print 'Special Discount = ' + isNull(convert(varchar(50),@specDisc),'NULL')
print 'PPL = ' + isNull(convert(varchar(50),@myPPL),'NULL')
declare @tester as varchar(50)
SELECT @tester = ID FROM A_ORDER_ITEMS WHERE PARENT = @ID
declare @myPrice REAL,@nonExChildPrice money,@exChildPrice money,@totalPrice money, @unitPrice money, @flatPrice money

if @sysID = 'SYS_SHIPPING' or @myExID is not null
	UPDATE A_ORDER_ITEMS SET EST_WEIGHT = @wt,EST_WEIGHT_UNIT = @wtType,QTY = @qty WHERE ID = @ID

if @tester is not null
	begin
	SELECT @nonExChildPrice = SUM((TOTAL_PRICE)) FROM A_ORDER_ITEMS WHERE PARENT = @ID AND ADD_COST_ID is null
	SELECT @exChildPrice = SUM((TOTAL_PRICE)) FROM A_ORDER_ITEMS WHERE PARENT = @ID AND ADD_COST_ID is not null
	set @myPrice = 0
	set @totalPrice = (isNull((1-(@specDisc/100)) * @exChildPrice,0)) + (isNull(@nonExChildPrice,0))
	end
else
	begin
	print 'Getting Price from Additional cost '
	exec A_SP_PROD_PRICE_LIST_EXTRA_COST_GET_PRICE_FOR_QTY 
			@myPrice OUTPUT, @flatPrice OUTPUT, 
			@unitPrice OUTPUT, @myExID, @qty, @wt, @wtType
	print 'MyUnit Price is ' + convert(nvarchar(50),@myPrice)
	set @totalPrice = (1-(@specDisc/100)) * @myPrice
	end		
print 'My Price = ' + isNull(convert(varchar(50),@myPrice),'NULL')
print 'My Total Price = ' + isNull(convert(varchar(50),@totalPrice),'NULL')
print 'My Special Disc = ' + isNull(convert(varchar(50),@specDisc),'NULL')

if @myExID is null
	begin
	print 'This is just an order item not a real money tracker so we need to do the qty the right way'
	UPDATE A_ORDER_ITEMS SET
		UNIT_PRICE = @unitPrice,
		FLAT_RATE = @flatPrice,
		PARENT_QTY = @parentQTY, 
		TOTAL_QTY = QTY,   --isNULL(@parentQTY,1) * 
		TOTAL_PRICE = @totalPrice
	WHERE ID = @ID
	end
else
	begin
	print 'This is a real money tracker so we need to make the qty = the parents and figure price on qty'
	UPDATE A_ORDER_ITEMS SET
		UNIT_PRICE = @unitPrice,
		FLAT_RATE = @flatPrice,
		PARENT_QTY = @parentQTY, 
		TOTAL_QTY = @parentQTY,
		TOTAL_PRICE = @totalPrice
	WHERE ID = @ID
	end

	

	

declare @pRunner varchar(50),@oldP varchar(50)
SELECT @pRunner = PARENT FROM A_ORDER_ITEMS WHERE ID = @ID
while @pRunner is not null
	begin
	set @oldP = @pRunner
	set @pRunner = null
	exec A_SP_ORDER_ITEM_SET_PRICE @oldP,@strNTLogin
	SELECT @pRunner = PARENT FROM A_ORDER_ITEMS WHERE ID = @oldP
	end
GO

/****** Object:  StoredProcedure [dbo].[A_SP_ORDER_ITEM_SET_MY_PRECEDENTS]    Script Date: 6/3/2019 2:07:10 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[A_SP_ORDER_ITEM_SET_MY_PRECEDENTS]
@ID varchar(50),
@strPrecList varchar(8000),
@strNTLogin varchar(50)
AS
print 'Updating Precedents for ' + @ID
print 'First delete all the ones we used to have'
DELETE FROM A_ORDER_ITEM_PRECEDENTS WHERE FOL = @ID
print 'making a cursor to go through the ref files string'
CREATE TABLE #TempItems	(IT varchar(50))
INSERT INTO #TempItems Exec A_SP_Z_SPLIT @strPrecList,','
Declare @it nvarchar(50)
Declare @curs Cursor
set @curs = Cursor For SELECT * FROM #TempItems
open @curs
Fetch Next from @curs Into @it
while (@@fetch_status = 0)
Begin
	print 'Adding Precedent = ' + @it
	INSERT INTO A_ORDER_ITEM_PRECEDENTS (ID,PREV,FOL,DRCM,MODBY)
		VALUES(newID(),@it,@ID,getDate(),@strNTLogin)
	Fetch Next from @curs Into @it
End
close @curs
Deallocate @curs
GO

