		if @@ERROR <> 0 goto problem
	end 
if @myTable = 'A_REGIONS_HISTORY'
	begin
		print 'finishing the wf for A_REGIONS' + @myID
		exec A_SP_REGIONS_FINISH_WF @myID,@objID,@strNTLogin
		if @@ERROR <> 0 goto problem
	end 
if @myTable = 'A_COMPANIES_HISTORY'
	begin
