CREATE                    procedure [dbo].[A_SP_OBJECT_ADD]
	@OBJ_TABLE as nvarchar(50),
	@OBJ_ID as nvarchar(50),
	@OBJ_DESC as nvarchar(2000),
	@strNTLogin as nvarchar(50),
	@COMPANY_PART_NUMBER as nvarchar(50),
	@PT_NAME as nvarchar(50),
	@CO_NAME as nvarchar(50)
as
print 'Adding a new object'
declare @tester as nvarchar(50)
declare @sql as nvarchar(800)
declare @myCOName as nvarchar(200)
SELECT @tester = ID FROM A_OBJECTS WHERE OBJ_ID = @OBJ_ID AND OBJ_TABLE = @OBJ_TABLE
print 'Checking to see if this item is already in the object table '
print 'Tester = ' + isnull(@tester,'NULL')
if @tester is null
	begin
		print 'tester was null so we need to make this one.'
		declare @newID as nvarchar(50)
		exec sp_GetUniqueID3 @newID OUTPUT
		if @OBJ_ID is null
			begin 
			print 'The object is null table = '
			print @OBJ_TABLE
			print 'ERROR so we are not going to insert anything now'
			end
		else
			begin
				declare @myCo as nvarchar(50)
				SELECT @myCO = CO,@myCoName = COMPANY_NAME FROM A_V_PEOPLE_WITH_COMPANIES WHERE PERSON = @strNTLogin
				if @myCO is null
					begin 
					print 'The Company is null -- ID  = '
					print @strNTLogin
					end		
				declare @ApprovalAct as nvarchar(50)
				exec A_SP_GET_APPROVAL_ACTIVITY_BY_TABLE_AND_ID @ApprovalAct OUTPUT,@OBJ_TABLE,@OBJ_ID

				print 'Inserting the object ' + @newID
				INSERT INTO A_OBJECTS (ID,ROOT,REV,CREATING_CO,OBJ_TABLE,
								OBJ_ID,OBJ_DESC,CO_PART_NUM,PART_TYPE,PART_CO,DRCM,
								MODBY,CREATE_DATE,CREATED_BY,APPROVAL_ACTIVITY,CREATING_CO_NAME) 
				VALUES (@newID,@newID,1,@myCo,@OBJ_TABLE,@OBJ_ID,@OBJ_DESC,
								@COMPANY_PART_NUMBER,@PT_NAME,@CO_NAME,getDate(),@strNTLogin,
								getDate(),@strNTLogin,@ApprovalAct,@myCoName)
		end
	end
else
	begin
		print 'This object already exists so no need to make it'
	end
GO

/****** Object:  StoredProcedure [dbo].[A_SP_NOUN_HIERARCHY_FINISH_WF]    Script Date: 6/3/2019 2:07:24 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO










CREATE       PROCEDURE [dbo].[A_SP_NOUN_HIERARCHY_FINISH_WF]
	@myID nvarchar(50),
	@objID nvarchar(50),
	@strNTLogin nvarchar(50)
as
print 'Finishing the wf for a Noun Hierarchy'
declare @myRoot as nvarchar(50) --get the root which is the ID of A_VERBS
declare @ID as nvarchar(50) --get my ID  in the A_NOUN_HIERARCHIES_HISTORY table
SELECT @myRoot = ROOT,@ID = OBJ_ID FROM A_OBJECTS WHERE ID = @objID
declare @tester as nvarchar(50) --Test to see if it is in the table
SELECT @tester = ID FROM A_NOUN_HIERARCHIES WHERE ID = @myRoot 
if @tester is Null --it is not in there so add it
	begin
		print 'tester was null so i need to go ahead and make a record'
		INSERT INTO A_NOUN_HIERARCHIES(ID,HISTORY_REF_ID,DRCM,MODBY) VALUES (@myRoot,@ID,getDate(),@strNTLogin)
	end
--so now make sure that the value in A_NOUN_HIERARCHIES is Approved
declare @curID as nvarchar(50)
SELECT @curID = OBJ_ID FROM A_OBJECTS WHERE ROOT = @myROOT AND STATUS IN
('APPROVED','APPROVED_BUT_REVISING','APPROVED_BUT_DELETING')
exec A_SP_UPDATE_TABLE_FIELD @curID,@myRoot,'A_NOUN_HIERARCHIES','HISTORY_REF_ID'
--Now we need to delete and copy all the children information

--Delete the old Hierarchy in A_NOUN_HIERARCHY_CHILDREN
DELETE FROM A_NOUN_HIERARCHY_CHILDREN WHERE HIERARCHY_ID = @myROOT
--Now put the current Approved Hierarchies Children in here.
INSERT INTO A_NOUN_HIERARCHY_CHILDREN
(ID,ROOT_ID,APPROVED_OBJ_ID,PARENT_ID,HIERARCHY_ID,DRCM,MODBY,HIDDEN)
SELECT ID,ROOT_ID,APPROVED_OBJ_ID,PARENT_ID,@myROOT as HIERARCHY_ID,
DRCM,MODBY,HIDDEN FROM A_NOUN_HIERARCHY_CHILDREN_EDITING WHERE HIERARCHY_ID = @curID
--Now make those things in editing children been Approved
UPDATE A_NOUN_HIERARCHY_CHILDREN_EDITING SET BEEN_APPROVED = 'TRUE' WHERE HIERARCHY_ID = @curID
GO

