/****** Object:  StoredProcedure [dbo].[A_SP_MONITORS_CHECK_TASK_FOR_NEW_TEXT_MONITOR_RESULTS]    Script Date: 6/3/2019 2:07:36 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO






CREATE      PROCEDURE [dbo].[A_SP_MONITORS_CHECK_TASK_FOR_NEW_TEXT_MONITOR_RESULTS]
@retVal varchar(50) OUTPUT,
@retMSG varchar(50) OUTPUT,
@TASK_ID varchar(50),
@strNTLogin varchar(50)
AS
if dbo.md() = 1 
	begin
	print 'Checking the monitors on Task = ' + @TASK_ID + ' for new text'
	SELECT * FROM A_MONITOR_TEMPLATES wHERE TASK_ID = @TASK_ID
	end

if not exists(SELECT * FROM A_MONITOR_TEMPLATES WHERE TASK_ID = @TASK_ID AND MONITOR_TYPE = 'TEXT' AND USE_RESULT = 1 AND MY_ANSWER <> '' AND MY_ANSWER is not null)
	begin
	if dbo.md() = 1 print 'There are no text monitors on this call'
	goto fin
	end

if dbo.md() = 1 print 'We have a text monitor here time to check them all'
Declare @it nvarchar(50),@rollUpID varchar(50),@myTXT varchar(200)
Declare @curs Cursor
set @curs = Cursor For SELECT ID,ROLL_UP_ID,MY_ANSWER FROM A_MONITOR_TEMPLATES WHERE TASK_ID = @TASK_ID AND MONITOR_TYPE = 'TEXT'
open @curs
Fetch Next from @curs Into @it,@rollUpID,@myTXT
while (@@fetch_status = 0)
Begin
	if dbo.md() = 1 print 'Looking at monitor = ' + @it
	if not exists(SELECT * FROM A_MONITOR_TEMPLATES WHERE ROLL_UP_ID = @rollUpID and MY_ANSWER = @myTXT and ID <> @it)
		set @retVal = 'NEW_TEXT'
	
	Fetch Next from @curs Into @it,@rollUpID,@myTXT
End
close @curs
Deallocate @curs


	




fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_MONITOR_UPDATE_THESAURUS_ENTRY]    Script Date: 6/3/2019 2:07:37 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO





CREATE PROCEDURE [dbo].[A_SP_MONITOR_UPDATE_THESAURUS_ENTRY]
@retVal varchar(50) OUTPUT,
@retMSG varchar(50) OUTPUT,
@rollUpID varchar(50),
@myText varchar(2000),
@description varchar(5000),
@syns varchar(5000),
@isFirst varchar(10),
@strNTLogin varchar(50)
AS
if @isFirst is not null 
	DELETE FROM A_MONITOR_TEXT_THESAURUS 
	WHERE MON_ROLL_UP_ID = @rollUpID
		AND  MAIN_TEXT = @myText
		AND SIMILAR_TEXT <> @myText

declare @myRoot varchar(50)
SELECT @myRoot = ID 
	FROM A_MONITOR_TEXT_THESAURUS 
	WHERE MON_ROLL_UP_ID = @rollUpID AND MAIN_TEXT = @myText AND SIMILAR_TEXT = @myText


declare @simList varchar(8000),@sql varchar(2000),@bigList varchar(8000)

set @bigList = @myRoot + ',' + @syns

CREATE TABLE #TempItems	(IT varchar(50))
INSERT INTO #TempItems Exec A_SP_Z_SPLIT @syns,','

declare @simText varchar(50),@simDesc varchar(2000)
Declare @it nvarchar(50)
Declare @curs Cursor
set @curs = Cursor For SELECT * FROM #TempItems
open @curs
Fetch Next from @curs Into @it
while (@@fetch_status = 0)
Begin
	SELECT @simText = MAIN_TEXT,@simDesc = DESCRIPTION FROM A_MONITOR_TEXT_THESAURUS WHERE ID = @it

	

	IF (NOT (EXISTS 
			(
			SELECT * FROM A_MONITOR_TEXT_THESAURUS 
			WHERE 
				MON_ROLL_UP_ID = @rollUpID AND 
				MAIN_TEXT = @myText AND 
				SIMILAR_TEXT = @simText
			)))
		begin

			print 'Main Text = ' + @myText
			print 'Sim Text = ' + @simText


			INSERT INTO A_MONITOR_TEXT_THESAURUS (ID,MON_ROLL_UP_ID,MAIN_TEXT,SIMILAR_TEXT)
			VALUES (newID(),@rollUpID,@myText,@simText)
			print '		exec A_SP_MONITOR_UPDATE_THESAURUS_ENTRY null,null,' +
			'''' + isNull(@rollUpID,'null') + ''',' +
			'''' + isNull(@simText,'null') + ''',' + 
			'''' + isNull(@simDesc,'null') + ''',' + 
			'''' + isNull(@myRoot,'null') + ''',' + 
			'''' + isNull(@strNTLogin,'null') + ''''
			
			

			set @sql = 'SELECT ID FROM A_MONITOR_TEXT_THESAURUS m WHERE m.MON_ROLL_UP_ID = ''' + @rollUpID + ''' 
			AND m.MAIN_TEXT = m.SIMILAR_TEXT AND
			m.MAIN_TEXT IN (SELECT SIMILAR_TEXT FROM A_MONITOR_TEXT_THESAURUS WHERE MON_ROLL_UP_ID = ''' + @rollUpID + '''
			AND MAIN_TEXT = ''' + @simText + ''')'
			print @sql
			exec A_SP_Z_UTIL_GET_COMMA_ID_LIST @sql,@simList OUTPUT
			print @simList
			exec A_SP_MONITOR_UPDATE_THESAURUS_ENTRY
				@retVal OUTPUT,@retMSG OUTPUT,@rollUpID,@myText,@Description,@simList,null,@strNTLogin
			exec A_SP_MONITOR_UPDATE_THESAURUS_ENTRY
				@retVal OUTPUT,@retMSG OUTPUT,@rollUpID,@simText,@simDesc,@bigList,null,@strNTLogin




		end
Fetch Next from @curs Into @it


End
close @curs
Deallocate @curs








UPDATE A_MONITOR_TEXT_THESAURUS SET DESCRIPTION = @description WHERE 
	MAIN_TEXT = @myText AND SIMILAR_TEXT = @myText


fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_MONITOR_UPDATE_RESULT_AND_COMMENT]    Script Date: 6/3/2019 2:07:37 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE      PROCEDURE [dbo].[A_SP_MONITOR_UPDATE_RESULT_AND_COMMENT]
@newID nvarchar(50) OUTPUT,
@messages nvarchar(2000) OUTPUT,
@ID nvarchar(50),
@FAIL_ACTION varchar(50),
@RESULT  varchar(50),
@COMMENT varchar(1000),
@TARGET varchar(50),
@TOLERANCE varchar(50),
@THESAURUS_ID varchar(50),
@strNTLogin varchar(50)
AS
declare @PR as nvarchar(50)
print 'Updating a Monitor Result'
DELETE FROM A_MONITOR_RESULTS WHERE MONITOR_TEMPLATE_ID = @ID
declare @myType as varchar(50),@rollUpID varchar(50)
SELECT @myType = MONITOR_TYPE,@rollUpID = ROLL_UP_ID FROM A_MONITOR_TEMPLATES WHERE ID = @ID
print @myType
UPDATE A_MONITOR_TEMPLATES SET FAIL_ACTION = @FAIL_ACTION WHERE ID = @ID
--Custom Created type Equipment start
if @myType = 'EQUIPMENT'
	begin
		UPDATE A_MONITOR_TEMPLATES 
			SET 
			TARGET = convert(float,@TARGET),
			TOLERANCE = convert(float,@TOLERANCE),
			HIGHEST_THRESHOLD = (convert(float,@TARGET) + (convert(float,@TARGET) * (convert(float,@TOLERANCE)/100))),
			LOWEST_THRESHOLD = (convert(float,@TARGET) - (convert(float,@TARGET) * (convert(float,@TOLERANCE)/100)))
			WHERE ID = @ID
		INSERT INTO A_MONITOR_RESULTS 
			(ID,MONITOR_TEMPLATE_ID,NUM_VAL,PRINT_RESULT,DRCM,MODBY,COMMENT)
		VALUES (newID(),@ID,@RESULT,@RESULT,getDate(),@strNTLogin,@COMMENT)
		goto fin
	end
	--Custom Created type Equipment end

if @myType = 'USER_NUMBER'
	begin
		UPDATE A_MONITOR_TEMPLATES SET TARGET = convert(float,@TARGET),
			TOLERANCE = convert(float,@TOLERANCE),
			HIGHEST_THRESHOLD = (convert(float,@TARGET) + (convert(float,@TARGET) * (convert(float,@TOLERANCE)/100))),
			LOWEST_THRESHOLD = (convert(float,@TARGET) - (convert(float,@TARGET) * (convert(float,@TOLERANCE)/100)))
			WHERE ID = @ID
		INSERT INTO A_MONITOR_RESULTS 
			(ID,MONITOR_TEMPLATE_ID,NUM_VAL,PRINT_RESULT,DRCM,MODBY,COMMENT)
		VALUES (newID(),@ID,@RESULT,@RESULT,getDate(),@strNTLogin,@COMMENT)
		goto fin
	end

if @myType = 'NUMBER'
	begin
		INSERT INTO A_MONITOR_RESULTS (ID,MONITOR_TEMPLATE_ID,NUM_VAL,PRINT_RESULT,DRCM,MODBY,COMMENT)
		VALUES (newID(),@ID,@RESULT,@RESULT,getDate(),@strNTLogin,@COMMENT)
		goto fin
	end
if @myType = 'MULTIPLE'
	begin
		print 'Multiple'
		SELECT @PR = TXT FROM A_MONITOR_TEMPLATES_MULT_CHOICE WHERE ID = @RESULT
		INSERT INTO A_MONITOR_RESULTS (ID,MONITOR_TEMPLATE_ID,MULT_CHOICE_ANSWER,PRINT_RESULT,DRCM,MODBY,COMMENT)
		VALUES (newID(),@ID,@RESULT,@PR,getDate(),@strNTLogin,@COMMENT)
		goto fin
	end
if @myType = 'TEXT'
	begin
		INSERT INTO A_MONITOR_RESULTS (ID,MONITOR_TEMPLATE_ID,TEXT_VAL,PRINT_RESULT,DRCM,MODBY,COMMENT)
		VALUES (newID(),@ID,isNull(@RESULT,''),isNull(@PR,''),getDate(),@strNTLogin,@COMMENT)
		if @RESULT is not null
			begin
			if not(exists (SELECT * FROM A_MONITOR_TEXT_THESAURUS WHERE MON_ROLL_UP_ID = @rollUpID AND SIMILAR_TEXT = @RESULT))
				begin
				if @THESAURUS_ID is not null
					begin
					declare @myMainText varchar(1000)
					SELECT @myMainText = MAIN_TEXT FROM A_MONITOR_TEXT_THESAURUS WHERE ID = @THESAURUS_ID
					INSERT INTO A_MONITOR_TEXT_THESAURUS (ID,MON_ROLL_UP_ID,MAIN_TEXT,SIMILAR_TEXT)
						VALUES (newID(),@rollUpID,@myMainText,@RESULT)
					end
				else
					begin
					INSERT INTO A_MONITOR_TEXT_THESAURUS (ID,MON_ROLL_UP_ID,MAIN_TEXT,SIMILAR_TEXT)
						VALUES (newID(),@rollUpID,@RESULT,@RESULT)

					end
				end

			end		

		goto fin
	end
if @myType = 'OBJECT'
	begin
		print 'Object'
		SELECT @PR = OBJ_DESC FROM A_V_APPROVED_OBJECTS WHERE ID = @RESULT
		INSERT INTO A_MONITOR_RESULTS (ID,MONITOR_TEMPLATE_ID,TEXT_VAL,PRINT_RESULT,DRCM,MODBY,COMMENT)
		VALUES (newID(),@ID,@RESULT,@PR,getDate(),@strNTLogin,@COMMENT)
		goto fin
	end


INSERT INTO A_MONITOR_RESULTS (ID,MONITOR_TEMPLATE_ID,TEXT_VAL,PRINT_RESULT,DRCM,MODBY,COMMENT)
VALUES (newID(),@ID,@RESULT,@RESULT,getDate(),@strNTLogin,@COMMENT)

fin:











GO

