CREATE                   PROCEDURE [dbo].[A_SP_MESSAGES_BRANCH_GET_BRANCH_DATA]
@messageID varchar(50),
@strNTLogin nvarchar(50)
AS
print 'processing id of ' +isNull(@messageID, 'Null')
declare @hasRefFile as varchar(50)
declare @hasProcedure as varchar(50)
declare @hasBusinessPurpose as varchar(50)
declare @hasObject as varchar(50)
declare @hasProject as varchar(50)
declare @parentID varchar(50)



CREATE TABLE #tempToRootList(
							ID varchar(50),
							HAS_REF_FILE varchar(50),
							HAS_PROCEDURE varchar(50),
							HAS_BUSINESS_PURPOSE varchar(50),
							HAS_OBJECT varchar(50),
							HAS_PROJECT varchar(50)
							)

WHILE @messageID is not null 
	begin	
	set @hasRefFile = null
	set @hasProcedure = null
	set @hasBusinessPurpose = null
	set @hasObject = null
	set @hasProject = null

	SELECT @hasRefFile = ID from A_MESSAGES_ATTACHMENTS WHERE MESSAGE_ID = @messageID
	print 'Checking to see it my first one has a procedure for MESSAGE_ID of ' + isNull(@messageID,'NULL')
	SELECT @hasProcedure = ID from A_MESSAGES_PROCEDURE_LINK WHERE MESSAGE_ID = @messageID
	SELECT @hasBusinessPurpose = ID from A_BUSINESS_PURPOSES_ITEM_LINK WHERE ITEM_ID = @messageID AND ITEM_TYPE = 'A_MESSAGES'
	SELECT @hasObject = ID from A_OBJECT_ITEM_LINK WHERE ITEM_ID = @messageID AND ITEM_TYPE = 'A_MESSAGES'
	
	if @hasRefFile is not null
		begin
		print 'I have a reference file so setting @hasRefFile to 1 for MESSAGE ID OF ' + isNull(@messageID,'NULL') 
		set @hasRefFile = '1'
		end 
	else
		begin
		print 'I do not have a reference file so setting @hasRefFile to 0 for MESSAGE ID of'  + isNull(@messageID,'NULL')
		set @hasRefFile = '0'
		end 
	if @hasProcedure is not null
		begin
		print 'I have a reference file so setting @hasProcedure to 1 for MESSAGE ID of' + isNull(@messageID,'NULL')
		set @hasProcedure = '1'
		end 
	else
		begin
		print 'I do not have a procedure so setting @hasProcedure to 0 for MESSAGE ID of' + isNull(@messageID,'NULL')
		set @hasProcedure = '0'
		end 
	if @hasBusinessPurpose is not null
		begin
		print 'I have a business purpose so setting @hasBusinessPurpose to 1 for MESSAGE ID of' + isNull(@messageID,'NULL')
		set @hasBusinessPurpose = '1'
		end 
	else
		begin
		print 'I do not have a business purpose so setting @hasBusinessPurpose to 0 for MESSAGE ID of' + isNull(@messageID,'NULL')
		set @hasBusinessPurpose = '0'
		end 
	if @hasObject is not null
		begin
		print 'I have a object so setting @hasObject to 1 for MESSAGE ID of' + isNull(@messageID,'NULL')
		set @hasObject = '1'
		end 
	else
		begin
		print 'I do not have a object so setting @hasObject to 0 for MESSAGE ID of' + isNull(@messageID,'NULL')
		set @hasObject = '0'
		end 
	if @hasProject is not null
		begin
		print 'Need to add @hasProject code. '
		print 'I have a project FOR MY FIRST ID so setting @hasProject to 1 for MESSAGE ID of' + isNull(@messageID,'NULL')
		set @hasProject = '1'
		end 
	else
		begin
		print 'Need to add @hasProject code. '
		print 'I do not have a proejct FOR MY FIRST ID so setting @hasProject to 0 for MESSAGE ID of' + isNull(@messageID,'NULL')
		set @hasProject = '0'
		end 
	set @parentID = null
 	SELECT @parentID = PARENT_ID
		FROM A_MESSAGES 
	WHERE ID = @messageID
	INSERT INTO #tempToRootList (ID,HAS_REF_FILE,HAS_PROCEDURE,HAS_BUSINESS_PURPOSE,HAS_OBJECT,HAS_PROJECT) VALUES (@messageID,@hasRefFile,@hasProcedure,@hasBusinessPurpose,@hasObject,@hasProject)
	set @messageID = @parentID
	end


SELECT DISTINCT R.ID ,
				R.HAS_REF_FILE AS HAS_REF_FILE,
				R.HAS_PROCEDURE AS HAS_PROCEDURE,
				R.HAS_BUSINESS_PURPOSE AS HAS_BUSINESS_PURPOSE,
				R.HAS_OBJECT AS HAS_OBJECT,
				R.HAS_PROJECT AS HAS_PROJECT,
				V.DATE_SENT AS DATE_SENT,
				V.SENDER_NAME AS SENDER_NAME,
				V.MESSAGE AS MESSAGE,	
				V.IMPORTANCE AS IMPORTANCE,
				V.HIDE_MESSAGE AS HIDE_MESSAGE
FROM #tempToRootList R, A_V_MESSAGES_SEARCH_DATA V
WHERE R.ID = V.ID
GO

/****** Object:  StoredProcedure [dbo].[A_SP_MESSAGES_BRANCH_ADD_TO_BRANCH_TABLE]    Script Date: 6/3/2019 2:07:49 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO




CREATE        PROCEDURE [dbo].[A_SP_MESSAGES_BRANCH_ADD_TO_BRANCH_TABLE]
@ID varchar(50)
AS
declare @tester as varchar(50)
declare @hasRefFile as varchar(50)
declare @hasProcedure as varchar(50)
declare @hasBusinessPurpose as varchar(50)
declare @hasObject as varchar(50)
declare @hasProject as varchar(50)
set @tester = null
set @hasRefFile = null
set @hasProcedure = null

SELECT TOP 1 @tester = ID FROM A_MESSAGES WHERE PARENT_ID = (@ID)
print 'Checking for Child using ID = ' + @ID
if @tester is not null
	begin
	print 'Checking to see it my first one has a reference file for MESSAGE_ID of' + isNull(@ID,'NULL')
		set @tester = '1'
	end
else
	begin
	print 'setting @tester, @hasRefFile, @hasProcedure to 0'
	set @tester = '0'
	end

SELECT @hasRefFile = ID from A_MESSAGES_ATTACHMENTS WHERE MESSAGE_ID = @ID
print 'Checking to see it my first one has a procedure for MESSAGE_ID of ' + isNull(@ID,'NULL')
SELECT @hasProcedure = ID from A_MESSAGES_PROCEDURE_LINK WHERE MESSAGE_ID = @ID
SELECT @hasBusinessPurpose = ID from A_BUSINESS_PURPOSES_ITEM_LINK WHERE ITEM_ID = @ID AND ITEM_TYPE = 'A_MESSAGES'
SELECT @hasObject = ID from A_OBJECT_ITEM_LINK WHERE ITEM_ID = @ID AND ITEM_TYPE = 'A_MESSAGES'


if @hasRefFile is not null
	begin
	print 'I have a reference file so setting @hasRefFile to 1 for MESSAGE ID OF ' + isNull(@ID,'NULL') 
	set @hasRefFile = '1'
	end 
else
	begin
	print 'I do not have a reference file so setting @hasRefFile to 0 for MESSAGE ID of'  + isNull(@ID,'NULL')
	set @hasRefFile = '0'
	end 
if @hasProcedure is not null
	begin
	print 'I have a reference file so setting @hasProcedure to 1 for MESSAGE ID of' + isNull(@ID,'NULL')
	set @hasProcedure = '1'
	end 
else
	begin
	print 'I do not have a procedure so setting @hasProcedure to 0 for MESSAGE ID of' + isNull(@ID,'NULL')
	set @hasProcedure = '0'
	end 
if @hasBusinessPurpose is not null
	begin
	print 'I have a business purpose so setting @hasBusinessPurpose to 1 for MESSAGE ID of' + isNull(@ID,'NULL')
	set @hasBusinessPurpose = '1'
	end 
else
	begin
	print 'I do not have a business purpose so setting @hasBusinessPurpose to 0 for MESSAGE ID of' + isNull(@ID,'NULL')
	set @hasBusinessPurpose = '0'
	end 
if @hasObject is not null
	begin
	print 'I have a object so setting @hasObject to 1 for MESSAGE ID of' + isNull(@ID,'NULL')
	set @hasObject = '1'
	end 
else
	begin
	print 'I do not have a object so setting @hasObject to 0 for MESSAGE ID of' + isNull(@ID,'NULL')
	set @hasObject = '0'
	end 

print 'Inserting into #tempMessagesTree'
if @ID IN (SELECT ID FROM #tempCanSeeList)
begin
	INSERT INTO #tempMessagesTree(ID,HAS_REF_FILE,HAS_PROCEDURE,HAS_BUSINESS_PURPOSE,HAS_OBJECT,HAS_PROJECT) VALUES(@ID,@hasRefFile,@hasProcedure,@hasBusinessPurpose,@hasObject,@hasProject)
		Declare @it nvarchar(50)
		Declare @curs Cursor
		set @curs = Cursor For SELECT ID FROM A_MESSAGES WHERE PARENT_ID = @ID 
		open @curs
		Fetch Next from @curs Into @it
		while (@@fetch_status = 0)
			Begin
			print 'Adding  a child ' + @it
			exec A_SP_MESSAGES_BRANCH_ADD_TO_BRANCH_TABLE @it
			Fetch Next from @curs Into @it
			End
		close @curs
		Deallocate @curs
end
print 'done'
GO

/****** Object:  StoredProcedure [dbo].[A_SP_MESSAGES_ADD_TO_TREE_TABLE]    Script Date: 6/3/2019 2:07:49 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO




CREATE        PROCEDURE [dbo].[A_SP_MESSAGES_ADD_TO_TREE_TABLE]
@ID varchar(50),
@LEV integer,
@exAll smallint,
@strNTLogin varchar(50)
AS

print 'First Checking to see if we are in the expand All List'
If @ID in (SELECT ID FROM #tempExpandAllList)
	begin
	print 'ID = ' + @ID + 'Is in the expand all list'
	set @exAll = 1
	end
print 'Insert My ID and Level into the tree table'
declare @tester as varchar(50)
SELECT TOP 1 @tester = ID FROM A_MESSAGES WHERE PARENT_ID = (@ID) and ID IN (SELECT ID FROM #tempCanSeeList)
print 'Checking for Child using ID = ' + @ID
if @tester is not null
	begin
	set @tester = '1'
	end
else
	set @tester = '0'

if @ID IN (SELECT ID FROM #tempCanSeeList)
	BEGIN
	INSERT INTO #tempMessagesTree(ID,LEV,HAS_CHILD,EXPANDED) VALUES(@ID,@LEV,convert(smallInt,@tester),0)
	IF ((@ID in (SELECT ID FROM #tempExpandList)) or (@exAll = 1))
		begin
		UPDATE #tempMessagesTree SET EXPANDED = 1 WHERE ID = @ID
		print 'This one needs to be expanded so make a cursor for children and do it'
		Declare @it nvarchar(50)
		Declare @curs Cursor
		set @curs = Cursor For SELECT ID FROM A_MESSAGES WHERE PARENT_ID = @ID 
		open @curs
		Fetch Next from @curs Into @it
		set @LEV = @LEV + 1
		while (@@fetch_status = 0)
			Begin
			print 'Adding  a child ' + @it
			exec A_SP_MESSAGES_ADD_TO_TREE_TABLE @it,@LEV,@exAll,@strNTLogin
			Fetch Next from @curs Into @it
			End
		close @curs
		Deallocate @curs
		end
	END
print 'done'
GO

/****** Object:  StoredProcedure [dbo].[A_SP_MESSAGES_ADD_TO_MESSAGES_CAN_SEE_TABLE]    Script Date: 6/3/2019 2:07:50 PM ******/
