CREATE        PROCEDURE [dbo].[A_SP_LOCATIONS_UPDATE_ONE_LOCATION]
	@newObjID varchar(50) OUTPUT,
	@messages varchar(500) OUTPUT,
	@objID varchar(50),
	@NAME nvarchar(1000),
	@PARENT varchar(50),
	@ADDRESS_1 varchar(300),
	@ADDRESS_2 varchar(300),
	@CITY varchar(150),
	@STATE varchar(50),
	@COUNTRY varchar(50),
	@POSTAL_CODE varchar(50),
	@REGION varchar(50),
	@INTERNAL_ADDRESS varchar(300),
	@strNTLogin varchar(50)
as
declare @myID as nvarchar(50)
declare @regionName as nvarchar(1000)

SELECT @regionName = NAME FROM A_APPROVED_REGIONS
WHERE OBJECT_ID = @REGION


if @PARENT is not null
begin
	declare @parentLocationName varchar (50)
	SELECT @parentLocationName = NAME
		FROM A_LOCATIONS_HISTORY
	WHERE @PARENT = OBJECT_ID
end



if @objID is null
	begin
		print 'This is a new location so inserting it now'
		exec sp_GetUniqueID3 @myID OUTPUT
		INSERT INTO A_LOCATIONS_HISTORY (ID,NAME,PARENT_LOCATION,PARENT_LOCATION_NAME, ADDRESS_1,ADDRESS_2,CITY,STATE,COUNTRY,
		POSTAL_CODE,REGION,REGION_NAME,INTERNAL_ADDRESS,DRCM,MODBY)
		VALUES (@myID,@NAME,@PARENT,@parentLocationName,@ADDRESS_1,@ADDRESS_2,@CITY,@STATE,
		@COUNTRY,@POSTAL_CODE,@REGION,@regionName,@INTERNAL_ADDRESS,getDate(),@strNTLogin)
		SELECT @newObjID = OBJECT_ID FROM A_LOCATIONS_HISTORY WHERE ID = @myID 
	end
else
	begin
		print 'This is an update to the existing location ' + @myID
		UPDATE A_LOCATIONS_HISTORY set NAME = @NAME,PARENT_LOCATION = @PARENT,PARENT_LOCATION_NAME = @parentLocationName, ADDRESS_1 = @ADDRESS_1,
		ADDRESS_2 = @ADDRESS_2,CITY = @CITY,STATE = @STATE,COUNTRY = @COUNTRY,POSTAL_CODE = @POSTAL_CODE,
		REGION = @REGION,REGION_NAME= @regionName,INTERNAL_ADDRESS = @INTERNAL_ADDRESS,DRCM = getDate(),MODBY = @strNTLogin
		WHERE OBJECT_ID = @objID
		set @newObjID = @objID
	end
GO

/****** Object:  StoredProcedure [dbo].[A_SP_LOCATIONS_UPDATE_ALL_DATA_FOR_ONE]    Script Date: 6/3/2019 2:08:08 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO











CREATE        PROCEDURE [dbo].[A_SP_LOCATIONS_UPDATE_ALL_DATA_FOR_ONE]
@ID as NVARCHAR(50)
AS
declare @myFullAddress as nvarchar(200)
declare @myParentPAth as nvarchar(200)
declare @parentName as nvarchar(100)
declare @regionName as nvarchar(100)

exec A_SP_LOCATIONS_GET_FULL_ADDRESS @myFullAddress OUTPUT,@ID
exec A_SP_LOCATIONS_GET_PARENT_PATH @myParentPath OUTPUT,@ID
select @parentName = NAME FROM A_APPROVED_LOCATIONS WHERE ID IN (SELECT PARENT_LOCATION FROM A_LOCATIONS_HISTORY WHERE ID = @ID)
select @regionName = NAME FROM A_APPROVED_REGIONS WHERE ID IN (SELECT REGION FROM A_LOCATIONS_HISTORY WHERE ID = @ID)

print 'updating the full addy to ' + isNull(@myFullAddress,'NULL')
print 'updating the full Path to ' + isNull(@myParentPath,'NULL')
print 'updating the parent name to ' + isNull(@parentName,'NULL')
print 'updating the region name to ' + isNull(@regionName,'NULL')

if (select PARENT_PATH FROM A_LOCATIONS_HISTORY WHERE ID = @ID) != @myParentPath
	begin
	print 'Updating the parent path'
	UPDATE A_LOCATIONS_HISTORY SET PARENT_PATH = @myParentPath WHERE ID = @ID
	end
if (select FULL_ADDRESS FROM A_LOCATIONS_HISTORY WHERE ID = @ID) != @myFullAddress
	begin
	print 'Updating the FULL_ADDRESS'
	UPDATE A_LOCATIONS_HISTORY SET FULL_ADDRESS = @myFullAddress WHERE ID = @ID
	end
if (select PARENT_LOCATION_NAME FROM A_LOCATIONS_HISTORY WHERE ID = @ID) != @parentName
	begin
	print 'Updating the PARENT_LOCATION_NAME'
	UPDATE PARENT_LOCATION_NAME SET FULL_ADDRESS = @parentName WHERE ID = @ID
	end
if (select REGION_NAME FROM A_LOCATIONS_HISTORY WHERE ID = @ID) != @regionName
	begin
	print 'Updating the REGION_NAME'
	UPDATE REGION_NAME SET FULL_ADDRESS = @regionName WHERE ID = @ID
	end

print 'Done with A_SP_LOCATIONS_UPDATE_ALL_DATA_FOR_ONE'
GO

