CREATE             PROCEDURE [dbo].[A_SP_FORECASTS_VIEW_ROLLUP]
@forecastID varchar(50),
@forecastHistID varchar(50),
@forecastObjID varchar(50),
@strListToexpand varchar(8000),
@strExpandAllList varchar(8000),
@strNTLogin nvarchar(50)
AS
if @forecastID is not null and @forecastHistID is null
	SELECT @forecastHistID = HISTORY_REF_ID FROM A_FORECASTS WHERE ID = @forecastID
if @forecastObjID is not null and @forecastHistID is null
	SELECT @forecastHistID = ID FROM A_FORECASTS_HISTORY WHERE OBJECT_ID = @forecastObjID

CREATE TABLE #tempExpandList(ID varchar(50))
INSERT INTO #tempExpandList Exec A_SP_Z_SPLIT @strListToexpand,','
CREATE TABLE #tempExpandAllList(ID varchar(50))
INSERT INTO #tempExpandAllList Exec A_SP_Z_SPLIT @strExpandAllList,','
print 'viewing a forecast'
CREATE TABLE #tempForecast
( 
IDENT int IDENTITY PRIMARY KEY,
USE_PUT_TEXT tinyint,
VIEW_ITEM smallInt,
ID varchar(50),
PARENT_ID varchar(50),
NAME varchar(1000),
TREE_LEVEL int,TREE_HAS_CHILD smallInt,EXPANDED smallInt,
CONFIDENCE float,
PROGRESS varchar(50),
FORECAST_ID varchar(50),
FORECAST_NAME varchar(1000),
hidden tinyint,
SHORT_COMMENT varchar(10)
)
print 'The forecast ID is ' + @forecastID
print 'The forecast History ID is ' + @forecastHistID

declare @firstMonth as dateTime
declare @lastMonth as dateTime,@ID varchar(50)
SELECT 
@firstMonth = convert(dateTime,convert(varchar(50),START_MONTH) + '/1/' + convert(varchar(50),START_YEAR)),
@lastMonth = convert(dateTime,convert(varchar(50),STOP_MONTH) + '/1/' + convert(varchar(50),STOP_YEAR))
FROM A_FORECASTS_HISTORY WHERE ID = @forecastHistID
print 'First Month = ' + convert(varchar(50),@firstMonth)
print 'Last Month = ' + convert(varchar(50),@lastMonth)
declare @monthCounter dateTime,@sql varchar(4000)
set @monthCounter = @firstMonth
while @monthCounter <= @lastMonth
	begin
	print 'Adding column for month = ' + convert(varchar(50),month(@monthCounter)) + '/' + convert(varchar(50),year(@monthCounter))
	set @sql = 'ALTER TABLE #tempForecast ADD MONTH_' + 
		convert(varchar(50),month(@monthCounter)) + '_' + convert(varchar(50),year(@monthCounter)) +
		' money NULL,
		ACT_MONTH_' + 
		convert(varchar(50),month(@monthCounter)) + '_' + convert(varchar(50),year(@monthCounter)) +
		' money NULL 


 '
	print @sql
	exec(@sql)
	set @monthCounter = dateAdd(mm,1,@monthCounter)	
	end
ALTER TABLE #tempForecast ADD TOTAL money null,MO_AVG money null,ACTUAL_TOTAL money,ACTUAL_MO_AVG money

exec A_SP_FORECASTS_VIEW_ADD_ONE_FORECAST_TO_ROLL_UP @forecastHistID,1,@firstMonth,@lastMonth,0

declare @cnt int
set @cnt = 0
set @sql = 'UPDATE #tempForecast SET TOTAL = '
set @monthCounter = @firstMonth
while @monthCounter <= @lastMonth
	begin
	set @cnt = @cnt + 1
	print 'Adding column for month = ' + convert(varchar(50),month(@monthCounter)) + '/' + convert(varchar(50),year(@monthCounter))
	set @sql = @sql + ' MONTH_' + 
		convert(varchar(50),month(@monthCounter)) + '_' + convert(varchar(50),year(@monthCounter)) +
		' +'
	set @monthCounter = dateAdd(mm,1,@monthCounter)	
	end
set @sql = left(@sql,len(@sql)-1)
print @sql
exec(@sql)
set @sql = 'UPDATE #tempForecast set MO_AVG = TOTAL / ' + convert(varchar(50),@cnt)
exec(@sql)
set @cnt = 0
set @sql = 'UPDATE #tempForecast SET ACTUAL_TOTAL = '
set @monthCounter = @firstMonth
while @monthCounter <= @lastMonth
	begin
	set @cnt = @cnt + 1
	print 'Adding column for month = ' + convert(varchar(50),month(@monthCounter)) + '/' + convert(varchar(50),year(@monthCounter))
	set @sql = @sql + ' ACT_MONTH_' + 
		convert(varchar(50),month(@monthCounter)) + '_' + convert(varchar(50),year(@monthCounter)) +
		' +'
	set @monthCounter = dateAdd(mm,1,@monthCounter)	
	end
set @sql = left(@sql,len(@sql)-1)
print @sql
exec(@sql)
declare @monthCount int
if (getDate() > @lastMonth)
	set @monthCount = dateDiff(mm,@firstMonth,@lastMonth) + 1
else
	set @monthCount = dateDiff(mm,@firstMonth,getDate()) + 1


set @sql = 'UPDATE #tempForecast set ACTUAL_MO_AVG = ACTUAL_TOTAL / ' + convert(varchar(50),@monthCount)
exec(@sql)





SELECT * FROM #tempForecast WHERE hidden is NULL or hidden <> 1
GO

/****** Object:  StoredProcedure [dbo].[A_SP_FORECASTS_VIEW_FORECASTS_ADD_MONTHLY_DATA_FOR_ITEM]    Script Date: 6/3/2019 2:08:18 PM ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO













CREATE             PROCEDURE [dbo].[A_SP_FORECASTS_VIEW_FORECASTS_ADD_MONTHLY_DATA_FOR_ITEM] 
@ID varchar(50),
@firstMonth dateTime,
@lastMonth dateTime
AS
declare @vperc as float
declare @fType varchar(50)
declare @fID varchar(50)
print 'getting basic data from the Forecast Item Table with this query:'
print 'SELECT @vperc = PERCENT_OF_REV,F_TYPE FROM A_FORECAST_ITEMS WHERE ID = ''' + @ID + ''''
SELECT @vperc = PERCENT_OF_REV,@fType = F_TYPE,@fID = FORECAST_ID FROM A_FORECAST_ITEMS WHERE ID = @ID
declare @monthCounter dateTime,@sql varchar(8000)
set @monthCounter = @firstMonth
--'Sset the name and Paretn ID too
print 'Setting the name and parent ID of this item'
declare @acCom varchar(10),@acName varchar(2000),@conF float,@prog varchar(50),@pID varchar(50)
SELECT @acName = ACCOUNT_NAME + isNull(' ('+convert(varchar(50),PERCENT_OF_REV)+'%)',''),
		@conF = CONFIDENCE,
		@prog = PROGRESS,
		@pID = PARENT_FORECAST_ITEM,
		@acCom = left(NOTE,10)
		FROM A_V_FORECAST_ITEMS_WITH_ACCOUNT_PARENTS WHERE ID = @ID
UPDATE #tempForecast
	set NAME = @acName,
		CONFIDENCE = @conF,
		PROGRESS = @prog,
		PARENT_ID = @pID,
		SHORT_COMMENT = @acCom
	WHERE ID = @ID
	


set @sql = 'UPDATE #tempForecast SET '
while @monthCounter <= @lastMonth
	begin



	print 'Adding Data for month = ' + convert(varchar(50),month(@monthCounter)) + '/' + convert(varchar(50),year(@monthCounter))
	if @fType = 'VAR_COS'
		begin
		print 'This is a Variable cost item so do the special thing for that'
		set @sql = @sql + ' MONTH_' + 
			convert(varchar(50),month(@monthCounter)) + '_' + convert(varchar(50),year(@monthCounter)) +
			' = ' + convert(varchar(50),(@vperc/100)) + ' * isNull((SELECT MONTH_' + 
			convert(varchar(50),month(@monthCounter)) + '_' + convert(varchar(50),year(@monthCounter)) +
			' FROM #tempForecast WHERE ID = ''' + @fid + '_TSR'' AND FORECAST_ID = ''' + @fID + '''),0),'

		set @sql = @sql + ' ACT_MONTH_' + 
			convert(varchar(50),month(@monthCounter)) + '_' + convert(varchar(50),year(@monthCounter)) +
			' = ' + ' isNull((SELECT AMT_INVOICED FROM A_FORECAST_MONTHLY_BREAKDOWN WHERE FI_ID = ''' + @ID + 
					''' AND MO = ''' + convert(varchar(50),month(@monthCounter)) + 
					''' AND YR = ''' + convert(varchar(50),year(@monthCounter)) + '''' + '),0), '

		print 'TESTING THIS RIGHT HERE' + @sql
		end
	else
		begin
		if @fType = 'TAX_F'
			begin
			print 'This is a Tax item so do the special thing for that'
			set @sql = @sql + ' MONTH_' + 
				convert(varchar(50),month(@monthCounter)) + '_' + convert(varchar(50),year(@monthCounter)) +
				' = ' + convert(varchar(50),isNull(@vperc,0)) + ' * ((isNull((SELECT MONTH_' + 
				convert(varchar(50),month(@monthCounter)) + '_' + convert(varchar(50),year(@monthCounter)) +
				' FROM #tempForecast WHERE ID = ''' + @fid + '_EBT'' AND FORECAST_ID = ''' + @fID + '''),0))/100),'
			set @sql = @sql + ' ACT_MONTH_' + 
				convert(varchar(50),month(@monthCounter)) + '_' + convert(varchar(50),year(@monthCounter)) +
				' = ' + convert(varchar(50),isNull(@vperc,0)) + ' * ((isNull((SELECT ACT_MONTH_' + 
				convert(varchar(50),month(@monthCounter)) + '_' + convert(varchar(50),year(@monthCounter)) +
				' FROM #tempForecast WHERE ID = ''' + @fid + '_EBT'' AND FORECAST_ID = ''' + @fID + '''),0))/100),'

			end
		else
			begin
			print 'This is a normal item so do the special thing for that'
			set @sql = @sql + ' MONTH_' + 
				convert(varchar(50),month(@monthCounter)) + '_' + convert(varchar(50),year(@monthCounter)) +
				' = ' + ' isNull((SELECT AMT FROM A_FORECAST_MONTHLY_BREAKDOWN WHERE FI_ID = ''' + @ID + 
				''' AND MO = ''' + convert(varchar(50),month(@monthCounter)) + 
				''' AND YR = ''' + convert(varchar(50),year(@monthCounter)) + '''' + '),0),'
			print 'Adding the actuals for each item here'
			set @sql = @sql + ' ACT_MONTH_' + 
				convert(varchar(50),month(@monthCounter)) + '_' + convert(varchar(50),year(@monthCounter)) +
				' = ' + ' isNull((SELECT AMT_INVOICED FROM A_FORECAST_MONTHLY_BREAKDOWN WHERE FI_ID = ''' + @ID + 
						''' AND MO = ''' + convert(varchar(50),month(@monthCounter)) + 
						''' AND YR = ''' + convert(varchar(50),year(@monthCounter)) + '''' + '),0), '
			print @sql
			end
		end
	set @monthCounter = dateAdd(mm,1,@monthCounter)	
	end
set @sql = left(@sql,len(@sql)-1)
set @sql = @sql + ' WHERE ID = ''' + @ID + ''' '
print isNull(@sql,'This is NULL')
exec(@sql)
GO

/****** Object:  StoredProcedure [dbo].[A_SP_FORECASTS_VIEW_FORECAST_FIGURE_TOTALS]    Script Date: 6/3/2019 2:08:19 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[A_SP_FORECASTS_VIEW_FORECAST_FIGURE_TOTALS] 
@fHistID varchar(50),
@firstMonth datetime,
@lastMonth datetime
AS
print '$$$$$$$$$$Figuring Totals for Forecast = ' + @fHistID
declare @curs as CURSOR,@it varchar(50),@monthCounter dateTime,@sql varchar(8000),@monthField varchar(50)
set @curs = cursor for SELECT f.HISTORY_REF_ID FROM A_FORECAST_ROLL_UP r,A_FORECASTS f WHERE f.ID = r.CHILD AND r.PARENT = @fHistID
open @curs
fetch next from @curs into @it
while @@fetch_status = 0 
	begin
	exec A_SP_FORECASTS_VIEW_FORECAST_ADD_TOTAL_ROW	@fHistID,@it,@firstMonth,@lastMonth,'TSR'
	exec A_SP_FORECASTS_VIEW_FORECAST_ADD_TOTAL_ROW	@fHistID,@it,@firstMonth,@lastMonth,'TCS'
	exec A_SP_FORECASTS_VIEW_FORECAST_ADD_TOTAL_ROW	@fHistID,@it,@firstMonth,@lastMonth,'GM'
	exec A_SP_FORECASTS_VIEW_FORECAST_ADD_TOTAL_ROW	@fHistID,@it,@firstMonth,@lastMonth,'OE'
	exec A_SP_FORECASTS_VIEW_FORECAST_ADD_TOTAL_ROW	@fHistID,@it,@firstMonth,@lastMonth,'EBIT'
	exec A_SP_FORECASTS_VIEW_FORECAST_ADD_TOTAL_ROW	@fHistID,@it,@firstMonth,@lastMonth,'INT'
	exec A_SP_FORECASTS_VIEW_FORECAST_ADD_TOTAL_ROW	@fHistID,@it,@firstMonth,@lastMonth,'EBT'
	exec A_SP_FORECASTS_VIEW_FORECAST_ADD_TOTAL_ROW	@fHistID,@it,@firstMonth,@lastMonth,'TAX'
	exec A_SP_FORECASTS_VIEW_FORECAST_ADD_TOTAL_ROW	@fHistID,@it,@firstMonth,@lastMonth,'NET'
	fetch next from @curs into @it
	end
GO

