CREATE       PROCEDURE [dbo].[A_SP_FILLS_SELECT_FILL_ITEM]
@strWhere nvarchar(4000),
@objTable varchar(50),
@strOrder varchar(2000),
@strNTLogin varchar(50)
AS
declare @sql nvarchar(4000),@myCo varchar(50)
SELECT @myCo = ROOT_COMPANY FROM A_V_PEOPLE_APPROVED_DATA WHERE ID = @strNTLogin
set @sql = 'SELECT * '
if @objTable = 'A_ACTUAL_PARTS_HISTORY'
	begin
	set @sql = @sql + ' , isNull(NAME,'''') + ''['' + convert(varchar(50),isNull(QTY,1)) + '']'' AS DISPLAY_NAME FROM A_V_FILLS_ACTUAL_PART_SEARCH WHERE'
--	set @sql = @sql + ' WHERE CREATING_CO = ''' + @myCo + ''' AND AP_STATUS = ''ap_available'' AND ' + @strWhere

	set @sql = @sql + '(CUR_OWNER = ''' + @myCo + ''' OR CUR_OWNER IN ( SELECT CHILD_COMPANY 
						FROM A_COMPANIES_CHILD_LOOKUP_TABLE WHERE COMPANY = ''' + @myCo + ''' ))'
	set @sql = @sql + ' AND AP_STATUS = ''ap_available'' AND ' + @strWhere 
	end
else
	begin
	set @sql = @sql + ' , isNull(NAME,'''') + ''['' + convert(varchar(50),isNull(QTY,1)) + '']'' AS DISPLAY_NAME FROM A_V_ACTUAL_PARTS_APPROVED_DATA '
	--set @sql = @sql + ' WHERE AP_STATUS = ''ap_available'' AND ' + @strWhere
	end

print @sql
exec(@sql)
GO

/****** Object:  StoredProcedure [dbo].[A_SP_FILLS_SEARCH]    Script Date: 6/3/2019 2:08:34 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO







CREATE       PROCEDURE [dbo].[A_SP_FILLS_SEARCH]
@strWhere nvarchar(4000),
@strSort nvarchar(50),
@strNTLogin nvarchar(50)
AS

--find out my Company
declare @myCO as nvarchar(50)
exec A_SP_GET_PERSON_COMPANY @strNTLogin,@myCO OUTPUT

declare @sql nvarchar(4000)
set @sql = 'SET QUOTED_IDENTIFIER OFF SELECT * FROM A_V_FILLS_SEARCH '

set @sql = @sql + 'WHERE ('
print 'adding that i can see where i am the customer and fill by is customer'
set @sql = @sql + '(CUSTOMER = ''' + @myCo + ''' AND FILL_BY = ''CUSTOMER'') '
print 'adding that i can see where i am the supplier and fill by is SUPPLIER'
set @sql = @sql + ' OR (SUPPLIER = ''' + @myCo + ''' AND FILL_BY = ''SUPPLIER'') '
print 'adding that i can see where fill by is SUPPLIER and supplier is one of my child companies'
set @sql = @sql + ' OR (SUPPLIER IN (SELECT CHILD_COMPANY FROM A_COMPANIES_CHILD_LOOKUP_TABLE WHERE COMPANY = ''' + @myCo + ''') AND FILL_BY = ''SUPPLIER'') '
if len(@strWhere) > 0
		set @sql = @sql + ') AND ' + @strWhere + ' '

if len(@strSort) > 0
		set @sql = @sql + @strSort

print @sql
exec (@sql)
GO

/****** Object:  StoredProcedure [dbo].[A_SP_FILL_TASK_FILL_FROM_LOCATION]    Script Date: 6/3/2019 2:08:35 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO





CREATE   PROCEDURE [dbo].[A_SP_FILL_TASK_FILL_FROM_LOCATION]
@retID varchaR(50) OUTPUT,
@retMSG varchar(2000) OUTPUT,
@strLocation varchar(50),
@strTaskID varchar(50),
@strNTLogin varchar(50)
AS


declare @retStat varchar(50),@msgs varchar(50)
exec A_SP_TASK_ACCEPT @retStat OUTPUT,@msgs OUTPUT,@strTaskID,@strNTLogin
if @retStat is not null
	begin
		if not exists(SELECT * FROM A_TASKS WHERE ID = @strTaskID AND STATUS = 'ACCEPTED' AND REQUESTEE_ID = @strNTLogin)
			begin
			print 'Task returned a message'
			set @retID = 'YOU CAN NOT ACCEPT THIS TASK'
			goto fin
			end
	end

print 'Task Accepted Moving on'

print 'Searching for a fill item'
if @strLocation is null
	begin
		print 'We need a fill location'
		set @retID = 'YOU FORGOT TO SELECT A LOCATION'
		goto fin
	end

declare @fillItemID varchar(50),@appObjID varchar(50),@qty float,@fillID varchar(50)

SELECT @appObjID = OBJ_PROD_APPLIES_TO, @qty = TOT_QTY,@fillID = ID
	FROM A_V_FILLS_SEARCH 
	WHERE TASK_ID = @strTaskID

print 'The appObjID is ' + @appObjID
if @appObjID is null
	begin
		print 'Cant Find App Obj ID'
		set @retID = 'There is no Applicable Object for this Product'
		goto fin
	end

declare @actPartID varchar(50)
SELECT @actPartID = ID FROM A_V_ACTUAL_PARTS_APPROVED_DATA 
	WHERE
	PART_ID = @appObjID AND 
		(
		LOCATION IN (SELECT CHILD_LOC FROM A_LOCATIONS_CHILD_LOOKUP WHERE LOCATION = @strLocation) 
		OR 
		LOCATION = @strLocation
		)
	AND AP_STATUS = 'ap_available'
	AND QTY > @qty

if @actPartID is null
	begin
	print 'Could not find an actual part to fill this item'
	set @retID = 'There are no Parts at this location'
	goto fin
	end
declare @msg varchar(200),@newFillID varchar(50)
	exec A_SP_FILLS_UPDATE_FILL 
	@newFillID OUTPUT,
	@msg OUTPUT,
	@fillID,
	@actPartID,
	@strNTLogin



set @retID = 'Success'

fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_FILL_START_PROCEDURE_IF_POSSIBLE]    Script Date: 6/3/2019 2:08:35 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE                         PROCEDURE [dbo].[A_SP_FILL_START_PROCEDURE_IF_POSSIBLE] 
@fillID varchar(50),
@strNTLogin varchar(50)
AS

 print 'We just made a fill, so we need to see if the purchase already has been started or if 
	this is the last fille of the purchase to be filled'
declare @mySQL varchar(7500)
declare @purchItemID varchar(50), @purchHistID varchar(50)
SELECT @purchItemID = PURCH_ITEM_ID FROM A_FILLS WHERE ID = @fillID
SELECT @purchHistID = PURCHASE_HIST_ID FROM A_ORDER_ITEMS WHERE ID = @purchItemID

print 'Make sure there are no other fills that need to be done before we start this product'
if exists(SELECT * FROM A_V_FILLS_SEARCH WHERE PURCHASE_HIST_ID = @purchHistID AND FILL_OBJ_ID is null)
	begin
	print 'There are more fills to be done, so we can not start yet'
	print 'SELECT * FROM A_V_FILLS_SEARCH WHERE PURCHASE_HIST_ID = ''' + @purchHistID + ''' AND FILL_OBJ_ID is null'
	goto fin
	end

print 'This is a new one and there are no more fills that need to be filled. we are going to have to create all the tasks for the purchase'

declare @phID varchar(50),@purchaser varchar(50),@taskName nvarchar(2000),
	@newTaskID nvarchar(50),@messages nvarchar(2000)

SELECT @phID = PURCHASE_HIST_ID,
	@purchaser = PURCHASER_ID,
	@taskName = 'Manage Purchase # ' + PURCHASE_ID
	FROM A_V_FILLS_SEARCH
	WHERE ID = @fillID

if exists(SELECT * FROM A_TASK_ORDER_INFORMATION WHERE PURCHASE_HIST_ID = @phID AND FILL_ID IS NULL)
	begin
	declare @myTask varchar(50)
	SELECT @myTask = TASK_ID FROM A_TASK_ORDER_INFORMATION WHERE PURCHASE_HIST_ID = @phID
	print 'There is already a task for this purchase it is task # ' + @myTask
	goto fin
	end	



if @purchaser is null
	begin
	print 'Purchaser is null'
	return 1
	end

print 'First create a manage purchase task'

exec A_SP_TASKS_UPDATE_TASK @newTaskID OUTPUT,@messages OUTPUT,
	null, --ID
	null, --Parent,
	@purchaser,--Requestor
	@purchaser, --REQUESTEE_ID,
	null, --GROUP_REQUESTEE_ID
	@taskName, --DESCRIPTION 
	@taskName, --Title
	'SYS_PURCHASE', --SYSTEM_TASK,
	NULL, --COMMENT,
	'3', --Security Level
	null, --counter
	null, --orig planned Start Date
	null, --orig planned stop date,
	null, --@ORIG_PLANNED_COUNTER_START numeric,
	null, --@ORIG_PLANNED_COUNTER_STOP numeric,
	null, --@CUR_PLANNED_START_DATE dateTime,
	null, --@CUR_PLANNED_STOP_DATE dateTime,
	null, --@CUR_PLANNED_COUNTER_START numeric,
	null, --@CUR_PLANNED_COUNTER_STOP numeric,
	null, --@ACTUAL_START_DATE dateTime,
	null, --@ACTUAL_STOP_DATE dateTime,
	null, --@ACTUAL_COUNTER_START numeric,
	null, --@ACTUAL_COUNTER_STOP numeric,
	null, --@REF_PROC_LIST varchar(8000),
	null, --@REF_FILE_LIST varchar(8000),
	null, --@DISCUSSIONS varchar(8000),
	null, --@SURVEYS varchar(8000),
	null, --@MEETINGS varchar(8000),
	null, --Object varchar(8000),
	null, --@COMPANIES varchar(8000),
	null, --@SYSTEM_PEOPLE_TO_EMAIL varchar(8000),
	'1', --@PRIORITY smallInt,
	null, --@ADDITIONAL_ASSIGNEES varchar(8000),
	@purchaser --strNTLogin
	print 'Created A Task with the ID of ' + @newTaskID
	print 'Now to add the data to the TASK_ORDER_INFORMATION table'
	if not exists(SELECT * FROM A_TASK_ORDER_INFORMATION WHERE TASK_ID = @newTaskID)
		INSERT INTO A_TASK_ORDER_INFORMATION 
		(TASK_ID)
		VALUES
		(@newTaskID)

	UPDATE A_TASK_ORDER_INFORMATION 
		SET PURCHASE_HIST_ID = @phID,DRCM = getDate(),MODBY= @strNTLogin
		WHERE TASK_ID = @newTaskID

	declare @SUBMIT_STATUS varchar(50)
	print 'Submitting Task'
	exec A_SP_TASK_SUBMIT @SUBMIT_STATUS OUTPUT,@messages OUTPUT,@newTaskID,@purchaser
	print 'Done Submitting Task'

print 'Created the manage purchase task with the id of ' + @newTaskID
print 'Creating tasks for all the root purchase Items'
Declare @pItemID nvarchar(50), @curs Cursor
set @curs = Cursor For 
	SELECT DISTINCT PURCH_ITEM_ID FROM A_V_FILLS_SEARCH 
		WHERE PURCHASE_HIST_ID = @phID AND PURCHASE_ITEM_PARENT_ID is NULL

open @curs
Fetch Next from @curs Into @pItemID
while (@@fetch_status = 0)
	Begin
 	print 'Creating a task for purchase item = ' + @pItemID
	set @mySQL = 'exec A_SP_PURCHASE_ITEM_CREATE_TASK ' +
	isnull('''' + @pItemID + '''','NULL') + ',' +
	isnull('''' + @newTaskID + '''','NULL') + ',' +
	isnull('''' + @strNTLogin + '''','NULL') + ''
	exec A_SP_ADMIN_SQL_TO_RUN_QUE_UP @mySQL,@strNTLogin
 	Fetch Next from @curs Into @pItemID
	End
close @curs
Deallocate @curs
print 'Finished Creating tasks for all the root purchase Items'

	set @mySQL = 'exec A_SP_PURCHASE_UPDATE_STATUS_OF_ALL_TASKS ' +
	isnull('''' + @phID + '''','NULL') + ',' +
	isnull('''' + @strNTLogin + '''','NULL') + ''
exec A_SP_ADMIN_SQL_TO_RUN_QUE_UP @mySQL,@strNTLogin

fin:
print 'Exiting A_SP_FILL_START_PROCEDURE_IF_POSSIBLE'
GO

/****** Object:  StoredProcedure [dbo].[A_SP_FILL_SPLIT_FROM_BATCH]    Script Date: 6/3/2019 2:08:35 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO



CREATE   PROCEDURE [dbo].[A_SP_FILL_SPLIT_FROM_BATCH]
@subFillID varchar(50),
@strNTLogin varchar(50)
AS
print 'Splitting out fill Item with ID = ' + @subFillID
declare @batchFillID varchar(50)
SELECT @batchFillID = BATCH_PARENT FROM A_FILLS WHERE ID = @subFillID
print 'removing Fill ' + @subFillID + ' to Batch Fill ' + @batchFillID
print 'First lets uninstall our part from the batch part'
declare @subPartID varchar(50),@batchPartID varchar(50)
SELECT @batchPartID = FILL_OBJ_ID FROM A_FILLS WHERE ID = @batchFillID
SELECT @subPartID = FILL_OBJ_ID FROM A_FILLS WHERE ID = @subFillID
UPDATE A_ACTUAL_PARTS_HISTORY SET PARENT_ID = null 
	WHERE OBJECT_ID IN (SELECT ID FROM A_OBJECTS WHERE ROOT = @subPartID)
print 'Now lets update our fill info'
UPDATE A_FILLS SET BATCHED = null, BATCH_PARENT = null WHERE ID = @subFillID
exec A_SP_ACTUAL_PARTS_CREATE_CHILD_LIST null,@batchPartID,0,null,@strNTLogin
print 'Now get the copy task id'
declare @copyTaskID varchar(50),@myTaskID varchar(50)
SELECT @copyTaskID = TASK_ID FROM A_TASK_ORDER_INFORMATION WHERE FILL_ITEM_ID = @batchFillID

print 'Batch TASK ID = ' + @copyTaskID
exec sp_GetUniqueID3 @myTaskID OUTPUT
INSERT INTO A_TASKS (

--ID,DESCRIPTION,STATUS,COMMENT,REQUESTOR,CREATED_BY,CREATE_DATE,PROCEDURE_ID,SECURITY_LEVEL,
--GROUP_REQUESTEE_ID,HAS_CHILD,HAS_REF_PROC,ORIG_REQUESTOR_ID,PRIORITY,CHILD_STATUS,RECURSION_NUMBER)

ID,DESCRIPTION,Title,STATUS,COMMENT,REQUESTOR,
[COMPLETED_BY],[MODBY],[DRCM],[CHILD_ORDER],[CREATED_BY],
[CREATE_DATE],[CLOSED],[OPENED_BY],[OPEN_DATE],[SYSTEM_TASK],[PROCEDURE_ID],[PROCEDURE_STEP_ID], 
[SECURITY_LEVEL],[COUNTER],[REQUESTEE_ID],[GROUP_REQUESTEE_ID],[COUNTER_NAME],[COUNTER_VALUE],
[ORIG_PLANNED_START_DATE],[ORIG_PLANNED_STOP_DATE],[CUR_PLANNED_START_DATE],[CUR_PLANNED_STOP_DATE],
[ACTUAL_START_DATE],[ACTUAL_STOP_DATE],[ORIG_PLANNED_COUNTER_START],[ORIG_PLANNED_COUNTER_STOP],
[CUR_PLANNED_COUNTER_START],[CUR_PLANNED_COUNTER_STOP],[ACTUAL_COUNTER_START],[ACTUAL_COUNTER_STOP],
[LATEST_REQUESTEE_NAME],[HAS_DISCUSSION],[HAS_SURVEY],[HAS_CHILD],[HAS_REF_PROC],[HAS_FILE],[ORIG_REQUESTOR_ID],
[HAS_REF_OBJ],[HAS_MONITOR],[COLOR_CODE],[LAST_REQUEST_DATE],[PRIORITY],[CHILD_STATUS],[IS_QUOTE],
[IS_QUOTE_ACCEPT], [IS_FILL], [MANAGER], [DNR_TYPE], [RECURSION_NUMBER], [REPEAT_FROM_STEP]

)
	SELECT 
@myTaskID,DESCRIPTION,Title,STATUS,'Copied from Batch = ' + @BatchFillID,REQUESTOR,
[COMPLETED_BY],[MODBY],[DRCM],[CHILD_ORDER],[CREATED_BY],
[CREATE_DATE],[CLOSED],[OPENED_BY],[OPEN_DATE],[SYSTEM_TASK],[PROCEDURE_ID],[PROCEDURE_STEP_ID], 
[SECURITY_LEVEL],[COUNTER],[REQUESTEE_ID],[GROUP_REQUESTEE_ID],[COUNTER_NAME],[COUNTER_VALUE],
[ORIG_PLANNED_START_DATE],[ORIG_PLANNED_STOP_DATE],[CUR_PLANNED_START_DATE],[CUR_PLANNED_STOP_DATE],
[ACTUAL_START_DATE],[ACTUAL_STOP_DATE],[ORIG_PLANNED_COUNTER_START],[ORIG_PLANNED_COUNTER_STOP],
[CUR_PLANNED_COUNTER_START],[CUR_PLANNED_COUNTER_STOP],[ACTUAL_COUNTER_START],[ACTUAL_COUNTER_STOP],
[LATEST_REQUESTEE_NAME],[HAS_DISCUSSION],[HAS_SURVEY],[HAS_CHILD],[HAS_REF_PROC],[HAS_FILE],[ORIG_REQUESTOR_ID],
[HAS_REF_OBJ],[HAS_MONITOR],[COLOR_CODE],[LAST_REQUEST_DATE],[PRIORITY],[CHILD_STATUS],[IS_QUOTE],
[IS_QUOTE_ACCEPT], [IS_FILL], [MANAGER], [DNR_TYPE], [RECURSION_NUMBER], [REPEAT_FROM_STEP]

	FROM A_TASKS 
	WHERE ID = @copyTaskID

if @@ERROR <> 0 goto problem
INSERT INTO A_TASK_ASSIGNEE (ID,TASK_ID,PERSON_ASSIGNED,ROLE_ASSIGNED,REQUESTOR,REQUEST_DATE,ACTIVE,STATUS)
	SELECT newID(),@myTaskID,PERSON_ASSIGNED,ROLE_ASSIGNED,REQUESTOR,REQUEST_DATE,ACTIVE,STATUS
	FROM A_TASK_ASSIGNEE 
	WHERE TASK_ID = @copyTaskID
if @@ERROR <> 0 goto problem
exec A_SP_TASKS_UPDATE_DATA @myTaskID,@strNTLogin
print 'Created the Task now to copy or create all the other things'
print 'Inserting into A_TASK_ACTUAL_PARTS_LINKED_WHEN_FINISHED'
INSERT INTO A_TASK_ACTUAL_PARTS_LINKED_WHEN_FINISHED (ID,TASK_ID,ACTUAL_PART_ID)
		VALUES (newID(),@myTaskID,@subPartID)
if @@ERROR <> 0 goto problem
print 'Inserting into A_TASK_OBJECT_LINK'
INSERT INTO A_TASK_OBJECT_LINK (ID,TASK_ID,OBJECT_ID)
		VALUES (newID(),@myTaskID,@subPartID)
if @@ERROR <> 0 goto problem
UPDATE A_TASK_ORDER_INFORMATION SET 
	TASK_ID = @myTAskID
WHERE FILL_ITEM_ID = @subFillID

if @@ERROR <> 0 goto problem
INSERT INTO A_TASK_REFERENCE_PROCEDURES (ID,TASK_ID,REF_PROCEDURE)
	SELECT newID(),@myTAskID,REF_PROCEDURE FROM A_TASK_REFERENCE_PROCEDURES WHERE TASK_ID = @copyTaskID
if @@ERROR <> 0 goto problem
print 'Now we have a batch task and we need to steal all the steps from the other one'
declare @curs as CURSOR,@subTaskID as varchar(50),@newID varchar(50)
set @curs = cursor for SELECT ID FROM A_TASKS WHERE PARENT_ID = @copyTaskID
open @curs
fetch next from @curs into @subTaskID
while @@fetch_status = 0
	begin
	exec A_SP_TASK_COPY_TASK_FOR_BATCH_SPLIT @newID OUTPUT,@subTaskID,@myTaskID,@strNTLogin
	INSERT INTO A_TASK_ACTUAL_PARTS_LINKED_WHEN_FINISHED (ID,TASK_ID,ACTUAL_PART_ID)
		VALUES (newID(),@newID,@subPartID)
	if @@ERROR <> 0 goto problem
	INSERT INTO A_TASK_OBJECT_LINK (ID,TASK_ID,OBJECT_ID)
		VALUES (newID(),@newID,@subPartID)
	if @@ERROR <> 0 goto problem
	INSERT INTO A_TASKS_RELATION_TABLE ([ID], [PARENT_ID], [CHILD_ID], [LEV] )
		values (newID(),@myTaskID,@newID,1)
	if @@ERROR <> 0 goto problem
	fetch next from @curs into @subTaskID
	end


print 'Stole all the steps'





goto fin
problem:
print 'THERE WAS AN ERROR'
fin:
print 'Done'
GO

/****** Object:  StoredProcedure [dbo].[A_SP_FILL_ITEM_UPDATE_QTY]    Script Date: 6/3/2019 2:08:36 PM ******/
