GO




CREATE   procedure [dbo].[A_SP_COMPANY_CHECK_VALIDITY]
	@returnVal nvarchar(2000) OUTPUT,
	@ID nvarchar(50),
	@strNTLogin nvarchar(50)
as
print 'Entering A_SP_COMPANY_CHECK_VALIDITY'
declare @name as nvarchar(1000), @retVal as nvarchar(2000), @objID as nvarchar(50),
	@parentID as varchar(50)
select @objID = OBJECT_ID,@name = name, @parentID = PARENT FROM A_COMPANIES_HISTORY WHERE ID = @ID
set @retVal = ''
--first check to make sure the company has a name
if (@name = '' or @name is null)
	begin 
	print 'Company has no name'
	set @retVal = @retVal + 'NO_NAME_FOR_COMPANY,'
	end
--now check to make sure that if they have 
--no parent ID and they are rev 1 
--then they need to have a person in the new person table
declare @login as nvarchar(200),@password as nvarchar(100),@rev as smallint
SELECT @rev = REV  FROM A_OBJECTS WHERE ID = @objID
if @rev = 1 and @parentID is null
	begin
	select @login = LOGIN_NAME, @password = PASSWORD FROM A_COMPANIES_NEW_PERSON_DATA WHERE CO_ID = @ID
	if @login is null
		set @retVal = @retVal + 'NO_LOGIN_FOR_ADMIN_PERSON,'
	if @password is null
		set @retVal = @retVal + 'NO_PASSWORD_FOR_ADMIN_PERSON,'
	end
		

print 'returnVal = ' + isNull(@retVal,'NULL')
set @returnVal = @retVal
--Finished


fin:
GO

/****** Object:  StoredProcedure [dbo].[A_SP_COMPANY_ADD_TO_TREE_TABLE]    Script Date: 6/3/2019 2:09:20 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO



CREATE   PROCEDURE [dbo].[A_SP_COMPANY_ADD_TO_TREE_TABLE]
@ID varchar(50),
@LEV integer,
@exAll smallint
AS
print 'First Checking to see if we are in the expand All List'
If @ID in (SELECT ID FROM #tempExpandAllList)
	begin
	print 'ID = ' + @ID + 'Is in the expand all list'
	set @exAll = 1
	end
print 'Insert My ID and Level into the tree table'
declare @tester as varchar(50)
SELECT TOP 1 @tester = ID FROM A_COMPANIES_HISTORY WHERE PARENT = (@ID)
print 'Checking for Child using ID = ' + @ID
if @tester is not null
	begin
	set @tester = '1'
	end
else
	set @tester = '0'

INSERT INTO #tempCoTree(ID,LEV,HAS_CHILD,EXPANDED) VALUES(@ID,@LEV,convert(smallInt,@tester),0)
IF ((@ID in (SELECT ID FROM #tempExpandList)) or (@exAll = 1))
	begin
	UPDATE #tempCoTree SET EXPANDED = 1 WHERE ID = @ID
	print 'This one needs to be expanded so make a cursor for children and do it'
	Declare @it nvarchar(50)
	Declare @curs Cursor
	set @curs = Cursor For SELECT a.ID FROM A_COMPANIES a,A_COMPANIES_HISTORY h 
	WHERE h.PARENT = @ID AND a.HISTORY_REF_ID = h.ID ORDER BY h.NAME
	open @curs
	Fetch Next from @curs Into @it
	set @LEV = @LEV + 1
	while (@@fetch_status = 0)
		Begin
		print 'Adding  a child ' + @it
		exec A_SP_COMPANY_ADD_TO_TREE_TABLE @it,@LEV,@exAll
		Fetch Next from @curs Into @it
		End
	close @curs
	Deallocate @curs
	end
GO

