CREATE   PROCEDURE [dbo].[A_SP_APPROVALS_FURTHER_EDIT]
@msg nvarchar(500) OUTPUT,
@theID nvarchar(50) OUTPUT,
@WFS_ID nvarchar(50),
@WF_STAGE_ID nvarchar(50),
@WF_GROUP_ID nvarchar(50),
