declare @html varchar(4000)
set @html = '
			<obj type="text"><attribute name="value" value="ANSWER Update Email" /></obj>
			<obj type="link">
				<attribute name="url" value="' +  dbo.getEmailURL() + '/' + @linkPath + '" />
