/****** Object:  StoredProcedure [dbo].[A_SP_ACTUAL_PARTS_UPDATE_PART]    Script Date: 6/3/2019 2:09:43 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO










CREATE                      PROCEDURE [dbo].[A_SP_ACTUAL_PARTS_UPDATE_PART]
@newID nvarchar(50) OUTPUT,
@messages nvarchar(2000) OUTPUT,
@objID nvarchar(50),
@PART_ID varchar(50),
@QTY varchar(50),
@SERIAL nvarchar(1000),
@NICK_NAME nvarchar(1000),
@LOCATION_ID varchar(50),
@CUR_OWNER varchar(50),
@AP_STATUS varchar(50),
@PRODUCTS varchar(8000),
@PARENT_ID varchar(50),
@subpartAction varchar(10),
@responsiblePerson varchar(50),
@strNTLogin varchar(50)
AS
begin Transaction
if @QTY is null	set @QTY = 1
if @QTY = 0 goto PROBLEM

declare @newAPID as varchar(50)
print 'Updating an Actual Part'
declare @intN as smallint
set @intN = 0
if @objID is null
	begin
		print 'ID is Null  we need to create this Actual Part'
		exec sp_GetUniqueID3 @newID OUTPUT
		INSERT INTO A_ACTUAL_PARTS_HISTORY (ID,NICK_NAME,SERIAL,MODBY,DRCM,PARENT_ID) 
			VALUES (@newID,@NICK_NAME,@SERIAL,@strNTLogin,getDATE(),@PARENT_ID)
		if @@ERROR <> 0 goto problem
		SELECT @newID = OBJECT_ID FROM A_ACTUAL_PARTS_HISTORY WHERE ID = @newID
		print 'Done Creating now continueing'
	end
else
	begin
		print 'The ID is not null so we are just updating product object ID = ' + @objID
		set @newID = @objID
	end

SELECT @newAPID = ID FROM A_ACTUAL_PARTS_HISTORY WHERE OBJECT_ID = @newID
if @newAPID is null
	begin
		print 'Error Can not find this Part'
		goto problem
	end


print 'We need to do a little work here if the parent is not null'
if @PARENT_ID is not null
	begin
		print 'The Parent ID = ' + @PARENT_ID
		set @AP_STATUS = 'ap_installed'
		if @@ERROR <> 0 goto problem
		SELECT @LOCATION_ID = LOCATION FROM A_V_ACTUAL_PARTS_APPROVED_DATA WHERE ID = @PARENT_ID
		if @@ERROR <> 0 goto problem
	end

print 'Updating the ap history data ' + @AP_STATUS
UPDATE A_ACTUAL_PARTS_HISTORY SET
PARENT_ID = @PARENT_ID,
PART_ID = @PART_ID,
QTY = @QTY,
SERIAL = @SERIAL,
NICK_NAME = @NICK_NAME,
LOCATION = @LOCATION_ID,
CUR_OWNER = @CUR_OWNER,
AP_STATUS = @AP_STATUS,
MODBY = @strNTLogin,
SUB_PART_ACTION = @subPartAction,
RESPONSIBLE_PERSON = @responsiblePerson,
DRCM = getDate()
WHERE OBJECT_ID = @newID
if @@ERROR <> 0 goto problem

DELETE FROM A_ACTUAL_PART_PRODUCTS_INSIDE_LINK WHERE ACTUAL_PART_ID = @newAPID
if @@ERROR <> 0 goto problem
CREATE TABLE #TempItems(IT varchar(50))
INSERT INTO #TempItems Exec A_SP_Z_SPLIT @PRODUCTS,','
if @@ERROR <> 0 goto problem
CREATE TABLE #TempItemsII(IT varchar(50))
if @@ERROR <> 0 goto problem
INSERT INTO #TempItemsII SELECT DISTINCT IT FROM #TempItems
if @@ERROR <> 0 goto problem

INSERT INTO A_ACTUAL_PART_PRODUCTS_INSIDE_LINK (ID,ACTUAL_PART_ID,PRODUCT_ID,DRCM,MODBY)
	SELECT newID(),@newAPID,ltrim(IT),getDate(),@strNTLogin FROM #TempItemsII
if @@ERROR <> 0 goto problem

fin:
if @@trancount > 0 COMMIT TRANSACTION
print 'Finished A_SP_ACTUAL_PARTS_UPDATE_PART with no errors'
return 0

PROBLEM:
if @@trancount > 0 	ROLLBACK TRANSACTION
print ' There was a problem in A_SP_ACTUAL_PARTS_UPDATE_PART and we will terminate and not finish anything '
return 1
raiserror('Problem creating an actual part',16,1)
GO

/****** Object:  StoredProcedure [dbo].[A_SP_ACTUAL_PARTS_UPDATE_CHILD_PART]    Script Date: 6/3/2019 2:09:44 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO










CREATE        PROCEDURE [dbo].[A_SP_ACTUAL_PARTS_UPDATE_CHILD_PART]
@newID nvarchar(50) OUTPUT,
@messages nvarchar(2000) OUTPUT,
@ID nvarchar(50),
@PARENT_ID varchar(50),
@PART_ID varchar(50),
@QTY varchar(50),
@SERIAL varchar(50),
@NICK_NAME varchar(50),
@CUR_OWNER varchar(50),
@AP_STATUS varchar(50),
@PRODUCTS varchar(8000),
@strNTLogin varchar(50)
AS
declare @ROOT_ID as varchar(50)
declare @intN as smallint
set @intN = 0
print 'Updating an Actual PArt Child'
if @ID is null
	begin
		print 'ID is Null  we need to create this Actual Part'
		print 'first get the root pdata from the parent id'
		SELECT @ROOT_ID = ROOT_ID FROM A_ACTUAL_PARTS_SUB_PARTS WHERE ID = @PARENT_ID
		exec sp_GetUniqueID3 @newID OUTPUT
		INSERT INTO A_ACTUAL_PARTS_SUB_PARTS (ID,PARENT_ID,ROOT_ID,MODBY,DRCM) 
		VALUES (@newID,@PARENT_ID,@ROOT_ID,@strNTLogin,getDATE())
		set @intN = 1
	end
else
	begin
		set @newID = @ID
	end

UPDATE A_ACTUAL_PARTS_SUB_PARTS SET
PARENT_ID = @PARENT_ID,
PART_ID = @PART_ID,
QTY = @QTY,
SERIAL = @SERIAL,
CUR_OWNER = @CUR_OWNER,
AP_STATUS = @AP_STATUS,
NICK_NAME = @NICK_NAME,
DRCM = getDAte(),
MODBY = @strNTLogin
WHERE ID = @newID


if (@intN = 1 and @PART_ID is not null)
	begin
	print 'This is a new part so add all the childs automatically'
	exec A_SP_ACTUAL_PART_SUB_PARTS_AUTO_CREATE_CHIL_PT_4_PARENT @newID,@strNTLogin
	end

print 'Updating Products List for the Part'
print 'First delete all the ones we used to have'
DELETE FROM A_ACTUAL_PART_PRODUCTS_INSIDE_LINK WHERE ACTUAL_PART_ID = @newID
print 'making a cursor to go through the string'
CREATE TABLE #TempItems	(IT varchar(50))
INSERT INTO #TempItems Exec A_SP_Z_SPLIT @PRODUCTS,', '
Declare @it nvarchar(50)
Declare @curs Cursor
set @curs = Cursor For SELECT * FROM #TempItems
open @curs
Fetch Next from @curs Into @it
while (@@fetch_status = 0)
Begin
	print 'Adding Reference Product = ' + @it
	INSERT INTO A_ACTUAL_PART_PRODUCTS_INSIDE_LINK(ID,ACTUAL_PART_ID,PRODUCT_ID,DRCM,MODBY)
	VALUES (newID(),@newID,ltrim(@it),getDate(),@strNTLogin)
	Fetch Next from @curs Into @it
End
close @curs
Deallocate @curs
GO

/****** Object:  StoredProcedure [dbo].[A_SP_ACTUAL_PARTS_SPLIT_PART]    Script Date: 6/3/2019 2:09:44 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO


CREATE           PROCEDURE [dbo].[A_SP_ACTUAL_PARTS_SPLIT_PART]
	@newID varchar(50) OUTPUT,
	@msg varchar(4000) OUTPUT,
	@objID varchar(50),
	@DISTS varchar(200),
	@strNTLogin varchar(50)
AS
begin transaction
print 'Splitting part obj =  ' + @objID
declare @myQTY as numeric
SELECT @myQTY = QTY FROM A_ACTUAL_PARTS_HISTORY WHERE OBJECT_ID = @objID
if @@ERROR <> 0 goto problem
print 'The max QTY - '
print @myQTY

print 'Updating The QTYS'
CREATE TABLE #TempItems	(IT varchar(50))
INSERT INTO #TempItems Exec A_SP_Z_SPLIT @DISTS,'_____'
print 'First Lets Check the QTYS to make sure they are ok'
declare @splitQTYS as numeric
declare @nID as varchar(50),@msg2 nvarchar(4000)
declare @newObjID as varchar(50)
declare @newRootPart as varchar(50)
declare @tot as int
SELECT @tot = Count(IT) FROM #TempItems
print 'making a cursor to go through the splits and make the divisions'
Declare @it nvarchar(50)
Declare @curs Cursor
declare @cnt smallint
set @cnt = 1
set @curs = Cursor For SELECT * FROM #TempItems
open @curs
Fetch Next from @curs Into @it
print 'The first Qty = ' + @it
if @@ERROR <> 0 goto problem
while (@@fetch_status = 0) and (@cnt < @tot)
	Begin
	print 'Creating a new Actual Part with QTY = ' + @it
	exec A_SP_OBJECT_COPY @newObjID OUTPUT,@msg2 OUTPUT,@objID,'',@strNTLogin
	if @@ERROR <> 0 goto problem
	print 'Copied it now getting its ID'
	SELECT @nID = ID FROM A_ACTUAL_PARTS_HISTORY WHERE OBJECT_ID = @newObjID
	set @newID = @newObjID
	if @@ERROR <> 0 goto problem
	print 'Got its ID = ' + @nID
	UPDATE A_OBJECTS SET LOCKED_BY = NULL,STATUS='APPROVED'WHERE ID = @newObjID
	if @@ERROR <> 0 goto problem
	print 'Unlocked it and set status to approved'
	UPDATE A_ACTUAL_PARTS_HISTORY SET QTY = @it WHERE OBJECT_ID = @newObjID
	if @@ERROR <> 0 goto problem
	print 'Updates its quanitity'
	exec A_SP_ACTUAL_PARTS_FINISH_WF @nID,@newObjID,@strNTLogin
	if @@ERROR <> 0 goto problem
	set @msg = isNull(@msg + ',','') + @nID
	Fetch Next from @curs Into @it
	if @@ERROR <> 0 goto problem
	set @cnt = @cnt + 1
	End
close @curs
Deallocate @curs
declare @oldQty float,@mult float,@ap_ID varchar(50)
SELECT @oldQty = QTY FROM A_ACTUAL_PARTS_HISTORY WHERE OBJECT_ID = @objID
SET @mult = @it / @oldQty
UPDATE A_ACTUAL_PARTS_HISTORY
	SET QTY = @it
	WHERE OBJECT_ID = @objID
SELECT @ap_ID = ROOT FROM A_OBJECTS WHERE ID=@objID
exec A_SP_ACTUAL_PARTS_CASCADE_QTYS_FOR_A_PART_BY_ID @mult,@ap_ID
if @@ERROR <> 0 goto problem

fin:
if @@trancount > 0 COMMIT TRANSACTION
print 'Finished A_SP_ACTUAL_PARTS_SPLIT_PART with no errors'
return 0
PROBLEM:
if @@trancount > 0 	ROLLBACK TRANSACTION
print ' There was a problem in A_SP_ACTUAL_PARTS_SPLIT_PART and we will terminate and not finish anything '
return 1
GO

