CREATE         procedure [dbo].[A_SP_ACTUAL_PARTS_COPY_ONE]
	@newObjID nvarchar(50) OUTPUT,
	@strID nvarchar(50),
	@strNTLogin nvarchar(50),
	@copyPrefix nvarchar(50)
as
--Make a new ID for the copy
declare @newID as nvarchar(50)
exec sp_getUniqueID3 @newID OUTPUT
--Insert the new one
--INSERT INTO A_ACTUAL_PARTS_HISTORY ([ID], [LOCATION], [OBJECT_ID],[DRCM],[MODBY])
--SELECT @newID as ID, [LOCATION], [OBJECT_ID], getDate(), @strNTLogin
--FROM A_ACTUAL_PARTS_HISTORY WHERE ID = @strID
INSERT INTO A_ACTUAL_PARTS_HISTORY
([ID], [LOCATION], [OBJECT_ID], [DRCM], [MODBY], 
[NICK_NAME], [MERGABLE], [PARENT_ID], [PART_ID], 
[QTY], [SERIAL], [CUR_OWNER], [ASSEMBLY_WT], 
[AP_STATUS], [ROOT_ID], [ROOT_STATUS],[RESPONSIBLE_PERSON],[HAS_CHILD])
SELECT @newID, [LOCATION], [OBJECT_ID], getDate(), @strNTLogin,
[NICK_NAME], [MERGABLE], [PARENT_ID], [PART_ID], 
[QTY], [SERIAL], [CUR_OWNER], [ASSEMBLY_WT], 
[AP_STATUS], [ROOT_ID], [ROOT_STATUS],[RESPONSIBLE_PERSON],[HAS_CHILD] FROM
A_ACTUAL_PARTS_HISTORY WHERE ID = @strID

--find out what object id the new one got
SELECT @newObjID = OBJECT_ID FROM A_ACTUAL_PARTS_HISTORY WHERE ID = @newID
print 'The new object ID is ' + @newObjID

INSERT INTO A_ACTUAL_PART_PRODUCTS_INSIDE_LINK (ID,ACTUAL_PART_ID,PRODUCT_ID,DRCM,MODBY)
SELECT newID(),@newID,PRODUCT_ID,getDate(),@strNTLogin FROM A_ACTUAL_PART_PRODUCTS_INSIDE_LINK
	where ACTUAL_PART_ID = @strID
GO

/****** Object:  StoredProcedure [dbo].[A_SP_ACTUAL_PARTS_CASCADE_QTYS_FOR_A_PART_BY_ID]    Script Date: 6/3/2019 2:09:54 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[A_SP_ACTUAL_PARTS_CASCADE_QTYS_FOR_A_PART_BY_ID]
@mult float,
@PARENT_ID varchar(50)
AS
Declare @cID varchar(50)
Declare @cOID varchar(50)
Declare @myRoot varchar(50)
Declare @curs Cursor
set @curs = Cursor For SELECT ID,OBJECT_ID 
FROM A_ACTUAL_PARTS_HISTORY 
WHERE PARENT_ID = @PARENT_ID
open @curs
Fetch Next from @curs Into @cID,@cOID
while (@@fetch_status = 0)
Begin
	print 'Updating part ID = ' + @cID
	UPDATE A_ACTUAL_PARTS_HISTORY SET QTY = (QTY * @mult) WHERE ID = @cID
	SELECT @myRoot = ROOT FROM A_OBJECTS WHERE ID = @cOID
	Fetch Next from @curs Into @cID,@cOID
End
close @curs
Deallocate @curs
GO

/****** Object:  StoredProcedure [dbo].[A_SP_ACTUAL_PARTS_ADJUST_CHILD_QTYS]    Script Date: 6/3/2019 2:09:54 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[A_SP_ACTUAL_PARTS_ADJUST_CHILD_QTYS] 
@pID varchar(50),
@oldQty float,
@newQty float
AS
declare @curs CURSOR,@id varchar(50),@histID varchar(50),@cOldQty float,@cNewQty float
set @curs = Cursor For SELECT ID,HISTORY_REF_ID FROM A_V_ACTUAL_PARTS_APPROVED_DATA WHERE PARENT_ID = @pID
open @curs
Fetch Next from @curs Into @id,@histID
while (@@fetch_status = 0)
Begin
	SELECT @cOldQty = QTY FROM A_ACTUAL_PARTS_HISTORY WHERE ID = @histID
	SET @cNewQty = @cOldQty * (@newQty/@oldQty)
	UPDATE A_ACTUAL_PARTS_HISTORY SET QTY = @cNewQty WHERE ID = @histID
	exec A_SP_ACTUAL_PARTS_ADJUST_CHILD_QTYS @ID,@cOldQty,@cNewQty
	Fetch Next from @curs Into @id,@histID
End
close @curs
Deallocate @curs
GO

/****** Object:  StoredProcedure [dbo].[A_SP_ACTUAL_PART_UPDATE_SERIAL_FROM_SERIALIZE_TASK]    Script Date: 6/3/2019 2:09:55 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO







CREATE     PROCEDURE [dbo].[A_SP_ACTUAL_PART_UPDATE_SERIAL_FROM_SERIALIZE_TASK]
@ID varchar(50),
@taskID varchar(50),
@SN varchar(2000),
@strNTLogin varchar(50)
AS
begin Transaction
declare @curSerial varchar(50),@moveFrom varchar(50),@apHistID varchar(50),@newObjID varchar(50),@partID varchar(50),
		@parentID varchar(50), @kitSerial varchar(50),@kitPartID varchar(50)
SELECT @curSerial = SERIAL,@apHistID = HISTORY_REF_ID,@partID = PART_ID,
		@parentID = PARENT_ID
		FROM A_V_ACTUAL_PARTS_QUICK WHERE ID = @ID

select @kitSerial=serial,@kitPartID=part_id from [A_ACTUAL_PARTS_HISTORY] where object_id in
(
select parent_id from [A_ACTUAL_PARTS_HISTORY] where object_id=@ID
)

	IF NOT EXISTS(SELECT ID from PartsTransactionLog WHERE TaskId = @taskID AND PartId=@kitPartID)
			BEGIN
				INSERT INTO PartsTransactionLog(PartId,SerialNumber,CreatedDate,TaskID,PurchaseHistoryId)
				VALUES(@kitPartID,@kitSerial,GETDATE(),@taskID,@apHistID)
			END		

if isNull(@curSerial,'') = isNull(@SN,'')
BEGIN
	IF NOT EXISTS(SELECT ID from PartsTransactionLog WHERE TaskId = @taskID AND PartId=@partID)
			BEGIN
				INSERT INTO PartsTransactionLog(PartId,SerialNumber,CreatedDate,TaskID,PurchaseHistoryId)
				VALUES(@partID,@SN,GETDATE(),@taskID,@apHistID)
			END		
	goto fin
END

print 'The serial number has changed'

if @curSerial is null
	begin
		INSERT INTO PartsTransactionLog(PartId,SerialNumber,CreatedDate,TaskID,PurchaseHistoryId)
		VALUES(@partID,@SN,GETDATE(),@taskID,@apHistID)
	end
else
	begin
		IF EXISTS(SELECT ID from PartsTransactionLog WHERE TaskId = @taskID AND PartId=@partID)
			BEGIN
				UPDATE PartsTransactionLog SET SerialNumber = @SN WHERE TaskId = @taskID and PartId =@partID;
			END
		ELSE
			BEGIN
				INSERT INTO PartsTransactionLog(PartId,SerialNumber,CreatedDate,TaskID,PurchaseHistoryId)
				VALUES(@partID,@SN,GETDATE(),@taskID,@apHistID)
			END
		END	


if @parentID is null
	begin
	print 'This is a root part'
	end

if @curSerial is null
	begin
	print 'The current serial number is null'
	select @moveFrom = OBJECT_ID FROM A_V_ACTUAL_PARTS_APPROVED_DATA WHERE SERIAL = @SN AND PART_ID = @partID
	if @moveFrom is null
		begin
			UPDATE A_ACTUAL_PARTS_HISTORY SET SERIAL = @SN WHERE ID = @apHistID
			goto fin
		end
	else
		begin
			UPDATE A_ACTUAL_PARTS_HISTORY SET 
				PARENT_ID = @parentID,
				AP_STATUS = 'ap_installed',
				LOCATION = (SELECT LOCATION FROM A_V_ACTUAL_PARTS_QUICK WHERE ID = @parentID)
			WHERE OBJECT_ID = @moveFrom
			UPDATE A_ACTUAL_PARTS_HISTORY SET PARENT_ID = NULL, AP_STATUS = 'ap_available' WHERE ID = @apHistID
			exec A_SP_ACTUAL_PART_REPLACE_PART_IN_CALL @taskID,@ID,@moveFrom,@strNTLogin
			exec A_SP_ACTUAL_PARTS_DELETE_A_PART_ENTIRELY @ID,@strNTLogin
			goto fin
		end		
	end
else
	begin
	if @parentID is not null
		begin
		print 'The current serial number is not null'
		select @moveFrom = HISTORY_REF_ID FROM A_V_ACTUAL_PARTS_APPROVED_DATA WHERE SERIAL = @SN AND PART_ID = @partID
		if @moveFrom is null
			begin
				print 'We have to create a new part for this serial number ' + @SN
				exec A_SP_ACTUAL_PARTS_COPY_ONE @newObjID OUTPUT,@apHistID,@strNTLogin,null
				UPDATE A_OBJECTS SET STATUS = 'APPROVED',LOCKED_BY = NULL,LOCKED_BY_NAME = null WHERE ID = @newObjID
				UPDATE A_ACTUAL_PARTS_HISTORY SET SERIAL = @SN WHERE OBJECT_ID = @newObjID
				exec A_SP_ACTUAL_PARTS_FINISH_WF null,@newObjID,@strNTLogin
				UPDATE A_ACTUAL_PARTS_HISTORY SET PARENT_ID = NULL, AP_STATUS = 'ap_available' WHERE ID = @apHistID
				goto fin
			end
		else
			begin
				UPDATE A_ACTUAL_PARTS_HISTORY SET PARENT_ID = (SELECT PARENT_ID FROM A_V_ACTUAL_PARTS_QUICK WHERE ID = @ID) WHERE ID = @moveFrom
				UPDATE A_ACTUAL_PARTS_HISTORY SET PARENT_ID = NULL WHERE ID = @apHistID
				goto fin
			end		
		end
	else
		begin
		print 'The current serial number is not null and this is the root part'
		select @moveFrom = OBJECT_ID FROM A_V_ACTUAL_PARTS_APPROVED_DATA WHERE SERIAL = @SN AND PART_ID = @partID
		if @moveFrom is null
			begin
				print 'We have to create a new part for this serial number ' + @SN
				exec A_SP_ACTUAL_PARTS_COPY_ONE @newObjID OUTPUT,@apHistID,@strNTLogin,null
				UPDATE A_OBJECTS SET STATUS = 'APPROVED',LOCKED_BY = NULL,LOCKED_BY_NAME = null WHERE ID = @newObjID
				UPDATE A_ACTUAL_PARTS_HISTORY SET SERIAL = @SN WHERE OBJECT_ID = @newObjID
				exec A_SP_ACTUAL_PARTS_FINISH_WF null,@newObjID,@strNTLogin
				print 'Now we need to make this part ' + @newObjID + ' a part of this call'
				exec A_SP_ACTUAL_PART_REPLACE_PART_IN_CALL @taskID,@ID,@newObjID,@strNTLogin
				
			end
		else
			begin
				print 'Move the part ' + @moveFrom + ' into this call.'
				declare @oldPartStat varchar(50),@oldPartLoc varchar(50)
				SELECT @oldPartStat = AP_STATUS,@oldPartLoc = LOCATION FROM A_ACTUAL_PARTS_HISTORY WHERE ID = @apHistID
				UPDATE A_ACTUAL_PARTS_HISTORY 
					SET AP_STATUS = @oldPartStat,
						LOCATION = @oldPartLoc
					WHERE OBJECT_ID = @newObjID
				exec A_SP_ACTUAL_PART_REPLACE_PART_IN_CALL @taskID,@ID,@moveFrom,@strNTLogin
			end		
			UPDATE A_ACTUAL_PARTS_HISTORY 
				SET AP_STATUS = 'ap_available',LOCATION = NULL
				WHERE ID = @apHistID
			print 'Now we need to check and see if we should delete the part because it was a temp part and this is the only place it was used at.'
			exec A_SP_ACTUAL_PARTS_DELETE_A_PART_ENTIRELY @ID,@strNTLogin
		end

	end
	





fin:
if @@trancount > 0 COMMIT TRANSACTION
print 'Finished A_SP_ACTUAL_PART_UPDATE_SERIAL_FROM_SERIALIZE_TASK with no errors'
return 0

PROBLEM:
if @@trancount > 0 	ROLLBACK TRANSACTION
print ' There was a problem in A_SP_ACTUAL_PART_UPDATE_SERIAL_FROM_SERIALIZE_TASK and we will terminate and not finish anything '
return 1
GO

/****** Object:  StoredProcedure [dbo].[A_SP_ACTUAL_PART_UPDATE_MY_CHILDREN_PARTS]    Script Date: 6/3/2019 2:09:55 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE  PROCEDURE [dbo].[A_SP_ACTUAL_PART_UPDATE_MY_CHILDREN_PARTS]
@ID varchar(50)
AS
declare @histRefID varchar(50),
@name varchar(50),
@modby varchar(50),
@oStat varchar(50),
@apStat varchar(50),
@locID varchar(50),
@objID varchar(50)
CREATE TABLE #TempIs	(IT varchar(50),HISTORY_REF_ID varchar(50))
INSERT INTO #TempIs(IT,HISTORY_REF_ID) SELECT ID,HISTORY_REF_ID FROM A_V_ACTUAL_PARTS_APPROVED_DATA WHERE PARENT_ID = @ID

print 'In here'


SELECT @histRefID = HISTORY_REF_ID FROM A_ACTUAL_PARTS WHERE ID = @ID
print 'The history ID = ' + isNULL(@histRefID,'NULL')
SELECT @apStat = AP_STATUS, @locID = LOCATION, @objID = OBJECT_ID 
	FROM A_ACTUAL_PARTS_HISTORY 
	WHERE ID = @histRefID
SELECT @oStat = STATUS FROM A_OBJECTS WHERE ID = @objID
	if @oStat = 'APPROVED'
		begin
		print 'This is an approved one, so I am going to update all the children'
		declare @tester varchar (50)
		SELECT @tester = ID FROM A_V_ACTUAL_PARTS_APPROVED_DATA WHERE PARENT_ID = @ID
		if @tester is null goto fin
		print 'making a cursor to go through the childs'
		Declare @it varchar(50),@hist varchar(50)
		Declare @curs Cursor
		set @curs = Cursor For SELECT * FROM #TempIs
		open @curs
		Fetch Next from @curs Into @it,@hist
		while (@@fetch_status = 0)
		Begin
			print 'Updating Child = ' + @hist
			UPDATE A_ACTUAL_PARTS_HISTORY SET LOCATION = @locID WHERE ID = @hist
			EXEC A_SP_ACTUAL_PART_UPDATE_MY_CHILDREN_PARTS @it
			Fetch Next from @curs Into @it,@hist
		End
		close @curs
		Deallocate @curs		
		end


return(0)
fin:
print 'Fin'
return(0)
GO

