CREATE  PROCEDURE [dbo].[A_SP_ACCOUNTS_DELETE]
@id nvarchar(50),
@strNTLogin nvarchar(50)
AS
DELETE FROM A_ACCOUNTS_HISTORY WHERE ID = @ID
GO

