CREATE PROCEDURE [dbo].[A_SP_ACCOUNT_GET_LATEST_INVOICE_DATA]
@acctID varchar(50),
@modby varchar(50)
AS
declare 
@lastInvoiceDate datetime,
@lastInvoiceAmt money,
@paymentDueDate datetime,
@paymentsSinceInvoice money,
@currentBalance money

print 'Getting the latest invoice data for account # ' + @acctID
SELECT top 1 @lastInvoiceDate = INVOICE_DATE,
	@lastInvoiceAmt = TOTAL_DUE,
	@paymentDueDate = DUE_DATE
	FROM A_ACCOUNT_INVOICES WHERE ACCOUNT_ID = @acctID AND STATUS = 'INVOICED' ORDER BY INVOICE_DATE DESC

SELECT @paymentsSinceInvoice = PAYMENT_AMOUNT,
	@currentBalance = TOTAL_DUE
	FROM A_ACCOUNT_INVOICES WHERE ACCOUNT_ID = @acctID AND STATUS = 'CREATING'

SELECT @lastInvoiceDate AS LAST_INVOICE_DATE,@lastInvoiceAmt AS LAST_INVOICE_AMOUNT,@paymentDueDate AS  PAYMENT_DUE_DATE,
	@paymentsSinceInvoice AS PAYMENTS_SINCE_INVOICE,@currentBalance AS CURRENT_BALANCE,
	@acctID AS ACCOUNT_ID
GO

/****** Object:  StoredProcedure [dbo].[A_SP_ACCOUNT_FIGURE_TOTALS]    Script Date: 6/3/2019 2:10:13 PM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO



CREATE  PROCEDURE [dbo].[A_SP_ACCOUNT_FIGURE_TOTALS]
@acctID varchar(50),
@modby varchar(50)
AS
UPDATE A_ACCOUNTS_HISTORY SET 
INVOICED_BALANCE = (SELECT SUM(AMOUNT) FROM A_ACCOUNT_INVOICE_ITEMS_WITH_ACCT_AND_STATUS WHERE
	ACCOUNT_ID = @acctID AND STATUS IN ('INVOICED','SENT_TO_CUSTOMER','CLOSED')),
TOTAL_CREDITS = -(SELECT SUM(AMOUNT) FROM A_ACCOUNT_INVOICE_ITEMS_WITH_ACCT_AND_STATUS WHERE
	ACCOUNT_ID = @acctID AND AMOUNT < 0),
TOTAL_DEBITS = (SELECT SUM(AMOUNT) FROM A_ACCOUNT_INVOICE_ITEMS_WITH_ACCT_AND_STATUS WHERE
	ACCOUNT_ID = @acctID AND AMOUNT > 0),
TOTAL_TAX = (SELECT SUM(TAX) FROM A_ACCOUNT_INVOICE_ITEMS_WITH_ACCT_AND_STATUS WHERE
	ACCOUNT_ID = @acctID),
UNINVOICED_BALANCE = (SELECT SUM(AMOUNT) FROM A_ACCOUNT_INVOICE_ITEMS_WITH_ACCT_AND_STATUS WHERE
	ACCOUNT_ID = @acctID AND STATUS IN ('CREATING')),
BALANCE = (SELECT SUM(AMOUNT) FROM A_ACCOUNT_INVOICE_ITEMS_WITH_ACCT_AND_STATUS WHERE
	ACCOUNT_ID = @acctID)

WHERE ID IN (SELECT OBJ_ID FROM A_OBJECTS WHERE ROOT = @acctID)
GO

